/* 平成27年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h27.committeeSessions.push(...[{"id":"h27-20150310-3","meetingId":"h27-c-budget","date":"2015年3月10日","dateIso":"2015-03-10","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時２７分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を161件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２７年度品川区一般会計予算","agenda":"平成２７年度品川区一般会計予算","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"私は、３０３ページの駅周辺等放置自転車対策事業、放置防止指導啓発、そして３３１ページの子ども達のアイデアを活かした公園整備についての確認をします。子ども達のアイデアを活かした公園整備からお伺いいたします。子ども達のアイデアを活かした公園づくりの経緯を確認させていただきたいと思います。詳しい経緯と遊びのアイデアの内容をまずお願いいたします。","respondent":"多並公園課長","answer":"委員が今ご紹介いただきましたとおり、子ども達のアイデアにつきましては、平成２０年策定の基本構想の中で、次代を担う子どもたちが主役となって公園づくりをしていこうという観点でワークショップを進めながらつくっていったものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"横山委員","kind":"質問","question":"荏原南公園ということで、今回、第４号となるわけですが、第１号の鮫洲運動公園、第２号の二葉公園、第３号の東品川公園、それぞれの公園の特徴と、遊具の設置例、そして現在の状況を教えてください。","respondent":"多並公園課長","answer":"これまでの子ども達のアイデアにつきましては、まず、鮫洲運動公園につきましては、一番象徴的なのが全方向すべり台といいまして、なかなか普通では発想できないような遊具、今も子どもたちの人気になっているすべり台があります。","voiceIndex":6,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"荏原南公園でも、例えば近隣の第二延山小学校に協力を得ながら、３年生から５年生の児童へのアンケートの実施ですかと、ミニワークショップの開催によって、実際に公園を利用する子ども達の考えを聞き、その結果を活かして設計を検討していただきたいと要望いたしますが、区のお考えをお聞かせください。","respondent":"多並公園課長","answer":"平成２８年度以降に工事の予定をしていますが、まずは荏原南公園につきましては、さまざまな方がご利用いただく、また、荏原地区でも非常に貴重な広い空間ということがありますので、地元のご利用の実態だとか、また、ご意見を踏まえながら進めるということで。","voiceIndex":8,"id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"今お話にもあったのですけれども、荏原南公園は地域の核となる公園です。お子さんから高齢者まで幅広い年齢層の地域の方々のご利用があり、さまざまなご要望が出てくるかと思います。公園利用者や町会とのワークショップの開催、または住民説明会の実施などによって、ぜひ地域の幅広い層の方々の声を積極的に取り入れて、状況を勘案しながら総合的に整備の内容を検討していただきたいと考えています。","respondent":"多並公園課長","answer":"住民説明会、地元のご意見を聞く件です。以前この荏原南公園につきましては、直近ですと平成４年に改修したところです。このときも説明会を開きながら、地元のご意見をお聞きし、公園整備の内容を決定する際もきめ細かく聞きながら進めたところです。","voiceIndex":10,"id":"exchange-004"},{"speaker":"横山委員","kind":"質問","question":"地元との丁寧なやりとりですとか、他部署との連携をぜひお願いしたいと思います。防災機能につきましてもお伺いいたします。防災かまどベンチ、防災収納ベンチ、防災トイレベンチ、仮設シェルターになるような防災遊具、ソーラー照明など、防災機能をつけてほしいというような地域の声がありますが、その辺も区のお考えをお聞かせください。","respondent":"多並公園課長","answer":"そのような観点からも、かまどベンチですとか、マンホールトイレ等、必要なところを地元のご意見をお伺いしながら進めていきたいと思ってあります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"横山委員","kind":"質問・要望","question":"駅周辺等放置自転車対策事業、放置防止指導啓発についてお伺いいたします。以前、松澤委員より戸越銀座のバリケードの事例、また、過去にはほかの委員の方々から、マナー向上のための子どもの絵による路面シート、看板、花壇の設置などの事例が紹介されておりますが、計画的かつ効果的な放置自転車対策を強く要望いたします。放置している方へのアンケートや聞き取り調査は実施しておりますでしょうか。","respondent":"田口交通安全担当課長","answer":"ただ、現在の利用料金がこのまま続くということではなくて、これも今後の推移を見ながら検討していきたいと思います。したがって、今すぐ割引云々ということはございませんが、引き続き、利用料金、またその他のサービス等もあわせて検討していきたいと考えています。","voiceIndex":14,"id":"exchange-006"},{"speaker":"横山委員","kind":"質問・要望","question":"角ということで、緊急車両が通ったりですとか、事故の面ですとか、早急に対策をしていただきたい、そういった箇所です。割引ですとか、利用料金の面、サービスの面というところでご検討いただいているかと思いますけれども、何か少しでも、一歩でも進めるようなことがございましたら、ぜひお願いしたいと思います。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"私からは、３３８ページ、建築行政費、３３３ページ、都市防災まちづくり事業費、３０７ページ、職員給与費、３４３ページ、空き家等対策事業についてお伺いいたします。","respondent":"鈴木建築課長","answer":"感震ブレーカーについてのご質問です。感震ブレーカーの設置促進の動きにつきましては、国の中央防災会議等々、今、委員ご指摘いただいた検討の方向性については承知しています。","voiceIndex":18,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"今、若干ご答弁をいただきましたが、品川区として同ガイドラインの趣旨、木密地域から優先的に設置が求められている点、また、大火災を防ぐ鍵として、自治体に対しても既存の木造住宅への普及、こうしたことが指摘されていることなども含めて、改めて感震ブレーカー等の普及促進を今後区としてどのように進めていくのか、改めてお知らせいただきたいと思います。","respondent":"鈴木防災課長","answer":"その成果を踏まえまして、区としましても、感震ブレーカーの一定程度の有効性、また、そのときに必要な課題を把握しておりますので、トータルで区民の方の防災に役立つ情報の提供、啓発をしっかりと進めていきたいというふうに考えているところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"次にいきたいと思います。職員給与費です。それに絡んでという観点ですが、昨年の７月から道路法施行規則の改正に基づいて、５年ごとの近接目視の点検を行うよう義務づけられておりますが、この間、品川区の議事録を確認しますと、品川区は橋梁長寿命化修繕計画に基づいて、平成２５年度に２回目の点検を行って、今年度、平成２６年度中に修繕計画の見直しをする、こういうふうにご答弁がありました。","respondent":"稲田道路課長","answer":"橋梁長寿命化の点検です。７月１日より、委員ご指摘のように５年に一度の点検を義務づけられたものの中に橋梁が含まれております。この橋梁について、私どもでは点検を平成２５年度に実施しました。","voiceIndex":22,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"ちょっと点検の仕方とかが違うのか、その辺も知りたかったのですが、結構です。その上で、今ご答弁いただいた点検を直接区の職員が行っているのかどうか、これも教えてください。","respondent":"稲田道路課長","answer":"この業務におきましては、橋梁点検の業務委託を、点検委託を行っております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"つる委員","kind":"質問","question":"今後、さまざまな形で公共施設の修繕また改善が必要になってくるわけですので、その観点で人材の育成、またその確保というところも教えていただければと思います。","respondent":"稲田道路課長","answer":"ただ、専門的なところになりますと非常に弱い部分も確かにあることはあります。近年ですけれども、経験者採用を大分進めておりまして、橋梁の設計や工事の経験を持った者が入ってきております。","voiceIndex":26,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問・要望","question":"今、品川区では、区の技術会議で育成に取り組まれているということで、非常にそれは力を入れてやっていただきたいと思っています。その上で、委託も含めて、また、庁内の職員の力をつけていただくという観点も含めて、また改めて質問させていただきたいのですが、国土交通省で昨年の１１月にインフラの点検・診断に役立つ技術や知識を身につけることができる民間資格の登録制度が創設されたと思います。","respondent":"稲田道路課長","answer":"委員ご指摘の資格等々の活用につきましては、その資格を取った者とかは現在はおりませんけれども、国土交通省が開催する橋梁点検の研修等が実施されております。そういう場面に積極的に職員を派遣して橋梁点検の技術を習得するというところは現在も行っております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"最後に、空き家対策事業です。時間の関係上、あわせて聞かせていただきますが、平成２７年度で空き家活用モデル事業の実施とありますけれども、その具体的な内容を改めて教えていただきたいのと、今後の活用法の１つとして、立地によっては、保育園の周辺などでは、活用できるようなところがあれば、代替地として園庭に活用なども検討できると思いますが、あわせてその辺のご認識をお知らせください。","respondent":"矢木住宅担当課長","answer":"平成２７年度におきますモデル事業の内容ですが、こちらは既にプレスリリースで発表のとおり、少なくとも１軒の空き家につきまして、公的利用ないしは公共利用して、その中でさまざまな状態ですとか管理体制、どういった方と協働していくか。","voiceIndex":30,"id":"exchange-014"},{"speaker":"松永委員","kind":"質問","question":"本日は、３０３ページのスタントマンを活用した自転車安全教室について、３２７ページの日本庭園おもてなし事業について、３４３ページの空き家等対策事業について伺いたいと思います。近年、自転車での事故、また交差点での事故が多発しております。昨年も多くの地区や学校で執り行われたと聞いておりますが、昨年はどのような場所で行われ、また、何回実施されているのか教えてください。","respondent":"田口交通安全担当課長","answer":"スタントマンを使いましたスケアードストレイトという安全教育になります。これは昨年、小学校また中学校、それと西大井広場公園、こういったところで実施しております。対象につきましては、学校の生徒のほかにも、会場付近の住民の方にも参加をいただいて行ってあります。","voiceIndex":33,"id":"exchange-015"},{"speaker":"松永委員","kind":"質問","question":"これは毎年８回ということでよろしいのでしょうか。１回行うに当たって、例えば小学校なら小学生対象だと思うのですけれども、公園だと地域の町会の方々とかがお見えになられると思うのですが、その中での参加者の年齢層がわかったらぜひお願いしたいと思います。","respondent":"田口交通安全担当課長","answer":"通常の安全教育よりも非常にインパクトの強い安全教育ですので、この辺は今後検討させていただきたいというように考えてあります。それと、参加者の年齢ですが、これは非常に幅広くて、子どもから高齢者まで幅広い年齢層の方に来ていただいているという状況です。","voiceIndex":37,"id":"exchange-016"},{"speaker":"松永委員","kind":"意見","question":"このように品川区では現場を再現した教室を行っているということで、事故件数も減ってきていると思います。他区でもそうしたスタントマン教室を活用して取り組んでいると思いますが、まだまだ周知されていないところもあります。そこで、この教室を１回行うに当たっての費用等がわかりましたら、よろしくお願いいたします。","respondent":"田口交通安全担当課長","answer":"大体２７万円ぐらいです。","voiceIndex":39,"id":"exchange-017"},{"speaker":"松永委員","kind":"質問","question":"品川区では、そうした中で平成２５年は事故件数が９３９件と年々減少してきております。そこで品川区ではそうした中間層の事故件数を減らすために、どのような取組みを行っていくのでしょうか。昨年も小学校、自治会等で公園等で行っていると思いますけれども、その対策について伺いたいと思います。","respondent":"田口交通安全担当課長","answer":"そこで今回、５月に大崎駅西口のシンクパークタワー前、こちらのほうで実際に公道上でスタントマンを使った交通安全教室を実施する予定です。時間がちょうどお昼の時間帯ということで、サラリーマンが行き来する時間帯です。","voiceIndex":41,"id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"日程等わかりましたら、ぜひよろしくお願いします。そうした中で、事故を減らすためのヒヤリハット地図について伺いたいと思うのですけれども、このヒヤリハット地図というのは、どういった形で周知方法をされているのか。ヒヤリハットとされている場所について、箇所数が増えたりとか減ったりとかされるとは思うのですけれども、それについて伺いたいと思います。","respondent":"田口交通安全担当課長","answer":"学校に対しても事前に説明を行い、有効に活用していただくということで実施をしています。箇所が減ったり増えたりですが、これは警察署また各学校、町会・自治会等から危険箇所、ここは危ないという情報をいただいております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に、この件に関して要望ですが、地元の南大井４丁目８番１４号の交差点付近なのですけれども、点滅信号が赤と黄色になっているのですけれども、実は昨年もそこで自転車と車の事故があり、そうした中で近くには学校がありまして、とても危ないところなのですけれども、ぜひそうしたわかりやすいような看板、ここは危険地点とか、それとも黄色を赤の点滅に。","respondent":"田口交通安全担当課長","answer":"現場を実査して、詳しく調査した上で対応させていただきたいと考えております。","voiceIndex":45,"id":"exchange-020"},{"speaker":"松永委員","kind":"質問","question":"３２７ページの日本庭園おもてなし事業について伺います。東京の日本庭園おもてなし協議会に池田山公園が参加していると伺っておりますが、現在、池田山公園には年間どれくらいの人数が訪れているのか、また、どういった方が見学されているのか伺いたいと思います。","respondent":"多並公園課長","answer":"池田山公園の件です。池田山公園の現在の利用者数という捉え方は、現在、データとしてございませんが、訪れている方は、区民はもとより、あとは観光客がねむの木の庭とあわせて見に来ていただいたり、いろいろな方々に現在見に来ていただいている状況です。","voiceIndex":47,"id":"exchange-021"},{"speaker":"松永委員","kind":"質問","question":"今後、改修工事を行って、現在より魅力ある公園に生まれ変わろうとしております。外国人観光客にも対応した多言語表示板設置が行われると伺っておりますが、このプレス発表には、多言語表示等とありますが、この「等」について伺いたいと思います。","respondent":"多並公園課長","answer":"この「等」につきましては、多言語化の案内板だけではなくて、いろいろなサイン類がありますので、そこら辺も含めながら全体的に外国人の方々がわかりやすいような表示というものを考えているため、「等」とさせていただいたところです。","voiceIndex":49,"id":"exchange-022"},{"speaker":"松永委員","kind":"質問","question":"この池田山公園に関しては、今現在、入園料は受け取っていないということでございまして、新たに改修工事を行って、とてもきれいになると思いますが、今後も無料で楽しむことができるのでしょうか。開園時間についてですが、９時から１７時までとなっております。９時からではなくて、少し早めることはできないでしょうか。あわせて伺いたいと思います。","respondent":"多並公園課長","answer":"今後もそのようなところを含めながら、より実態に合わせた形に、必要であればもちろん見直していくところですけれども、現在のところはそのような形で進めたいと思ってあります。","voiceIndex":51,"id":"exchange-023"},{"speaker":"松永委員","kind":"質問","question":"３４３ページの空き家対策事業について伺います。平成２６年度に実施されている空き家等実態調査ですが、その結果がどうなったのか。この空き家等対策の「等」についても伺いたいと思います。","respondent":"矢木住宅担当課長","answer":"平成２６年度に実施しました実態調査の結果ですが、アンケートを発送いたしまして、現在、詳細を集計中です。","voiceIndex":53,"id":"exchange-024"},{"speaker":"松永委員","kind":"意見","question":"この「等」というのは、いわゆる物品等堆積家屋、俗に言うごみ屋敷と言われている部分ではありますけれども、区内にどのくらいのごみ屋敷があるのか、ごみ屋敷と呼ばれる基準がありましたら、お願いいたします。","respondent":"矢木住宅担当課長","answer":"ごみ屋敷として実態調査の中から浮かび上がってきたものは２２件あります。内容といたしましては、委員ご指摘のとおり、条例に基づいて、例えば、ごみが堆積していますとか、あと雑草が繁茂していますとか、そういう状態のものを差します。","voiceIndex":55,"id":"exchange-025"},{"speaker":"松永委員","kind":"質問・要望","question":"最後に、品川区ではいろいろな措置をされて、最終的には代執行という運びになると理解しておりますが、所有者の方が解体したいという要望があったときに、その費用についてはいかがでしょうか。","respondent":"矢木住宅担当課長","answer":"こちら、除却費用につきましては、当然のことながら私どもの耐震事業ないしは木密事業といった事業で助成があるものです。","voiceIndex":57,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"３２５ページの地域交通検討会経費を伺いたいと思います。委託会社を伺いたいと思いますが、平成２５年度、平成２６年度、そして今回の平成２７年度の委託会社がどこか伺います。そして、この公共交通ネットワークを検討とは、区内全域か、または特定地域なのか、ここを伺いたいと思います。そして、この間、コミュニティバスの運行を求めてきましたが、早く実施してほしいと思います。いかがでしょうか。","respondent":"中村都市計画課長","answer":"コミュニティバスについてですけれども、これは昨年も１０月にバスの事業者に働きかけを行ったところですけれども、やはり依然として既存路線の増便ですとか、あるいはバス停を増やすといったようなことにつきましては、非常に多額の費用がかかるということで。","voiceIndex":60,"id":"exchange-027"},{"speaker":"中塚委員","kind":"質問","question":"つまり、一体どんな要因なのか、どんな考慮すべき事情があるのか、区の認識を伺いたいと思います。既に品川区は交通不便地域を１１カ所認めています。この間、疑問なのは、交通不便地域を解消する必要があると区は考えているかどうかです。その手段はさまざまあると思いますが、問題は、１１カ所の交通不便地域を解消する必要があると品川区は考えているのかいないのか、そこを伺いたいと思います。","respondent":"中村都市計画課長","answer":"特にその中で調査に当たりましては、鉄道駅は７００ｍ、またバス停からは３００ｍということで、十分歩いていける距離だというふうに認識をしています。","voiceIndex":62,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"この間、コミュニティバスを求めてきましたけれども、例えば民間ができないのであれば、だからこそ自治体がコミュニティバスを運行する必要があるのだと私は思います。先ほど伺ったのは、区が認める１１カ所の交通不便地域を何らかの方法で解消する必要がある地域だと区は考えているのか、ここを伺いたいと思います。","respondent":"中村都市計画課長","answer":"そういった意味からしますと、やはり物理的に公共交通機関が通行することが難しい道路幅員ですとか、そういった場合には、やはりバリアフリーの観点から道路を歩きやすくするとか、総合的な見地から改善を進めていく必要があると、このように認識しています。","voiceIndex":64,"id":"exchange-029"},{"speaker":"中塚委員","kind":"質問","question":"交通不便地域とは、区も認める区民にとって不便な地域です。もちろんバリアフリーは大事です。そもそもこの不便地域とは、駅やバス停からの距離が基準です。こうした社会的要因も不便を計る要因としてしっかり位置づけるべきではないかと思いますが、この点伺いたいと思います。距離以外にも移動に不便な要素、要因を位置づけて検討すべきではないかと思いますけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"既存の公共交通機関を使って移動する場合に、ご自宅から目的地へ行くに当たりましては、これはどのような場合でも乗換えは避けられないというふうに考えております。やはりダイレクトに目的地に行くニーズに応えるというのは、現実的には難しいです。","voiceIndex":66,"id":"exchange-030"},{"speaker":"中塚委員","kind":"質問","question":"私が指摘をしたのは、お年寄りにとって不便な移動とは、決して距離だけでは計れない、さまざまな要因があるでしょうということです。品川区自身も高齢者人口増など社会的要因を考慮と認めております。これを距離だけで計るのではなく、そういった要素が必要ではないかと、移動に不便な要素をしっかり位置づけるべきではないかと思いますけれども、この点改めて伺いたいと思います。","respondent":"中村都市計画課長","answer":"今、民間の事業者に働きかけを行っていくと同時に、少しでも道路あるいは公共機関、駅やバス停、そういったものを利用しやすいようにすること、まずそこが一番最初にやるべきことだというふうに認識しています。","voiceIndex":68,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問","question":"自宅から目的地までの移動の不便にしっかり目を向けるべきだと思います。このルートは必要で、私は需要があると思います。こうした移動確保がお年寄りの生活圏確保につながることと思いますけれども、この点を伺いたいと思います。そして、区民が不便に感じているルート、移動はどこなのか、生活に必要なルートを把握して、コミュニティバスを運行すべきだと思いますけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"バスの路線を延長する場合も、バス停を１カ所設置して延長する場合でも、１,０００万円以上の費用がかかるということで、そういったところから、現在の経営状況では、赤字の路線を黒字の路線で埋めてぎりぎりの経営状態というところでは、なかなかそこまで。","voiceIndex":70,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"事業者が困難だからこそ自治体が税金を使ってコミュニティバスを運行し、お年寄りの生活圏確保や社会参加を支援する役割がそこにあると思います。ぜひ運行を検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"それと、３０９ページの自転車走行環境整備詳細調査委託なのですけれども、これはすごく私、印象あるのですけれども、前のまちづくり部門の部長は、毎回の答弁で、品川区は駅が歩いて１０分ぐらいのところにあるから自転車でというのは推奨していなかったはずで、私はそういう答弁だったのがとても印象にあるのですけれども、いつからこのように方向転換をしたのでしょうか。その辺もお伺いします。","respondent":"矢木住宅担当課長、稲田道路課長、溝口都市開発課長","answer":"平成２７年度につきましては、５棟を返還する予定です。これからも引き続き、特優賃につきましては、借上期間満了後に粛々と返還予定です。出ますけれども、それを何とか効果的に流れるような形で、歩行者におきましては仮設の迂回ルートとかを設けることも考えまして、今後。当然、観光施策を担っている部署がありますので、そちらとの連携も図りながら、今後、大崎駅西口、また大崎駅周辺をどのようなまちづくりにしていくのか。","voiceIndex":74,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問・要望","question":"それと、自転車については、わかったようでよくわからないのですけれども、方向転換したというのは、私はエコという意味でもいいと思うのですけれども、これからやるわけですから、詳細を調査した後に、区においては自転車の施策はやっていただいておりますが、その辺の効果を期待しておりますので、答弁を改めていただきたいと思います。その辺のお答えもいただきたいと思います。","respondent":"稲田道路課長、溝口都市開発課長","answer":"自転車走行レーンの詳細調査等、今後の効果的な運用です。まさしくご指摘のとおりでございまして、来年度に詳細を調査して、適所に設置しながら、その効果等も検討していきたいと考えています。そういった中では、商業・観光施策をやっています部署、またはオリンピック・パラリンピック、そういった人が集まるところも契機になりますので、そういったことも含めてしっかり連携しながらつくった施設を生かしていきたい。","voiceIndex":78,"id":"exchange-035"},{"speaker":"沢田委員","kind":"質問","question":"３０３ページの駅周辺等放置自転車対策事業で自転車のシェアリングについて、それから３４１ページの崖・擁壁実態調査委託、３２９ページの東品川公園土壌改良工事、それから３２５ページの特定整備路線沿道まちづくり推進費についてお伺いします。今後、自転車シェアリングについては、どういうふうに考えられているのかお聞かせください。","respondent":"田口交通安全担当課長","answer":"自転車シェアリングですが、以前に大崎駅で民間ボランティア団体を通じて実施したことがあると伺っております。結果的には二、三カ月で廃止になったと聞いてあります。","voiceIndex":82,"id":"exchange-036"},{"speaker":"沢田委員","kind":"質問・要望","question":"なかなか放置自転車対策にならない部分があるということでしたけれども、観光という部分でも、２０２０年のオリンピック・パラリンピックに向けて、やはり環境にやさしい交通手段として自転車を積極的に活用していくまちづくりを、自転車走行レーンとか、そういったこともですけれども、しっかりと進めていく必要があるのかと思いますので、また検討を進めていっていただきたいと思います。","respondent":"鈴木建築課長","answer":"１年目にそういったデータを活用して、区内にどれくらいの数があるかというところを把握して、その数を１年、２年かけて分けて行っていくという予定です。それから、調査後の所有者等に対する指導あるいは改修に対する支援策ですが、調査におきましては、目視の調査が主体です。","voiceIndex":84,"id":"exchange-037"},{"speaker":"沢田委員","kind":"質問・要望","question":"本当に所有者の方等にしっかりと危険性を認識していただいて、また調査をしていただきたいと思います。地域で本当に所有者が、これは空き家のこともそうですけれども、空き家と一緒になっている擁壁のある家のところで、地域の方がなかなか持ち主の方がわからないということもありましたので、しっかりとそういった対応をしていっていただきたいと思います。","respondent":"多並公園課長","answer":"スケジュールとしましては、来年度中の工事を予定していますが、１日も早く終わるよう、現在、設計作業の中でできないか検討しています。","voiceIndex":86,"id":"exchange-038"},{"speaker":"沢田委員","kind":"質問・要望","question":"１日も早く東品川公園の整備ということでやっていただきたいと思っているのですけれども、特に弓道場とテニスコートがありまして、テニスというのはあちこちやれるところがあるのですけれども、弓道場は品川区内に１つしかないもので、本来は半年で、夏から秋、春までの間でできるはずだったのが、１年半、弓道場が使えないということで、本当に厳しい状況であります。","respondent":"安藤文化スポーツ振興課長","answer":"そんな中で１つの代替施設として、今ご指摘のＪＲの跡地にもあるという情報をつかんでいますので、そことのパイプを持っている関係部署または関係機関と調整をして、今現在、開放に向けて鋭意努力をしています。","voiceIndex":88,"id":"exchange-039"},{"speaker":"沢田委員","kind":"質問・要望","question":"三ツ又の交差点のところは、五叉路になっていますし、見ていただくと、当時、子どもの通学路があるということで設置されたかと思うのですけれども、ほとんど使われていることもないということで、ぜひともそういったところから歩道を広げるということもありますし、高齢者の方が歩きやすいまちづくり、障害者の方が歩きやすいまちづくりを進めていくという観点からも。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"私からは、３２９ページ、東品川公園土壌改良工事、３４３ページ、空き家等対策事業、３０９ページ、道路安全施設費、３１３ページ、大井町駅周辺バリアフリー工事費について伺います。よろしくお願いします。今回、一般質問させていただきましたので、それに沿って伺います。昨年の条例の成立で、この４月からの施行だと思うのですけれども、その後、問い合わせが増えているのかどうか。","respondent":"矢木住宅担当課長","answer":"条例制定後の問い合わせの内容ですが、多い少ないはありますが１日一、二件ほどあります。","voiceIndex":94,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問","question":"先ほど、質疑の中で、約１,７００軒の空き家の所有者に対してアンケートを利活用も含めてとったということでしたけれども、クロス集計で２万件で、自治会、町会に問い合わせして６００件ぐらい上がってきたという話は聞いているのですが、この約１,７００軒はどうやって抽出して送られたのか教えてください。","respondent":"矢木住宅担当課長","answer":"こちらの約１,７００軒の抽出方法ですが、まず、区内全域に実態調査をかけまして、外観から空き家と思われるものにつきまして、登記簿謄本で所在を確認し、所有者にアンケートを送付したものです。","voiceIndex":96,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"確認","question":"昨年調査をされて、では、約１,７００軒全て登記簿謄本をとられて所有者を確認されたということで、本当に大変なことだったと思います。この前、区長のご答弁をいただいて、さまざまな手段を使ってやっていく、こういうご答弁をいただいていますけれども、そのほかで何かあれば教えてください。","respondent":"矢木住宅担当課長","answer":"パンフレットができ次第、所有者の方々に対して、空き家対策条例の周知、また同時に支援、有効活用についても情報提供を郵送で行う予定です。","voiceIndex":98,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"確認","question":"確認ですけれども、それは先ほどの約１,７００軒の方に個別に送られるということですか。","respondent":"矢木住宅担当課長","answer":"その予定です。","voiceIndex":100,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"この前の一般質問で、相談窓口の設置についてお伺いしたところ、区長からご答弁いただいて、品川区ではこの４月から空き家対策担当を新たに設けるという、このようなご答弁を頂戴しました。これは空き家対策担当の相談の係を立てるということでしょうか。もしそうであれば、名称とか人員配置、またその役割についてもう少し詳しく教えてください。","respondent":"矢木住宅担当課長","answer":"この４月から、空き家対策担当主査という部署を設置いたしまして、こちらは住宅運営担当と兼ねておりますが、人員体制につきましては、主査１名、係員２名という体制で、住宅運営担当と共同でやる形になります。","voiceIndex":102,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問","question":"世田谷区とかほかの自治体では、民間企業やＮＰＯに委託して行っておりますが、こうした専門機関の設置について、品川区はどのようにお考えでしょうか。","respondent":"矢木住宅担当課長","answer":"こちらの有効活用につきましては、まず当面は職員による相談を行っていく予定としておりますが、ただし、その相談内容、あるいは量的なもの、そういったものを総合的に検討いたしまして、どういった相談内容かによって。","voiceIndex":104,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"質問","question":"３０９ページ、道路安全施設費で、これは毎回やるのですが、生活道路の交通安全対策、ゾーン３０について伺いたいと思います。最近、北品川の三丁目のあたりでも新たに追加になっていましたが、品川警察署がそこをゾーン３０に指定をした理由、また、いつ追加になったのかの経緯、また規制標識、路面表示などは、区と都でどのような割り振りで設置をされたのか教えてください。","respondent":"田口交通安全担当課長、稲田道路課長","answer":"ここを設置した経緯です。品川警察署に確認をとりましたが、やはり学校があるということで地元住民の要望が強かったということで設置したと聞いてあります。警察と私どもの道路管理者の割り振りですが、警察のほうでは、ゾーン３０エリアを設定した暁には、標識を設置するです。我々、道路管理者としては、路面表示で「ゾーン３０」というものを今回の場合は施工しております。","voiceIndex":106,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問","question":"品川学園、そして品川女子学院がここにあるということで、通学路とかぶることから生活道路の交通安全対策をやられたということだと思うのですが、これでゾーン３０が区内８カ所になりましたけれども、品川警察署管内の話なのですが、ほかの３警察署、大井、大崎、荏原、ここでも指定をしていく予定があるのかどうか、もしご存じであれば教えてください。","respondent":"田口交通安全担当課長","answer":"現在、把握しているところでは、大崎署管内、池田山地区になると思いますが、１カ所設置する予定だと聞いております。","voiceIndex":109,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そうですか。以前にもそんな話があったと思うのですが、なったのですか、わかりました。一目見ただけで、ここはゾーン３０とわかるような感じになっています。このあたり、これは警視庁との関係もありますが、世田谷区は警視庁と協力して区でやっているのですが、ぜひこのあたりを取り組んでいただきたいと思いますが、いかがでしょうか。","respondent":"田口交通安全担当課長","answer":"隣の大田区でも、東谷口に１カ所設置をしております。こうしたことも区内の各４警察署と協議をしながら、周知ということは非常に大事なことだと思いますので、今後も継続して協議を進めていきたいと考えております。","voiceIndex":111,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"非常にすばらしい内容だと本当に思っています。特に、先日、歳入のところで鈴木真澄委員からもありましたけれども、南品川シルバーセンター、これも大井町からの生活関連経路ということで、これも入っているということで、手すりの設置についても検討していただける、これは前々から地域のご要望が多かったので非常にありがたいと思っています。２点お伺いします。トイレのことについて伺います。","respondent":"中村都市計画課長","answer":"このトイレを設置するにはテナントの契約ですとか、あるいは、設置に当たりまして、設備の配管の関係上、やはり上下階の他の店舗にも影響を及ぼすということで、大変な工事とは思いますけれども、これも引き続き、設置のお願いをしてまいりたいというふうに考えてあります。","voiceIndex":115,"id":"exchange-050"},{"speaker":"向委員","kind":"質問","question":"よくある、メールアドレスを登録して、それなりに時間を区切って、例えば１５分とか３０分とかに区切っての利用になるのかどうか、そのあたりをお伺いしたいのと、イルミネーションのほうなのですけれども、５,０００万円ということで結構予算がついていると思うのですが、これはあくまで設置費用ということで、今後イルミネーションを新しくして、季節的なイベント、近いところでは、この間。","respondent":"奥田河川下水道課長、稲田道路課長、多並公園課長、鈴木建築課長、秋山情報システム課長","answer":"ソフト対策といたしましては、委員からお話がございましたように、例えば、土のうの位置がホームページ上でわかるようにしてございましたり。これは今年度におきましては５月に実施して、枝折れや倒木についての損傷がないかということを点検するとともに、日常の道路巡回においても。公園の場合は計画的にということで、外観診断、いわゆる樹木医の方に見ていただいて。それと、ご自身の建物とどれぐらいの距離にあるか、そういった日頃からの情報収集は非常に大事だと思いますので。","voiceIndex":118,"id":"exchange-051"},{"speaker":"向委員","kind":"質問・要望","question":"ただ、住んでいる方は家のことで、いろいろ土のうを置いてある場所がありますけれども、意外と家庭にあるものでも対応できたりとか、実際、防水板も件数は例年なかなか伸びていないので、使いづらさとかもいろいろあるのかというところもありますし、家庭にあるものでできる周知とか、そのあたりのお考えはいかがでしょうかということと、実際に排水とかをお願いするとき。","respondent":"鈴木防災課長、多並公園課長","answer":"私のほうは、豪雨等に関する対応の件についてお答えをいたします。樹木医等の件ですけれども、現在、１人合格ということで区に今おります。","voiceIndex":125,"id":"exchange-052"},{"speaker":"井上委員","kind":"提案","question":"１点目、自転車走行レーンですが、拡大を求めてきた生活者ネットワークは、この調査経費を評価しております。２点目です。空き家所有者の方たちが活用に関するイメージを持つために、アイデアコンテストのようなものが他自治体では既に行われていますけれども、こういったものについて提案をしたいと思いますが、お考えをお伺いいたします。","respondent":"稲田道路課長、奥田河川下水道課長、矢木住宅担当課長、中村都市計画課長","answer":"完了時期ですが、今、９月を目途として考えております。津波対策についてですが、委員からお話がございましたように、品川区はほかの区に先がけまして海抜標示板を６３２カ所。１点目、活用のイメージを具体的にというお話ですが、まずは平成２７年度にモデルケースといたしまして、公的ないし公共活用をするということで。天王洲アイル駅の内方線付の視覚障害者誘導ブロックですけれども、こちらは私の説明が悪かったことをお詫び申し上げます。","voiceIndex":131,"id":"exchange-053"},{"speaker":"井上委員","kind":"提案","question":"これは積極的に工夫していただきたいと思いますけれども、今ある安全対策以上に何かご検討されているところがあるかどうかということをお伺いしたいと思います。内方線付きのブロックなのですけれども、ぜひ鉄道事業者にお任せではなく、区としても区民を守るためにチェックをし、そして働きかけていただきたいと思います。これは要望です。お願いします。","respondent":"奥田河川下水道課長、稲田道路課長","answer":"その他、例えば来訪者ということで、津波避難施設ですと、日本語だけではなくて、英語や中国語、韓国語などにより多言語表示もしてございまして。自転車の今ある以上の安全対策ですが、警視庁が改めて自転車は車道の左側を通行するようにと昨年度明示されました。我々はまず、自転車走行レーンの設置を進めていきたいと考えております。","voiceIndex":136,"id":"exchange-054"},{"speaker":"渡部委員","kind":"質問","question":"３０３ページ、自転車等駐車場整備手法検討委託というのは、何をどういうふうにやっていくのか。３０９ページ、先ほど来、自転車走行環境整備詳細調査委託ということでご説明もいただいておりますので、この中で僕も自転車走行レーンについてなのですけれども、そもそもこれで詳細の調査をして、自転車走行レーンをどのように増やしていくのかというふうなお考えがあるのか教えてください。","respondent":"田口交通安全担当課長、稲田道路課長","answer":"そういったものをトータルで検討を行いまして、どのような場所にどのような手法で整備するのが放置自転車対策として最も効果的であるかという基本方針を策定するものです。自転車走行レーンの整備について、調査をしてどのように進めるかですが、自転車走行レーンを設置するには、ある程度の幅員が必要です。連続性もある程度必要であると。","voiceIndex":141,"id":"exchange-055"},{"speaker":"渡部委員","kind":"確認","question":"自転車の駐輪場は、そうしますと、今後何らかの形で、さまざまな手法がありますが、確かに今回の大森駅水神口もそうですし、相当需要予測を立てた上で、これからは区がある程度主導をして駐輪場の整備に当たっていくという方針の確認なのですけれども、そのようなことなのでしょうか。","respondent":"田口交通安全担当課長","answer":"したがいまして、基本的な方針として、区としましては、例えば利用率の少ない場所、そういったところは区でやる。民間ができるところは民間でやっていただくという基本方針で進めていきたいと考えております。","voiceIndex":144,"id":"exchange-056"},{"speaker":"渡部委員","kind":"確認","question":"確認させていただきました。自転車走行レーンは、先ほど来いろいろな話があるのですけれども、立会道路を例に出しますと、かなり走行する方が増えています。車のことを気にせずに出てくるわけです。あそこの道路は片側通行で、確かにもう皆様は慣れていて通行しやすくなっているのですけれども、相当危ないというふうに僕は見ているのですけれども、その辺の交通安全対策は何か考えていらっしゃいますか。","respondent":"稲田道路課長","answer":"現在のところ、そのような形で対応していますが、基本的に路側帯のカラー化というところで、なかなか自転車と車道を分けるというところにいかないところがあるのですけれども、それは現状を見ながら、また警察とも話し合いながら安全点検をやっていきたいというふうに思います。","voiceIndex":146,"id":"exchange-057"},{"speaker":"渡部委員","kind":"質問","question":"そんな中でいろいろ見ていたら、品川区は違法駐車等の防止重点地域をそれぞれ平成何年からだったでしょうか、各警察１カ所ずつ持っているではないですか。そのような指定か何かをそれ以外の道でもかけることは難しいのですか。だから、そういうふうなときに、今の状況を見据えて、例えばせっかく条例があって重点地域があるわけですから、そういうところにしていくとか。","respondent":"田口交通安全担当課長","answer":"しかしながら、場所は警察署のほうで指定しますが、確かに従前のまま実施しているところも見受けられますので、今後その辺は警察と協議をします。","voiceIndex":148,"id":"exchange-058"},{"speaker":"渡部委員","kind":"質問","question":"そこの普及啓発のところで、先ほどもご説明あったのですけれども、ヒヤリハット地図の活用は学校だけでしたか。いろいろなところで見受けられるのですけれども。あの地図を見ていて、ポイントは出ているのですけれども、逆にもうちょっと詳細に、こういうことがありましたとかを示せるような方法はないでしょうかというところで質問したいのですけれども。","respondent":"田口交通安全担当課長","answer":"そこまで出せないということで、今回、地図に危険地点、交通事故の発生地点ということで配布をさせていただきましたが、来年度はシステム化を図りながら、データ更新もできるように考えてあります。","voiceIndex":150,"id":"exchange-059"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひお願いしたいと思います。例えば自転車対何とかの事故がありました。そのときには、それこそ駐車違反の車をよけてぶつかりましたとか、何かわかるように地域の方にしっかり確認していただけるような地図になるとうれしいと思いますので、そこは要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-060"},{"speaker":"塚本委員","kind":"質問・要望","question":"それぞれ近隣の住民の方から、ここに一体何ができるのかということが何も示されていないので、例えば完成図とかといったものがあると、こういうものがここにできるということで地域としては大変にありがたい、そういうものをお知らせいただきたいというような要望が何点かございましたので、そういったことについて、本来はこれは建築事業者にゆだねられるべきものなのかもしませんが。","respondent":"溝口都市開発課長","answer":"ただ、全ての地区が同じような取組みをしているわけではありませんので、事業をしております組合等に、そういったＰＲを含めて要望していきたいと考えているものです。","voiceIndex":154,"id":"exchange-061"},{"speaker":"塚本委員","kind":"質問","question":"よろしくお願いをしたいと思います。来年度予算案では、地域を拡大して、さらに推進をしていくと伺っておりますけれども、この二項道路の拡幅ということで、私道と公道とあるかと思いますけれども、公道につきましては、建替えなどをしてセットバックした場合に、その提供した土地は１つとしては寄附、あるいは２つ目としては無償使用承諾ということで、無償で区なり何なりの管理にゆだねる。","respondent":"鈴木建築課長","answer":"基本的に法律、建築基準法にのっとってそういったところが規制できるかというと、なかなかこれは建築物ではございませんので難しいところではありますが、区のほうでは、細街路拡幅整備事業で、私道は、今、委員ご指摘のとおり、後退後も持ち主。","voiceIndex":156,"id":"exchange-062"},{"speaker":"塚本委員","kind":"意見","question":"この電柱については、これは建築主の管理ということになるのかもしれませんけれども、大変に公共性のあるものであるので、こういったものがそのまま、緊急車両が通行するための二項道路の拡幅整備だと思うのですけれども、先ほどのプランターとかですと、いざというときにはどかせるという話はあると思いますが、電柱がありますと全く入れないということで。","respondent":"鈴木建築課長","answer":"ですから、電柱の管理自体は東電側が行うというものでございまして、ただ、委員ご指摘のとおり、狭い道路に電柱があって、拡幅後、塀などは下がっているところに電柱だけが残っているというようなところもございまして、こちらにつきましては、細街路の拡幅整備協議の中で。","voiceIndex":158,"id":"exchange-063"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういった形で進んでいるところは進んでいるということが確認できたのでよかったのですけれども、現状まだそういうふうな形で残ってしまっているところがあるので、これについては引き続きそういった形の話し合いをしていただいて、移動できるように進めていただきたいと思います。","respondent":"稲田道路課長","answer":"エリアを示すですが、基本的には、品川区全域を示します。","voiceIndex":160,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"３３３ページの都市防災まちづくり事業費、都市計画道路です。続いて、武蔵小山駅周辺地区の再開発についてお伺いします。自動車を呼び込む道路はやめてほしいと。道路は防災の費用対効果をどうあるのか示してほしいという実際的なご質問に対しては、算出をしていないので答えられないというような、こういった中身でした。私はこれは自治体のやることではないと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"こういったところから、今後、十分に丁寧な説明を重ねながら理解をしていただく、これから信頼が積み上がっていく段階であるというふうに認識しております。","voiceIndex":163,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そのことを十分に理解をしていただきたいと思います。今日もう１点は、特定整備路線は都内に２８路線ありまして、あちこちで反対の運動が広がっております。品川の道路連絡会の方も下北沢の補助５４号線、あと北区の８６号線、江戸川区の１４４号線など、あちこちで今つながっていますけれども、下北沢では裁判を行っているのです。ぜひ白紙撤回をして捉え直していただきたいと思います。いかがでしょうか。","respondent":"中村都市計画課長","answer":"計画道路の事業の決定、事業認可につきましては、これは東京都あるいは国がそれぞれの責任においてなされたものだというふうに考えております。認可につきましては、裁判で結果が明らかになるです。区といたしましては、都と連携して進めていく姿勢に違いはございません。","voiceIndex":165,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"この道路を認可をしたという事実がないのです。書類もないし、原図も何もない。結局、国も都もそのことを認めている、一番大もとのスタートのところが間違っていることに対して、区がそのまま続けていくというのはおかしいと思います。私は区民に一番近い自治体の役割とは一体何なのか、新たに検討していただきたいのですけれども、もう一度お願いします。","respondent":"中村都市計画課長","answer":"この事業認可につきましては、かなり歴史が古いということで、その辺は書類管理というところではあるかもしれませんけれども、いずれにしましても、都と連携して進めていく、この姿勢は今後も変わることはございません。","voiceIndex":167,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"時間がなくなってしまうので次に、武蔵小山周辺の再開発の問題ですけれども、武蔵小山駅周辺地区開発連絡会のニュースが先日新聞に折り込みがされておりましたけれども、駅前の３つの事業について、改めてお伺いをしたいと思いますが、まず、真ん中の一番初めの武蔵小山パルム駅前地区、地権者の数と組合員数、この地域に居住をしたり、営業をしている方々の総数を教えていただきたいのが１点です。","respondent":"溝口都市開発課長","answer":"続きまして、駅前通り地区ですが、現在、組合設立に向けて準備を進めているところでして、権利者数としては５２名、そのうちの４３名の方が加入している状況になっているものです。","voiceIndex":169,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"どこの駅前もこのところ再開発によって同じようなチェーン店ばかり並んで魅力がどんどんなくなっているという、こういった意見も出されていますので、こういう再開発によるまちづくり、この辺をどう考えているのかが１点と、区内の再開発で商店が１回外に出て、また再び戻ってきて元気になっている商店街があるのかないのか、そこも教えてください。","respondent":"溝口都市開発課長","answer":"もう１つ、再開発事業で商店街をということなのですが、今回、武蔵小山が初めて、区内でいきますと商店街の中で本格的にやる再開発事業になりますので、今後、商店街と連携して、どのようなまち。","voiceIndex":171,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ商店街の方々の心配事とか思いをしっかり受けとめていただきたいと思います。初めてのケースということでは、絶対失敗は許されないのと、やはり正しい方法なのかどうかもしっかり検証していただきたいと思います。私はこの公共の福祉をどう捉えるのかということで変わってくると思うのです。この点、どうお考えでしょうか。","respondent":"溝口都市開発課長","answer":"そういった中では、憲法、そういったものを十分に含めた中で法は構成されております。そういった手続を踏みながら進めている事業になっておりますので、決して憲法の趣旨に反するような形で事業を進めているというような考えはございません。","voiceIndex":173,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は、公共の福祉を都市の土地利用に当てはめると、住民の生活のための土地利用が他人の生活を害してはならない。私はこの間、品川区のまちづくりマスタープランも、そして武蔵小山のまちづくりビジョンも、どちらかというと建てる側の立場に立っていて、周りの人たちの意見が聞かれない、住民合意が本当に形骸化されているまちづくり、本当に改めていただきたい、これは白紙に戻していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":175,"id":"exchange-071"},{"speaker":"渡辺委員","kind":"質問","question":"５年スパンの中で２,５００基、結構な台数の中で電気料の比較を、現状がこうで、電気料という点ではどれくらい削減になるのかというのがまず疑問としてあったので伺いたいです。その中で、この説明にもあるように、五反田が１つの起点である。桟橋という点に絞っていったときに、河川、運河、対象は限られるとは思うのですが、どんな場所が検討に上がっていて、今後、可能性があるのか教えてください。","respondent":"稲田道路課長、奥田河川下水道課長","answer":"太陽光発電による街路灯におきましては、確かにそういう品物も今、出ていることは出ているのですけれども、バッテリーの容量が非常に不足しておりまして、公設街路灯で使うにはまだ難しいというのが現状です。桜の名所です目黒川における観光客ですとか、あるいは、２０２０年東京オリンピック・パラリンピックに向けて見込まれる観光需要を取り込んでいき、本桟橋と羽田空港ですとか、お台場などの湾岸エリア。","voiceIndex":177,"id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"街路灯のところです。今すぐどうこうではないのですが、ただ、このＬＥＤの建替えが終わって、２０２０年の節目も踏まえたときに、またそこからの建替え等は、それこそ二重投資みたいになってしまうので、ぼちぼち検討に入られてもいいのかという気がしたので、この辺の考え方を聞かせてください。五反田で２０２０年のオープンを目指すという中で、区内の動線はあるべきものだと思います。","respondent":"稲田道路課長、奥田河川下水道課長","answer":"太陽光を利用した街路灯の今後の検討ですが、設備類は日々に進歩しておる状況です。その辺の技術の革新等を見据えながら、今後の状況を注視していきたいです。委員からございました水族館ですとか、あるいは競馬場の桟橋についてですが、例えば、災害時に使ったり、訓練のときに使ったり、観光とかにぎわいの創出、あるいは教育と連携した形でも今使ってございまして。","voiceIndex":180,"id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問・要望","question":"というのは、五反田のところの説明を見ていても、もちろん春のシーズン的な観光客もあるのですが、やはり２０２０年に向けて、それ以降もおそらくすごく魅力のある、水辺を持っている品川区だからこそできる観光施策の点もありますし、強い目標設定があっていいのかと思うので、それを１つ伺います。教育目的の観点もあるかと思います。区の強いリーダーシップが求められると思いますが、いかがでしょうか。","respondent":"奥田河川下水道課長","answer":"教育ですとか高齢者の利用についてですが、例えば、平時でも親子の水辺見学会ということで教育目的などでも、目黒川などで区所有の船を使って見学会などを実施してございまして。","voiceIndex":183,"id":"exchange-074"},{"speaker":"渡辺委員","kind":"質問・要望","question":"随時検討が進まれることを祈っています。どんな設計を考えているのか、あるいは３つのエリアをどう連携させていくのかを伺いたい。というのは、現状のあれは２０年前、３０年前の区民ニーズがもとになっている。具体的に教えていただきたいのが、例えばグラウンドの拡張、これはすごいニーズがあると思いますし、同様に、稼働率が大変高いテニスコートの面数、これなどはものすごい要望があると思うのです。","respondent":"多並公園課長","answer":"ただ、委員もおっしゃるとおり、全体的な整備のグランドデザインの中で、やはりスポーツ施設が中心になるところですので、より拡張、またご利用いただけるような整備の手法は検討する必要があると思ってあります。","voiceIndex":185,"id":"exchange-075"},{"speaker":"大倉委員","kind":"質問・要望","question":"こうした環状線ができることによって、今、区民の利便性の向上であったり、さまざまな渋滞の緩和だったり、環境改善だったり、経済力の強化だったりというのは都が言ってはいるのですが、区としては、この環状線ができたことによってどのように交通を捉えているのか、この環状線自体をどうやって捉えているのか教えていただきたいのと、また。","respondent":"中村都市計画課長","answer":"それからもう１つは、新宿から羽田空港間の所要時間が短縮されるということがありますけれども、これも今、五反田の入り口から首都高速道路に入りまして、そして都内各所あるいは都外へも行きやすくなったということで、交通の利便性が向上されたと認識しております。","voiceIndex":188,"id":"exchange-076"},{"speaker":"大倉委員","kind":"意見","question":"区内においての交通の事情が変わったりというところは何か考えていたりするかどうかをもう一度お答えください。","respondent":"中村都市計画課長","answer":"交通の利便性につきましても、それを利用して品川区でどういったことができるか、これも今後の検討課題と認識しております。","voiceIndex":190,"id":"exchange-077"},{"speaker":"大倉委員","kind":"質問","question":"商店街の方からもそういったお話を聞いたりしているので、その辺はどういった対策をとられるか、現状は、その道路自体は入れないようにはなっているのです。でも、実際に見てみると、通常入ってきている方が多いので、そういった部分に対して非常に心配をされている声も聞いているので、その辺にどうやって対応するか教えてください。","respondent":"中村都市計画課長","answer":"アナウンスでは山手通りから入り口へ、首都高速中央環状線に入るというふうにされておりますけれども、この辺は、今後、ドライバーが新たな経路があるとなった場合に、そこをどのぐらい利用するのか、これも開通してこれから様子を注視していかないとわからないですけれども。","voiceIndex":192,"id":"exchange-078"},{"speaker":"大倉委員","kind":"質問","question":"１点、排気塔なのですが、これは品川区内の地下で事故や火災が起きた際に、排気塔への煙がどうなっていくのか、全然心配ないのか、それとも今、排気塔自体はＳＰＭ除去装置とか、低濃度脱硝装置とかいろいろやっていて、その中できれいな空気に戻しますとやっているところなのですが、火災が起きた際はその辺は大丈夫なのでしょうか。","respondent":"中村都市計画課長","answer":"通常の排気がなされるというふうに考えております。非常口、非常電話、非常ベル等が配備されているということで、早期の火災に対する対策がなされて、排気量も最小に抑えられると期待をしております。","voiceIndex":194,"id":"exchange-079"},{"speaker":"大倉委員","kind":"質問","question":"災害時、発災時に車からおりた方たちが出口から上がっていったり、非常口から上がっていったときに、区が対応するのかわからないですけれども、その辺の情報をしっかり持っておくということは大事かと思っているのですが、情報の連携について教えていただければと思います。","respondent":"中村都市計画課長","answer":"災害時の対応につきましては、まず、人命が第一優先ということからいたしますと、消防、それから警察が第一番の連絡先というふうに認識しております。","voiceIndex":196,"id":"exchange-080"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ安心して、沿道の方たちが心配ないように対応していただければと思います。次に、防水板設置工事費助成事業なのですが、これは１台でどのくらいの負担になるのか教えていただきたいと思います。","respondent":"奥田河川下水道課長","answer":"防水板の設置助成ですが、例えば、区民の方で個人の方ですと、限度額を１００万円にして、そのうちの４分の３を助成している形、それと法人ですと、限度額１００万円といたしまして、助成額２分の１ということで助成しておりまして、おおむね数十万程度がかかる費用です。","voiceIndex":198,"id":"exchange-081"},{"speaker":"大倉委員","kind":"提案","question":"今回、助成額が８件と前年度から３件上がっているので、需要もあってそうなっているのかと思うのですが、住民の方が手を出すというのは、金額的に見てもなかなか厳しいのかと。そういった部分でこの助成、安い防水シートとか、防水ゲートみたいなものにも出せないかという提案なのですが、いかがでしょうか。","respondent":"奥田河川下水道課長","answer":"例えば、平成２４年度と比べまして、平成２５年度は３倍、平成２６年度は５倍以上に助成件数が増えてありますので、非常にニーズは高く、区民の方に使っていただいているように認識しています。","voiceIndex":200,"id":"exchange-082"},{"speaker":"こんの委員","kind":"質問・要望","question":"私からは、３０３ページの大森駅水神口自転車等駐車場整備、２点目が３０９ページの自転車走行環境整備詳細調査委託、３点目に３１３ページの大井町駅周辺バリアフリー工事費、この３点をお聞きいたします。私も安全性というところでも、またバリアフリーという観点から、この歩道橋は使われていないという声もありますので、これがこの計画の中ではどのようになっていくのか教えていただきたいと思います。","respondent":"中村都市計画課長","answer":"三ツ又の交差点ですけれども、こちらも利用者が少ない、あるいはないというようなご指摘ですけれども、こちらも交通管理者、それから歩道橋の直接の管理者とも利用状況につきましては協議を行いまして、今後どうしていくか協議をして検討していきたいというふうに考えてあります。","voiceIndex":203,"id":"exchange-083"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川道踏切のことは、計画の中でも、またこれまでのご答弁の中でもご検討いただくということは伺っておりましたので、進捗状況というか、それもあわせてお聞きしてみました。三ツ又歩道橋のことはわかりました。次に、大森駅水神口の自転車の駐輪場ですけれども、先日もお聞きさせていたただきましたが、今日は現在の平置きが今後どうなっていくのかというところをお聞きしたいと思います。お願いします。","respondent":"田口交通安全担当課長、稲田道路課長","answer":"１点目の平置きです。地下駐輪場は全ての自転車に対応できるというものではございませんので、現在ある駐輪施設、こちらのほうも当日利用、あと定期利用もあります。平置きもあります。その辺をトータルで見直す計画です。桜新道の歩道内におきましては、施工時期が大分古くございまして、当時は煉瓦色でやったところです。平成２２年２月に立会道路に設置したときに、警察と協議しまして、ほかに使っていない色ということでブルーを選択したところです。","voiceIndex":205,"id":"exchange-084"},{"speaker":"こんの委員","kind":"質問・要望","question":"水神口の駐輪場に関しての安全対策、これから業者をということですので、ぜひお願いしたいと思います。それから、走行レーンの色ですけれども、これから南大井のほうもそうした工事が入るときにしてくださるということですので、ぜひお願いしたいと思います。よろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":208,"id":"exchange-085"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今、最初に大井町駅周辺のバリアフリーの件が出ていました。それから、河川費の中で、天王洲アイル水辺広場、これは中継所の近くの部分をやるわけですか。この前、本多委員のほうから東品川中継所の質問をしたときに、今後５年を見据えて、オリンピックを見据えてというお話があった中で、この水辺広場との関連をどういうふうにとったらいいのかという部分をお聞きしたいと思います。","respondent":"稲田道路課長、奥田河川下水道課長","answer":"場所は、大井町阪急脇から品川道踏切につながる歩道上で実施したいというふうに考えています。天王洲アイル水辺広場について、委員からお話がございましたように、東品川清掃作業所に面するところですが、ここはちょうど延長１１０ｍのところで水辺の散歩道として整備する予定で、平成２６年度に設計を行って。","voiceIndex":210,"id":"exchange-086"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"あれ、「シナガワドウ」踏切ですか、そこがいつもひっかかるのだけれども、「シナガワミチ」になって、確認をしておきたい。その近くで、東品川海上公園、ある方から言われているのは、せっかくウッドデッキのあたりに、港区あたりの運河でやっているのですけれども、カルガモプロジェクトをやっているので、そういうものはできないのかというのが１点、考え方がどうかと思ってお聞きしたいと思います。","respondent":"稲田道路課長、多並公園課長","answer":"確かに急な坂道で、開発のときにその辺を考慮しなければいけなかったところだと思いますが、今後はそういうところをよく注意しながらやっていきたいと思います。手すりのほうについては道路課のほうで今考えております。そのような空間も活用して、もう少し緑を増やせる形はできないかとか、また、そういうものが今、委員からもご紹介あった形の鳥たちの憩える空間にならないかとか、そういうものもあわせまして検討しなければいけないと思っています。","voiceIndex":213,"id":"exchange-087"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"先に、私道のほうは、大分前から言われていて、確かに工事をやっているときに早く対応できればよかったのかと思うのですけれども、もう完全に終わってしまった後になってしまったので、いろいろお手数をおかけして、対応もしてもらっているということは十分承知していますので、今後もよろしくお願いしたいと思います。これは内容的にどういうふうにとったらいいのか、そこを教えてください。","respondent":"稲田道路課長","answer":"品川道表示板設置についてです。品川道という道が古い時代にはあったというところでございまして、表示板を現在の道路で当てはまるところがあるかどうか、これを調査しながらひとつ選定をしていきまして、表示板、それから解説板等を設置していきたいというものです。","voiceIndex":216,"id":"exchange-088"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"道もこの前、品川区史にも２ページにわたって出ています。どの道かわからないけれども３本あるだろうと言われている中で、うまくその辺をご理解いただけるようにやっていただきたいのと、その表示板にも、これは府中のほうから来ているはずなのですけれども、府中から品川の港、品川の海へ向かってきている道なのだと、その辺をよく強調していただきたいというのがやはり要望の中に出ています。","respondent":"稲田道路課長","answer":"この５,０００万円の内訳ですが、５００万円が電源等の新設工事、それから４,５００万円がイルミネーションを購入して設置する費用というところで考えております。","voiceIndex":218,"id":"exchange-089"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"うまくできるように、せっかくこれだけかけるのですから、きれいな形にしていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":220,"id":"exchange-090"},{"speaker":"西本委員","kind":"質問・要望","question":"この資金繰りというのも非常に大変で、ぜひ品川区としても自主的な活動、自分たちのまちをつくり上げる、いろいろ再開発をするときにも組合等々つくられて、品川区としてもいろいろなサポートをしていると思うのですけれども、そういうような観点でこういう事業に対してサポートする、そういう支援、それから啓発活動に関してのご見解をお聞きしたいと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"まさに今委員がおっしゃいました区民の皆様、地域の皆様が自分たちのまちをどのようにつくっていこうかということを考えるに当たりまして、今、ハードウエアの観点からいろいろまちづくりが行われる中では、この区民の自主的なまちづくりの中で、専門家の派遣ですとか、あるいは。","voiceIndex":222,"id":"exchange-091"},{"speaker":"西本委員","kind":"意見","question":"予算としては、ここに入ってくるべきがいいのか、あとはもう町会・自治会の活動という形で入っていったら一番いいのかというのは、そこはいろいろあろうかと思います。よろしくお願いします。それと、今回の整備路線についてそういうふうになった場合に、どこまで強制力がかかるものなのか、いつまでにそういう形を検討していかないと、法的な手段も含めて入ってくるのかということをお尋ねしたいのですが。","respondent":"中村都市計画課長","answer":"今後、そういった反対の方がいらっしゃるということですけれども、その反対の方の反対の理由が何なのか、そういったところも東京都は踏み込んでお聞きするようにして、それに対してどういった形で不安や反対のお気持ちを解消していただけるか、こういったところを含めてお伺いし。","voiceIndex":224,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"今、現実的に反対だと言っている方たちは、将来どういう形になるということが、決して脅しと捉えてほしくはないのですけれども、そうではなくて、次のステップになるべくスムーズに行ってもらいたいという思いがあるものですから、今までこういう決め事になっていますということがあるならば、それをしっかりとお伝えするというのが住民にとっても一番いいことではないかと思いますが、いかがでしょうか。","respondent":"中村都市計画課長","answer":"反対の方に対しての丁寧な説明、これは東京都も十分配慮して行っていただいているというふうに聞いております。この用地をお譲りいただく際の説明会、用地説明会ですけれども、その中でもこの法律や制度の話はしています。","voiceIndex":226,"id":"exchange-093"},{"speaker":"西本委員","kind":"意見","question":"非常にそれはありがたいことですし、一生懸命やっていただけるのだろうと考えています。最後に、オリンピック・パラリンピックの誘致があって、東京都の予算は大丈夫なのかということが正直あるのです。結構な金額になると思うのですが、それの保証とかはどこまで受け取っているのか、大丈夫ですと言っていただいているのか、東京都のお考えがあったら聞きたいと思います。","respondent":"中村都市計画課長","answer":"特定整備路線を整備するに当たりまして、平成３２年までということで予算については計画的に措置をしていくと聞いております。","voiceIndex":228,"id":"exchange-094"},{"speaker":"あべ委員","kind":"質問・要望","question":"私は、３０９ページ、自転車走行環境整備詳細調査委託について、それから３１７ページの橋梁維持管理費、これは名称ならびに点検についてお伺いしたいと思います。それから３４３ページ、空き家等対策事業、時間がありましたら、区内交通についても少しお伺いしたいと考えています。この名称板のデザインはどんな形で行われているのでしょうか。","respondent":"稲田道路課長","answer":"自転車走行レーンを今まで何キロ実施したかですが、今、手元にキロ数はないのですが、箇所数で言いますと、立会道路をはじめ７カ所実施しています。","voiceIndex":231,"id":"exchange-095"},{"speaker":"あべ委員","kind":"質問・要望","question":"空き家対策なのですけれども、活用について確認をさせていただきたいのですけれども、区が借り上げて民間に使わせるということなのか、仲介というイメージなのか、事業を決めてから物件を探すのか、区がこの建物を使いたいと言ってから、その所有者の方にお話をするのか、あるいは所有者の方からうちの建物を区で使ってという話になっていくのか、いろいろな考え方があると思うのですけれども。","respondent":"稲田道路課長、矢木住宅担当課長","answer":"橋梁名表示板のデザインが非常に景観に合っていないですが、我々はシミュレーションを、画像に張りつけて周辺の景色も写しながらやったり、それから。それでマッチングをした上で、何らかの協議体、私どもが考えているのは、やはり私ども単独の課だけではできませんので、地域の力支援チームを通して、客観性を持ちまして選定してマッチングしていく。","voiceIndex":233,"id":"exchange-096"},{"speaker":"あべ委員","kind":"質問・要望","question":"は庁内活用ということで。その際、例えば、昨年も旧東海道とか、そういったところで立て続けに古い石造りの蔵ですとか、銅板葺きの古い建物ですとか、取り壊されて大変惜しいと思いました。こうした時代の価値を帯びた建物の保存活用ということにもぜひ積極的に介入していただきたいと考えています。最後は要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":236,"id":"exchange-097"},{"speaker":"本多委員","kind":"意見","question":"最初に、土木費の予算なのですが、平成２６年度で３１５億７,０５７万１,０００円、平成２７年度の予算で、２７７億２,７４６万７,０００円ということで、対前年３８億円余の減額、伸び率１２.２％の減ということなのですが、この要因について概要をお知らせください。","respondent":"溝口都市開発課長","answer":"それが一番大きな要因と考えているものです。具体的には、北品川五丁目第１地区が今年度中に完成しますので、それに伴っての市街地再開発事業の補助金が減っているというのが予算としての減の原因だというふうに考えているものです。","voiceIndex":238,"id":"exchange-098"},{"speaker":"本多委員","kind":"質問","question":"次の質問にいきます。それと、助成に対する算定がどういうふうになっているのか、メーター、距離なのか、その辺について教えてください。","respondent":"中村都市計画課長","answer":"同じ制度に基づき実施をしてまいります。助成の割合です。この助成対象の工事につきまして、３分の１が事業者、そして３分の１が国、残りの３分の１が地方自治体、そしてその地方自治体の３分の１の中では、東京都と品川区がさらにそこで２分の１を負担いたします。","voiceIndex":240,"id":"exchange-099"},{"speaker":"本多委員","kind":"質問","question":"わかりました。それで、ＪＲとの協議について、また引き続き質問なのですけれども、今のはホームドアでわかりました。そういうことはＪＲの方は把握していると思うのですが、何もやっていないのかと思うのですけれども、安全性についてＪＲとの協議はどういうふうになっているのか。","respondent":"中村都市計画課長","answer":"いずれにしましても、駅舎の建物そのものにつきましては安全性は確保されているものと聞いておりますし、また、乗客などの利用上の安全性につきましても、随所に監視カメラ等がありまして、常時駅員が可能な限り即座に対応する体制を整えているというふうに聞いております。","voiceIndex":242,"id":"exchange-100"},{"speaker":"本多委員","kind":"質問・要望","question":"ちょっとＪＲに関連して、最後にもう１つだけお聞きしたいのですが、３３３ページの百反歩道橋架替関連整備費で、本当にくどくてすみません。本当にあのＪＲの敷地を５坪、６坪、７坪、例えば区が買い上げて、そこに持ってくれば、ものすごく機能がよかったと思うのですが、ＪＲとそういう協議はしたのかしないのか、それだけ教えてください。","respondent":"溝口都市開発課長","answer":"百反歩道橋の整備に関するお問い合わせです。今回、歩道橋設置に当たって、また歩道設置もあわせてなのですが、さまざま検討していく中で、ＪＲの協力も一部仰ぎながら進めてきているところです。","voiceIndex":244,"id":"exchange-101"},{"speaker":"本多委員","kind":"質問","question":"本当にこれから進めていくということだと思うのですけれども、現行では結構です。それで、目黒川の区界、上流のほうに進みますと、目黒雅叙園のあたりが区界になるのですけれども、もちろんその船の形態にもよると思うのですが、上流はどの辺までイメージをされているのか。もちろん船の大きさ、高さ等にもよりますけれども、現在のイメージについて教えてください。","respondent":"奥田河川下水道課長","answer":"現在、例えば、春の桜の時期とかに目黒川を上がってくる民間の船とかは平舟ですので、オリンピック・パラリンピックに向けても国内外の観光客が来られますので、おおむねそれと同じぐらいの船と考えています。","voiceIndex":248,"id":"exchange-102"},{"speaker":"山元委員","kind":"質問・要望","question":"初めに、八潮団地の中の拡幅整備工事について伺います。第１期区間が終了したかと思いますけれども、まずは計画どおり進んでいるのかどうかを教えていただきたいということと、あともう１点、こちらのバリアフリー、まず第一には、歩道を２ｍ幅にするというお話で進めているわけですけれども、ここに点字ブロックをつけていただけるかと思いますが、２ｍのどの辺に設置するのか教えていただきたいと思います。","respondent":"稲田道路課長","answer":"八潮団地は今年度から着工したところで、４年計画で進めるです。第１期工事は計画どおり進みまして、現在、竣工しています。点字ブロックにつきましては、２ｍの歩道がありますけれども、若干民地寄りというところで考えているところです。","voiceIndex":251,"id":"exchange-103"},{"speaker":"山元委員","kind":"質問","question":"実は、点字ブロックのお話なのですけれども、お年寄りがカートというのでしょうか、点字ブロックが悪い、そういう意味ではないのです。そこの段差についていろいろご相談させていただいて解決はしたのですけれども、これから第２期、第３期、第４期区間というところでバス停ができると思いますが、そのバス停に対しては、これからどのような工事を予定していらっしゃるか教えてください。","respondent":"稲田道路課長","answer":"いろいろと工事は支障が出てきたりとかというのがありますので、そういうところを地域に協力を求めながらやっていきたいです。","voiceIndex":253,"id":"exchange-104"},{"speaker":"山元委員","kind":"質問","question":"実は前もちょっとお話ししましたが、道路沿いにバスが停まると段差があるということで、高齢者の方がカートを引っ張ってバスに乗り込むのが大変で、課長にいろいろご相談させていただいて直していただいたのですが、今聞いたのは、バス停がそのようになるのかどうかお聞きしたかったのですが、お願いいたします。","respondent":"稲田道路課長","answer":"そういう中におきましては、施工中におきましても、バス利用者になるだけご不便はかけないように考えていきたいとは思いますけれども、工事中においては、途中でそういう状況が生じる。最終的には不便のないような形ででき上がるです。","voiceIndex":255,"id":"exchange-105"},{"speaker":"山元委員","kind":"質問・要望","question":"八潮の中にはバスを使う方がたくさんおりますので、ぜひご検討いただきたいと思います。次に、先ほど、自転車走行レーンの話が出ました。そこを１人で走る場合、道路が暗いとき、灯はありますけれども、そこにキララ舗装というか、光るもの、道路にそういうものは、ここは自転車の走行レーンとわかるようなものにはできないのだろうかという、そんなご相談をいただきましたけれども、いかがでしょうか。","respondent":"稲田道路課長","answer":"夜間に自転車走行レーンがわからないのではないかというお話ですが、これは実は地域の説明会の中においてもこういう話が出てきておりました。ということで、我々はブルーの色はなかなか光らせることはできないのですけれども、ナビマークをあわせて設置しております。","voiceIndex":257,"id":"exchange-106"},{"speaker":"山元委員","kind":"質問・要望","question":"もっと狭かったのですね。最後に、もう１つ聞きたいことは、今度は第３期区間に、まだ先の話になりますが、あそこは一直線の道路になります。本当に長い車を運転すると、波というか、でこぼこというか、それがなくなってしまうというのが逆にこれから危ないのではないかという、そんなお問い合わせがありましたけれども、これから第３期区間を工事する場合、どのようになるか教えていただきたいと思います。","respondent":"稲田道路課長","answer":"ただ、そういう中におきましては、交通においてのスピードの出し過ぎとか、そういうものを抑制するために、路面表示、その辺で何か、今はまだ考え中ですけれども、警察と協議しながら、よりよいものができればというふうに思っております。","voiceIndex":259,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"ちょっと時間がありますので、３４１ページの耐震シェルター等設置助成について伺います。もうほとんど毎回のように私はこのシェルターについてお伺いしていますが、どうしてこんなにいいものが毎年２桁の件数の予算が計上されているのに、決算になると１桁が多いので、８年ぐらいたちますが、なぜなのだろうかと不思議に思うのです。","respondent":"寺嶋木密整備担当課長","answer":"ほかの事業でもそうなのですけれども、危険度の認識と、それにかかる手間暇とのバランスの問題がありまして、やはり東日本大震災の翌年は８件、耐震シェルターは１２件という実績が出たのですけれども、その後、２件、１件と下がっていっております。","voiceIndex":261,"id":"exchange-108"},{"speaker":"山元委員","kind":"質問・要望","question":"いずれにしましても、本当にすばらしいものですので、むだのないようにまたご努力、お力添えいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-109"},{"speaker":"南委員","kind":"提案","question":"集合住宅ができ上がってきた、いわゆる団地というものができ上がった時代には、低層の住宅にはエレベーターはつけなくていいと、そんな趣旨で決めたというか、そういう認識が広がったやに聞いているのですけれども、それは若い人たちが地方から都会に来て、住宅に住んで生活をするという、そういう方たちを対象にした住宅建設だったので、エレベーターがなくてもいいかという。","respondent":"矢木住宅担当課長、多並公園課長","answer":"３点目、エレベーター整備につきましては、こちらは現時点で私どもが２３区の調査をしたところ、エレベーター助成につきまして、２３区中、助成しているのが６区。今後につきましては、もちろん全面改修のタイミングを見ながら、その際は、地域の皆様のご意見、子育て世代はもちろん、住んでいる皆様のご意見を踏まえながら、現在もさまざまなところで公園を整備する際はお聞きしていますので。","voiceIndex":265,"id":"exchange-110"},{"speaker":"南委員","kind":"質問","question":"高齢化が非常に進んでいけば、さまざまな問題が出てくること、そのことはもう必然です。したがって、そういうまちをそのままにしておくわけにはいかないから課題だと思っているという答弁だと私は理解してきたのですけれども、では、その点についてどういうふうに認識しておられるのか、そこをまず伺います。","respondent":"柏原行財政改革担当課長","answer":"そういったところを課題としながら、八潮のまちづくりをどうやってやっていくのだということで、庁内の検討部会を開きながら進めていきたいというふうに思ってあります。","voiceIndex":268,"id":"exchange-111"},{"speaker":"南委員","kind":"提案","question":"庁内で検討していくことは当然だと思うし、だからそれをもう少し、私は具体的な提案をさせていただきながら、それについても検討していただきたいということで、今、質問をしているわけです。したがって、来年してくださいとかということではないにしても、きちんとした改修を、その際には子どもの声を入れて改修していただきたいと、こういう提案ですから、それについての検討をお願いしたいと思います。","respondent":"柏原行財政改革担当課長、多並公園課長","answer":"先を見たときに、オリンピック・パラリンピック等々、国際化の流れ、こういったところも視野に入れながら、八潮のまちをどうつくっていくのだ、それは１つの部門というところのアイデアもありますけれども。公園につきましても、もちろん３０年たっているところがありますけれども、ただ、全体的な地域バランスやほかの公園の状況も踏まえながら、改修時期を見定めて、必要なときには、先ほどご説明させていただきましたが。","voiceIndex":270,"id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"子育て支援について、必要かどうかという答弁がないので、ぜひお願いします。","respondent":"柏原行財政改革担当課長","answer":"子育ても、高齢者への施策も、全て大切な施策だと考えていますので、そういった面、八潮のまちを見ながらやっていきたいと思ってあります。","voiceIndex":273,"id":"exchange-113"},{"speaker":"南委員","kind":"提案","question":"私は幾つか提案しましたけれども、しっかりと受けとめて、庁内での検討に生かしていただきたいと考えていますので、よろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":275,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問・要望","question":"初めに３１１ページの補助１６３号線整備、９億３,２２２万１,０００円、たくさん、これは工事用地借料とか、事業用地補修工事費とか、移転補償費とかありますけれども、これは今年度の予算の中で、どれがどれくらいの工事になっていくのか、ちょっと頭の中でわからないので、どこを借りて、工事車両がこういうふうに入って、あるいは、ここを移転してもらってとか。","respondent":"稲田道路課長","answer":"まず今年度の工事としましては、準備工、工事をするために準備をしていく。それから、あそこにまだ建物が残っていますので建物を壊していく。それから、仮設山留をつくって、本設山留をつくっていくところまで行く予定で今考えております。","voiceIndex":278,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、２６号線の部分には工事車両がずらずらと両側に並ぶということはないということなのかどうかということと、私たちの駐車場に入るのに支障はないのか、その辺をお聞きしたいと思います。","respondent":"稲田道路課長","answer":"それと、区役所の駐車場におきましては、リボンの前からバイク置き場、階段のところという具合に、ちょっとヤードを借りてやっていくです。駐車場の入り口も若干影響はするかもしれませんけれども、ご不便にはならないような形で考えていきたいと思っています。","voiceIndex":280,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問","question":"続きまして、３１５ページの私道整備事業、これは私道整備に、通り抜けられない場合は９０％助成して行うというようなことがありますが、根拠として、品川区私道整備に関する条例ということですけれども、これがいつ頃できて、９０％助成はいつ頃こういう形になったのか、この根拠についてお聞きしたいと思います。","respondent":"鈴木建築課長","answer":"私道整備についてのお尋ねです。私道整備事業につきましては、平成１５年になります。それまで一定の助成率が８５％、地元のほうで１５％ご負担いただいていたものを平成１５年に条例改正しまして、９０％というふうな見直しを行ったものです。","voiceIndex":282,"id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"実は、この私道の補助が今、９０％助成して１０％しか出していないのです。ところが、これが問題で、９０％補助してもらうというのですけれども、私道の両側の人たちの同意を得なくてはいけない、あるいは判こをもらわなくてはいけないとかでなかなか大変なのです。これで年間どれくらい助成を受けたいと来て、やれないというのがありますか。その数は見ておりますでしょうか。","respondent":"鈴木建築課長","answer":"相談を含めてですけれども、平成２６年度、今年度です。途中の状況ですが、相談も含めて７９件あります。その中で実際に整備まで進んだとか、結果的にお話だけ伺って地元でどういう合意形成がなされたか、あるいはとりやめたとかいう細かい数字までは今現在把握しておりません。","voiceIndex":286,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"この私道整備の条例が昭和３４年にできて、平成１５年から８５％から９０％に変わったと言いますけれども、これは道路に対する助成というより、ここに一つ福祉のバリアフリーという心を入れることはできないですか。そうしたら、福祉のバリアフリーという観点、高齢者のためということで、例えば品川区が１０万円までもちましょうとか、何かそういうような心が欲しいと思うのですが、いかがでしょうか。","respondent":"鈴木建築課長","answer":"ですから、事業の内容としましては、非常にバリアフリーの視点も入っているというところでございまして、心的なところもお話としていただきましたけれども、私道の維持管理につきましては、基本はやはりそこを所有されている方。","voiceIndex":288,"id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"続きまして、３３５ページ、都市防災不燃化促進事業、これは戸越公園一帯周辺地区と、補助２６号線その２地区、これは１０年間なのですけれども、平成２７年度で終わりなのです。平成２７年度で１０年間が終了いたします。これは今までどれくらい助成ができたのか、あるいは今年度どれぐらいやるつもりなのか、その辺をお聞きします。","respondent":"寺嶋木密整備担当課長","answer":"補助２６号線その２につきましては、助成は、今年度、除却の２棟を予算上は予定しています。それから、戸越公園一帯につきましては、除却が５棟と、建築助成については１２棟ということで予算上は計上させていただいているところです。","voiceIndex":290,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問","question":"戸越公園一帯地区というのは広いですから、ある程度の数が出て、また、今までの実績も大きな数があるのですけれども、補助２６号線その２は今年度までの９年間で２件です。今年２件やりますという話ですけれども、最終年度なので、その２地区は短いですけれども、しっかりと回って整備できる家がありましたら、ひとつよろしくお願いしたいと思います。","respondent":"寺嶋木密整備担当課長、矢木住宅担当課長","answer":"新規事業として未接道宅地解消事業ということで予定させていただいていますが、こちらは、ご案内のとおり、敷地が前面道路２ｍ以上接していないところに建っている建築物について未接道の建物ということで。委員ご指摘のとおり、こちらは決算特別委員会のところから発しまして、防災性向上の観点から取り入れたものでございまして、対象といたしましては、器具は買ってこられるが取り付けができないといった場合を想定しております。","voiceIndex":292,"id":"exchange-121"},{"speaker":"松澤委員","kind":"意見","question":"その何年間のうちにどういうふうにするかを考えてくれる。これはすばらしい施策だと思いますので、１,５４０万円と言わずに、どんどんなくなったら追加するような形でお願いをしたいと思います。家具転倒防止につきましても、やはり一番大事なのは、家具転倒で亡くなる方がたくさんいますので、この辺のことを、この予算が余らないように、ひとつよろしくお願い申し上げます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":295,"id":"exchange-122"},{"speaker":"高橋委員","kind":"質問・要望","question":"３１２ページの受託事業費のことをまずお尋ねします。東京都からの受託は、排水施設建設事業と下水道管改修事業です。この２つの受託事業について、どのような経緯で受託するようになったのか。つまり、東京都の下水道局からの申し出なのか、それとも区民生活と密接に関係がある、区民の要望を一番身近で受けとめている区のほうから下水道局にアプローチしたのか、そのあたりをお伺いします。","respondent":"奥田河川下水道課長、稲田道路課長","answer":"今の浸水対策関係ですとか、あるいは再構築の関係でやっています受託事業の経緯ですが、浸水を早期に軽減させる、それから、例えば技術の継承とかになるということで、東京都のほうから話がありまして、区にとってもいいことですので。そのために沿道の区民の方には随分と迷惑をかけてきたということから、できるだけ工期を短縮しようというところでございまして、区のほうからと下水道局のほうからと、それぞれから協議が成立したです。","voiceIndex":297,"id":"exchange-123"},{"speaker":"高橋委員","kind":"質問","question":"区民生活に近い状況の中で、先ほどあったように立会川の下水関係で昭和の時代から受託していると。それから今、道路のほうも、早期に対応できるようにという形で双方が協議してというふうなお話で始まったと。ここを利用される方が大変苦労しているというお話があって、道路課長にお願いをして、第二建設事務所に伝えていただいたのですが、その後の対応について、どういうような状況でしょうか。","respondent":"稲田道路課長","answer":"把握しておりまして、私どもは最初そこのところを指摘したのですけれども、ちょっと今どうやっていいか悩んでいるところという話はありましたけれども、最終的に、先週なのですが、歩道の舗装を、インターロッキングを張り直しまして、勾配を確保して。","voiceIndex":300,"id":"exchange-124"},{"speaker":"高橋委員","kind":"質問","question":"何年間もかかってしまったと。とすると、こちらは都道なので、今みたいな対応をしなければいけないのですが、先ほどお話があったように、もう一歩踏み込んで、住民の皆様がお困りになっている状況を一番よくわかっている区が都道の整備も受託して、それで早期解決、先ほどお話がありましたけれども、積極的に対応できるという形、これをとっていけないのかということで、その辺のお考えはいかがでしょうか。","respondent":"稲田道路課長","answer":"道路の維持管理を区が都から受託したらですが、現状におきましては、この品川工区との連携では、担当者レベル等で十分に連携がとれているというふうに私どもは思っております。","voiceIndex":302,"id":"exchange-125"},{"speaker":"高橋委員","kind":"質問","question":"今は一例なのですが、区内には都道がたくさんあります。以前はモノレールの大井競馬場駅から大井埠頭に渡る都道の橋の整備も都のほうから受託したと伺っています。ぜひ検討をお願いいたします。あそこはどうしてアスファルトではなく、そういったちょっと変わった舗装なのでしょうか。その経緯と、そういった現状をどのように考えて、どう改善していただけるのでしょうか。","respondent":"稲田道路課長","answer":"ご指摘のように、この前の２月６日も路面凍結等があった日なのですけれども、随分歩行者等が滑っているのを私自身も確認しております。今後はもう少し調査をしまして、どのような対策をしたほうがいいのか検討していきたいと思います。","voiceIndex":304,"id":"exchange-126"},{"speaker":"石田（し）委員","kind":"質問","question":"初めに、地籍調査に関連してですが、世田谷区の総面積が小さくなったという情報を得まして、これはなぜかと思ったら、より高精度である電子国土基本図の整備完了に伴って計測方法が変更され、小さくなったということなのですが、品川区の総面積に変更はないのかどうか教えてください。","respondent":"安井土木管理課長","answer":"国土地理院のほうから３月６日に発表されました総面積ですが、こちらは国土の面積そのものが電子化によりまして増えたということで、市町村別も出ておりまして、世田谷区の場合は減ってありますけれども、品川区の場合は従来２２.７２km2とあったところが。","voiceIndex":310,"id":"exchange-127"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そうですか。五反田地区コーディネート業務委託に移ります。それと、このまちづくりビジョンを含めてなのですが、まちづくり協議会の中にたしか鉄道会社等が入っていなかったかと思って、私も以前に、駅にもぜひ参加をしていただいて、五反田のまちの活性化に結びつけていただきたいというお願いをしていたのですが、今、鉄道会社との連携はどのようになっているのか教えてください。","respondent":"溝口都市開発課長","answer":"ただ、今後の跡地利用については今後検討していくと聞いておりますので、引き続きまちづくりビジョンの中で示しましたにぎわいづくり、また、地元の方たちも引き続きホール等のにぎわい施設を望んでいるという声も聞こえておりますので、日本郵政に対してはしっかりと区の思い。","voiceIndex":312,"id":"exchange-128"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"ぜひ連携をよろしくお願いします。ゆうぽうとの跡地については、地元の声を届けていただくのも行政の役割かとも思いますので、その辺もぜひよろしくお願いいたします。もし何かあれば言ってください。新しい事業で入り口までの空間を充実していくということなのですが、どこに設置をされるのか教えてください。","respondent":"溝口都市開発課長、多並公園課長","answer":"五反田駅前の交通広場を含めて、歩道橋を含めてなのですが、今後、まちづくりを検討していく中で、さまざまな展開が考えられると思います。入り口につきましては、おもてなし事業の中で、大井町から無料バスが着く停留所がありますが、そこのところから水族館までの間がなかなか以前から公園との連続性という部分でご意見をいただいていたところがありますので。","voiceIndex":314,"id":"exchange-129"},{"speaker":"石田（し）委員","kind":"意見","question":"しながわ水族館のモデルにもなったと言われているケリータールトンズ・シーライフ水族館、ニュージーランドに行った際に時間をむりくりとっていただいて見せていただきました。非常にすばらしい水族館で、特に私が印象に思ったのは、動く歩道です。よろしくお願いします。","respondent":"多並公園課長","answer":"パンフレットにつきまして、現時点でもう一度確認して適切な対応をします。","voiceIndex":317,"id":"exchange-130"},{"speaker":"浅野委員","kind":"質問","question":"３０７ページ、舗装工事と側溝修繕について、それと３１５ページの私道整備事業について、３４３ページ、空き家等対策事業について質問します。品川区では、道路や側溝などを含めて、巡回パトロールを毎日朝から夕方まで実施していると伺っていますが、異常の発見件数、平均どのくらい発見をされているのかということと、また、どのような異常が多いのかということについて教えてください。","respondent":"稲田道路課長、多並公園課長","answer":"区道の維持管理におきましては、巡回パトロールを平日も休日も実施しています。陳情の件ですけれども、平成２６年度現時点で４２件、ただ、昨年度は全部で１９５件というところで、このような対応をしながらやっております。基本的に１カ月で各持ち場の区道を全部点検するというところで、点検の仕方もいろいろあるのですが、車に乗って車道を回る。","voiceIndex":320,"id":"exchange-131"},{"speaker":"浅野委員","kind":"質問","question":"質問した内容だけ答えていただければいいのに、公園までいただいてありがとうございました。アスファルトはどのような構成になっているのか、厚さについて、国道ですとか、また都道、区道で違うのかどうかということと、強度、耐久性についても国道とか区道とかで違いがあるのかどうかということについてお伺いします。","respondent":"稲田道路課長","answer":"それと、国道、都道におきましても同じような形でやっているところです。それから、Ｌ型側溝につきましては、コンクリートブロックを、６０cmの長さなのですけれども、それを並べていくというところで、車の出入りが多い場所、駐車場の前とかは破損が生じることが多々あります。","voiceIndex":324,"id":"exchange-132"},{"speaker":"浅野委員","kind":"質問","question":"例えば、区道が損傷していて、ここで事故が起きたとか、けがをしたということになると、区の責任になるかと思うのですけれども、このような事故で区として補償が必要になったことがあるのかどうかということをお伺いします。例えば、私道整備の際に区民の方にこういうこともあり得るから、しっかりと私道は整備してくださいとか、そういうアドバイスなどをされているのかお伺いします。","respondent":"稲田道路課長、鈴木建築課長","answer":"区道の段差や穴ぼこ等で転んで補償に至った件ですが、そんなに発生はないです。５年に１回ぐらい程度の頻度だと思われます。私道の穴があいている件についての補償の話を含めてですけれども、基本的に委員ご指摘のように、何かけががあった場合は私道の管理者が責任を負うというところでございまして。","voiceIndex":326,"id":"exchange-133"},{"speaker":"浅野委員","kind":"質問","question":"これは年代によってはもうかなり古いものから、最近整備したものもあるかと思うのですけれども、例えばこの古い私道から区のほうで調査をして、傷み具合でありますとか、そういうような場合については、傷んでいるところがあれば、区民の方に積極的に整備を、例えば声をかけるとか、そういう取組みをしながら傷んでいる私道、これはけがをしたりすると。","respondent":"鈴木建築課長","answer":"私道のご相談については、基本的に路面改修、維持管理含めていろいろなご相談をいただいております。その中で、区の土木専門職ならびに委託をしているコンサル等々が現地で立会いをして、原因についても細かく説明しております。","voiceIndex":329,"id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"区のほうで多分問い合わせをすれば、ある程度の対処はしていただけるとは思うのですけれども、どのような対処ができるかということと、あと空き家等を活用した町会・自治会会館の整備を促進するという、この記事がありましたけれども、空き家の状態からこの町会・自治会会館にするまでに必要とされる手順等について教えてください。","respondent":"矢木住宅担当課長","answer":"ご相談に対する対応です。こちらは、空き家対策の担当をするということですが、地域の力支援チームにおいても対応をそれぞれがとっております。相互に連携を図ってまいります。","voiceIndex":331,"id":"exchange-135"},{"speaker":"須藤委員","kind":"質問","question":"今の浅野委員の質問である程度わかったのですが、維持管理ということで、３１３ページの道路バリアフリー事業、それから３２５ページのしながわお休み石設置事業、このあたりの維持管理がどうなっているのかと思って質問いたします。ある企業は、製造会社で、検査をしないでどんどん町に流してしまう。","respondent":"稲田道路課長","answer":"巡回点検の委託業者等も回っているのですが、チェックポイントを設けておりまして、点字ブロック、ゼロ段差、そういうところでガタつきや異常はないかというところを調査して回ってはいるのですけれども、なかなか全部を把握することは難しいです。","voiceIndex":334,"id":"exchange-136"},{"speaker":"須藤委員","kind":"質問","question":"荏原南公園、子どもたちのアイデア、先ほど横山委員がいろいろ聞かれたので内容はわかりましたけれども、あそこの下には調整池があるので、そのことをきちんと、それはそれで調整池としての活動ができる仕組みで子どもたちのアイデアを生かしてもらえるようにお願いしたいと思いますけれども、その辺はいかがでしょうか。","respondent":"多並公園課長","answer":"ＪＴ跡地は、地元の方にもご説明している中で、防災機能に重点を置きながら整備していますので、有事があったときにヘリコプターとか、いろいろな防災活動に必要な部分で、なるべく何も置かず、いろいろな場面場面で使えるような形で整備ということで。","voiceIndex":338,"id":"exchange-137"},{"speaker":"須藤委員","kind":"意見","question":"そうすると、これが子どもたちにタッチしたときに、こういう話だということだろうと思うので、私が平成３２年までに死んでしまえばやるだろうけれども、まだ元気でやっているうちはそのままにしているというような思いがあるので、今のままでいきたいと思っているので、そうすると、ある程度時間をかけてまちづくりをするというのもあるのではないかという思いがあるので。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":343,"id":"exchange-138"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、３３３ページ、都市防災まちづくり事業費、その中の首都直下大地震後の都市計画についてお聞きしたいと思います。日本の心臓部に当たる首都圏については、復旧・復興に対して時間をやはりかけられない。早急な対応が求められると思うのですが、品川区がここで万が一甚大な被害を受けた場合、復興後の道路、住宅等、さまざまな都市計画は、これは検討されているのでしょうか。教えてください。","respondent":"中村都市計画課長","answer":"これについては、道路の整備、それから建物の復旧、そういったところが主な一部というふうになってあります。","voiceIndex":345,"id":"exchange-139"},{"speaker":"須貝委員","kind":"意見","question":"今立てていらっしゃるというお話ですが、実際に東日本大震災を見ても、４年たってもなかなか進まない。確かに関東大震災のときは、人口２３０万人足らずで、４カ月で都市計画をつくり上げた。でも、これだけ、品川区だけで約３７万人の大都会、東京圏内で１,２００万人もいるとなると、実際にそういうある程度大きな被害想定に対してきちんとした青写真を持っているのかどうか、もう一度お聞かせください。","respondent":"中村都市計画課長","answer":"マニュアルをつくっております。","voiceIndex":347,"id":"exchange-140"},{"speaker":"須貝委員","kind":"質問・要望","question":"中の細かいことをお聞きしますが、多くの家屋が焼失した場合、廃材等の持ち込み先はきちんとこれは決まっているのでしょうか、確保されているのでしょうか。この大都会で埋め立て地と言ってもほとんどない。その状況で実際にどうなのか。そして、空き地には仮設住宅を建てるわけですが、仮設住宅用の資材の確保はきちんとして、これはあるのでしょうか。","respondent":"中村都市計画課長、鈴木防災課長","answer":"ただ、問題はその量です。やはり受入れ先の容量等の関係もありますので、その辺は東京都あるいは国と調整するような形で実際は処理されるというふうに認識しています。昨年度から３カ年計画で、各災害対策本部の部隊の詳細のマニュアルの改訂に取り組んでおりまして、その中で瓦れきのマニュアル、避難者の方の対応マニュアル、それから仮設住宅等のマニュアルも再検討しています。","voiceIndex":349,"id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"確かに国とか、広域になりますから都の問題になるかと思うのです。実際にどうなるのですか。では、どこか地方に行くのですか、関東の奥地に行くのですか、それとも関西に行くのですか。でも、実際にそれは、数字として刻々として日々持っておられるのですか。そうではなくて、とりあえず漠然として、いや、都のほうでやっています、国のほうでやっていますというのが現状なのですか。教えてください。","respondent":"鈴木防災課長","answer":"その最大の被害に備える形で用意ができれば、それより小さな被害の場合には対応できるというのが現在の考え方ですので、首都直下地震の被害想定の数字をもとに対策を立てているというのが現状です。","voiceIndex":352,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"東日本だけではありません。全てパーフェクトにやれとは言いませんが、区民の間近にいる自治体としては、そういうことも情報を発信して、安全です、こういうところに避難場所もあります、避難できますとか、だめなら公営住宅、民間住宅もこういうふうに数字としてありますということを、私は数字として皆様に公表する義務があるのではないかと思うのですが、いかがでしょうか。","respondent":"鈴木防災課長","answer":"委員ご指摘のように、現在の体制を整える根拠となる数字、またそれに関する正しい知識は区民の方にしっかりとお伝えする必要があるというのは認識しておりますので、今後もさまざまな機会を捉えてしっかりとお伝えしていきたいというふうに考えております。","voiceIndex":354,"id":"exchange-143"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"３３３ページ、品川駅南地域周辺まちづくり事業についてお伺いしたいと思います。リニア新幹線についてお伺いしたいのですが、昨年１０月、ＪＲ東海が２０２７年開業を目指すリニア中央新幹線の工事実施計画を太田国土交通大臣が認可をしました。そのためにも丁寧な説明が今こそ求められているのではないかと思います。基本的なことを伺います。","respondent":"中村都市計画課長","answer":"残土につきましては、これは総量というものはＪＲ東海からはまだ公表はされておりませんけれども、先日の計画の説明会の中におきましては、北品川の立坑から排出される土の量は、トラックの台数にしまして、１日８３０台というふうに聞いてあります。","voiceIndex":357,"id":"exchange-144"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で１１月の決算特別委員会で、きめ細やかな説明会を求めていただきたいという飯沼委員の質問に対して、課長からは誠意をもって回答するようＪＲ東海に申し入れを行っていきたいと、こういう答弁がされていますけれども、ＪＲ東海には区としては具体的に何を求められてきたのか、そしてＪＲの回答はどうだったのか、このことについてお聞かせください。","respondent":"中村都市計画課長","answer":"説明につきましては、これはきめ細やかな説明を求めていくということで、区といたしましては、地域への説明、あるいは区民への説明、こういったものを引き続き求めているものでございまして、特にご自宅の真下を通るということにつきましては、これはＪＲのほうでは。","voiceIndex":359,"id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう中で、私はこれからも区から強力に、この国会答弁も使いながらＪＲに求めていただきたい。それで、ＪＲに求めていただいたときに、ＪＲは地上の権利者のところに、本当に私は町会ごとぐらいにやっていただきたいと思うのですけれども、地域ごとに説明会はやるというふうにはなっていないのか、やるというところまで求めていただきたいと思うのですけれども、そこのところを聞かせてください。","respondent":"中村都市計画課長","answer":"そういった法律上の手続は正規に行っていただく、これは当然のことですけれども、実際に地域への説明に対しましては、立坑が通る近隣の皆様への説明、また、品川区全体への説明も丁寧に行っていただきたいということで、今後、立坑の工事も行われますでしょうし、また。","voiceIndex":361,"id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"地上の権利は及ばないというＪＲのホームページや説明というのは間違いだったということで、ＪＲは訂正したのです。その後、ホームページの表記の仕方も変えたのです。そういうところで、私はぜひ区として下にトンネルが通る地上の方に説明会をやるようにということで、その説明会をやってほしいということで、しっかりと求めていただきたいと思うのですけれども、この点だけお聞かせください。","respondent":"中村都市計画課長","answer":"この大深度法の目的は、やはり地下に対する権利を、事業を進めるためのものですので、説明会については求めてまいります。","voiceIndex":363,"id":"exchange-147"},{"speaker":"いながわ委員","kind":"提案","question":"私から、３０７ページ、道路維持費の中でＬＥＤの街灯についてまず１点お伺いします。これは提案というか、先ほど建築課長のお話の中で、崖・擁壁、特に擁壁なのですか、工作物は建築確認が必要だと説明の中であったので、もし震災が起きたときに崩れるとか、そういうことも考えたときに、例えば耐震改修の促進事業の中に、そういった崖の部分も当て込んでやるのが可能なのかどうなのか。","respondent":"稲田道路課長、鈴木建築課長","answer":"このＬＥＤの街路灯なのですけれども、以前は確かに、まぶしさ、輝度が、基準で言えば２万カンデラというのですけれども、それを超えていたという状況もありました。今現在はそれがこの基準値内に入っている製品が出てきている。したがいまして、来年度行います区内全域の２ｍ以上の擁壁の調査とはまたちょっと違うという内容になっております。それからあと、委員ご指摘のとおり、擁壁の改修については非常に費用がかかります。","voiceIndex":366,"id":"exchange-148"},{"speaker":"いながわ委員","kind":"提案","question":"これもまた提案なのですが、例えば、西大井とか荏原町には普通の立体というのですか、普通の２階建てぐらいの駐輪場があるのですが、災害が起きればそれが崩れる可能性もあるわけですし、夜になれば夜になるで犯罪が起きる可能性もあるということで、そういったところを地下駐輪場にすれば、また公開空地が確保できるのでいいのではないかと思うのですけれども。","respondent":"田口交通安全担当課長","answer":"駐輪場の整備につきましては、来年度、ここの駅も含めまして、駐輪の需要予測等を踏まえて、どのような場所にどのような手法で整備するのが最も適切かということで基本方針を立てる予定です。その方針に基づきまして、今後の整備のあり方は考えていきたいと思います。","voiceIndex":369,"id":"exchange-149"},{"speaker":"いながわ委員","kind":"質問・要望","question":"３３５ページで都市開発費の中のどこになるかはちょっとわからないのであれですが、直球勝負でストレートにお伺いしたいのですけれども、二葉三丁目に２カ所、今、空地というか、空き地があります。品川区の密集市街地の看板が立っているのですが、１つは大きくて、１つは小さいという状況の中で、今もう既に何にするかというのが決まっているかどうかをお伺いしたいです。よろしくお願いします。","respondent":"寺嶋木密整備担当課長","answer":"公園として整備していくという可能性ももちろんあるのですけれども、実際のところ、今ご指摘があったとおり片方は小さい、それからもう１つは、そこの広場に至るまでの道路等の動線がやや不足しているとか、それから、地元のご理解等も含めまして、まさに現在検討しています。","voiceIndex":371,"id":"exchange-150"},{"speaker":"いながわ委員","kind":"質問","question":"非常に広い空地が確保できたということで、うまく公園ができたらどうなのかとか、ただ、少なくとも暫定用地として、あそこに家を建てて、そこにまた人が住むということはないようにしていただいて、空地をずっと何かしらの形で保たせてもらいたいというのですか、あの辺は公園がなくて厳しい状況下に置かれているのは実際にありますので、できれば公園。","respondent":"寺嶋木密整備担当課長","answer":"先ほどもご答弁申し上げましたとおり、公園用地という名目で国費を入れて購入した土地です。１つ考えられるのは、近隣にもう少し適地がありまして、そこと交換するということは、これは制度上可能なので、そのあたりも含めての検討というふうにご理解いただければと思います。","voiceIndex":373,"id":"exchange-151"},{"speaker":"いながわ委員","kind":"質問","question":"３４３ページ、空き家等対策事業ということで、条例化をされて、どちらかというと、空き家の有効利用は別にして、俗に言う堆積家屋、ごみ屋敷と言われる部分をいろいろとこの条例をもとに進めていくという部分なのですが、実際に今あるところ、例えば、以前にもご質問させていただきましたが、旗の台四丁目、ちょうど通学路になる屋内型の堆積家屋というのですか、中から飛び出てしまっているような状況に。","respondent":"矢木住宅担当課長","answer":"１つには、有人の空き家でない住居につきましては、代執行につながる道というよりは、従前からあります地域の力支援チームでの庁内横断的な組織のもと、まず心のケア等々、その方の内面まで立ち入りまして対応を考え。","voiceIndex":375,"id":"exchange-152"},{"speaker":"たけうち委員","kind":"提案","question":"東日本大震災から明日で４年目ということになりまして、震災を踏まえて会派として、この道路空洞修繕の調査を提案してまいりまして、平成２５年度から３年ということで平成２７年度、ちょうどこの予算書、来年度で一旦終了すると思うのですが、防災上重要な道路について調査するということでしたので、それがこの平成２７年度で終了するかどうか、これについてお聞かせください。","respondent":"稲田道路課長、矢木住宅担当課長","answer":"平成２５年度３５km、平成２６年度も３５km、平成２７年度も３５kmというふうに計画しておりまして、測線長の距離なのですけれども、平成２７年度完了する予定で進めております。それから、街路灯建替のＬＥＤの価格の件です。対応といたしましては、今後とも住宅改善資金あっせん事業のＰＲをあらゆる機会を捉えてやってまいりたいのと、あと修繕の方につきましても、こういった助成もありますということでご案内をしていきたいと考えています。","voiceIndex":378,"id":"exchange-153"},{"speaker":"たけうち委員","kind":"質問・要望","question":"西大井のガードについては、私も本当にびっくりしたのですけれども、１日１回以上引き返すことがあるというので、一方通行で、しかもバスも通るところですから、本当に今まで大きな事故がなくてよかったと思うので、やっていただいた安全対策が有効かどうかもまた調査していただいて、その上でほかのところでも同じような危険があるようなところはしっかり見ていただきたいと、これも要望します。","respondent":"稲田道路課長、矢木住宅担当課長","answer":"来年度はそれの３年目です。来年度、この状況を精査しまして、他の自治体の状況等もありますので、その辺を精査しながら、今後については考えていきたいというふうに考えております。１０年の償還期間を１５年にですが、他区の状況、あるいは６信用金庫、相手方もありますので、またいろいろな情報を収集しながら研究してまいりたいと思います。","voiceIndex":381,"id":"exchange-154"},{"speaker":"たけうち委員","kind":"質問・要望","question":"空洞調査についてはそういうことでよろしくお願いします。だけど、やはり一番は知らないということ、また、もしくは知っていても借りるときになかなか１０年だときついというような声もあるのかもしれないので、ぜひその辺を調査していただいて、もしできるならばそういう形で、いろいろな形で進めていただければと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":384,"id":"exchange-155"},{"speaker":"伊藤委員","kind":"確認","question":"３２３ページ、津波・高潮対策事業、それから３１６ページ、橋梁費、３２５ページ、地域交通検討会経費に関連して質問します。これを防ぐためには水門が必要だということでありまして、立会川にそれがない現状でありますから、今の進捗状況の確認をまずお願いいたします。","respondent":"奥田河川下水道課長","answer":"今、委員からお話がありましたように、東京都の被害想定では、２３区最大の津波高が立会川の河口部に２.６１ｍというのが来るような形になってあります。ここにつきましては、ハード整備といたしましては、東京都と連携しながら水門等の事業を進めているところです。","voiceIndex":386,"id":"exchange-156"},{"speaker":"伊藤委員","kind":"確認","question":"水門をなるべく早くつくってください。それはぜひお願いしておきますので、よろしくお願いいたします。これは地域の方々から相談があったのですけれども、たしか大正８年から９年ぐらいの建設でありまして、建設から９４年から９５年ぐらい経過している。当然メンテナンスを行っていると思うのですけれども、耐震性とか耐久性はどうなのかという話がありましたので、その確認をお願いいたします。","respondent":"稲田道路課長","answer":"平成２５年度に橋梁長寿命化で点検をいたしました。断面欠損とか、そういう表面の劣化等があります。というところで、来年度におきましては、検討業務を行っていきたいというところを考えております。","voiceIndex":388,"id":"exchange-157"},{"speaker":"伊藤委員","kind":"質問","question":"そういう現状、設計図がないとするとびっくりしますけれども、そうすると、ほかの品川区の橋はどうなのかという思いがあるわけです。やはり長寿命化を図ることももちろん必要なのだけれども、当然こういうものは劣化していくわけだから、この時期にこういうふうなことを手入れしていくとか、橋全体に関してそういう計画をつくるべきではないでしょうか。改めてご答弁をお願いいたします。","respondent":"稲田道路課長","answer":"修繕計画を立てるというところであると思います。長寿命化の点検をしながら、その修繕を計画的に点検状況によって立てているという状況です。永久にもつというわけではございませんので、その辺のことも視野に入れながら考えているという状況です。","voiceIndex":390,"id":"exchange-158"},{"speaker":"伊藤委員","kind":"質問","question":"大切なインフラでありますから、ぜひよろしくお願いいたします。でも、これがとても費用対効果が大きなマイナスが出てやめた経過があります。ですから、今後、高齢化なり、さまざまな移動手段の確保については、当然私ども関心を持っているわけでありますけれども、多大な税金を投入して経営を支えていくようなバスの運行は避けるべきだと私たちは思っています。お願いいたします。","respondent":"中村都市計画課長","answer":"地域の輸送サービスの手段につきましては、委員ご指摘のとおり、１種類ではございません。さまざまな手法について研究をしてまいりたいと思います。","voiceIndex":392,"id":"exchange-159"},{"speaker":"伊藤委員","kind":"意見","question":"その合間をどう縫っていくかということが、この地域交通検討会議ではないのかと思うのであって、今のお話を基本として、では、もっとさまざまな手段を使いながら、高齢者の方々の足を確保していくというのか、できるだけ税金を節約していく、そういうようなことを考えていかないと、これからますます高齢化になっていくわけであって、確かに意見があって、そういう形にして欲しいという意見も。","respondent":"中村都市計画課長","answer":"例えば、バス路線で定期的に運行するようなことになりますと、空のバスを運行するというような可能性について非常に効率が悪いです。そういった意味からしますと、事業者とともに考えて適切な方法について、いい方法があれば、それを検討してまいりたいと思います。","voiceIndex":394,"id":"exchange-160"},{"speaker":"伊藤委員","kind":"意見","question":"要は、そこのところで、既存の考え方ではだめだと思うのです。だから、そういう意気込みをもってやってほしいと思うのですが、もう一声お願いいたします。","respondent":"中村都市計画課長","answer":"今いろいろ全国でもさまざまな取組みが行われているですので、そういったものの情報収集に努めてまいりたいと思います。そういった中で検討してまいります。","voiceIndex":396,"id":"exchange-161"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1028#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":118789,"voices":398}},{"id":"h27-20150311-3","meetingId":"h27-c-budget","date":"2015年3月11日","dateIso":"2015-03-11","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時５０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を170件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２７年度品川区一般会計予算","agenda":"平成２７年度品川区一般会計予算","exchanges":[{"speaker":"渡部委員","kind":"質問","question":"この間、日野学園から始まって６校が立ち上がって、子どもたち、日野学園の１期目の子たちは卒業もされているということで、今回プレス発表のほうにも事業目的があって、内容があって、構成がというふうに書かれているのですけれども、この中で幾つか質問したいと思います。具体的に少し内容ですとか、これはどういうところに向けて発信をしていくのか、もうちょっと詳しく教えていただければと思います。","respondent":"渋谷指導課長","answer":"品川区教育フォーラムの今の予定についてご説明申し上げます。午前中は品川区全ての小中学校、一貫校において、１・２時間目は授業公開、特に市民科、英語、ＩＣＴ、また体力向上等、今後の品川区の目玉になる教育の中身を見ていただくというものです。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡部委員","kind":"意見","question":"午前中は各学校でそれぞれ行われて、地域の方々に成果の発表ではないですけれども、このようなことをやっていくということで、また午後に関しましては、全国に向けても発信していくということで、とりわけ、確かに品川区は１０年間やってきました。逆に、午前中の学校見学も当然見ていただいて、また感想を述べてもらうなどの機会も欲しいなと思うのですが、ちょっとその辺の考え方をお願いいたします。","respondent":"渋谷指導課長","answer":"この周知に関しましては、ホームページはもちろんのこと、全国の教育委員会にご案内を発送する予定です。春先には一次案内を出させていただいて、秋には二次案内ということで、広く周知をさせていただこうというふうに考えているところです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡部委員","kind":"質問・要望","question":"すごくいい機会だと思います。品川区が今まで取り組んできたことを他地域に向けて大きく発信ができる機会ですので、多方面、さまざま活用して、漏れのないように説明等していただき、また今後の品川区のより小中一貫教育の発展に向けて活かしていただきたいと思います。次です。この文言が出てまいりました。","respondent":"渋谷指導課長","answer":"ポイントは、地域の皆様、今まで校区外部評価という形で評価だけだったのが、具体的な支援に積極的にかかわっていただけるように、また学校のさまざまな活動が地域の皆様にもっともっと貢献できるように、その橋渡しがうまくできるような仕組みをぜひつくっていきたいと。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡部委員","kind":"質問・要望","question":"とりあえず１年間その浜川中学校、浜川小学校、鮫浜小学校のモデルケースの中で、さまざまな課題等も見えてくることだと思いますから、それを活かして、平成２８年度以降になるのでしょうか、順次進めていただきたいのですが、防災、防犯上考えましても、やはり近隣学校と、それこそ町会、自治会のつながりというのは、この後の質問にもつながるのですけれども。","respondent":"品川庶務課長","answer":"いろいろ準備等を今行って実施をしているところですが、事前に町会に対してアンケートもとってあります。このアンケートの結果ですと、このスタンプカード事業、基本的には賛成だという意見が全体の８割に達しております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"町会長にはお話しされたかもしれないですけれども、実際運営をするべき青少年部の方々とかにもまず伝わっていないですよね。これはもう一回再考していいのではないでしょうかね。〔「そうだ」と呼ぶ者あり〕例えば、町会の方々に本当にお願いをして、学校で配るのではなくて、町会で配ったり、要するに町会の人が積極的にかかわっていただけるような仕組みでないと厳しいのではないですか。","respondent":"品川庶務課長","answer":"教育委員会としましても、ある程度説明がちょっと不十分なまま進めているということは非常に感じているところであります。その辺は少し反省しているところであります。","voiceIndex":12,"id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"町会は頑張っているわけですから。ですから、そういう思いもありまして、やっていただけるところに、やっていただくというような、しかも、やるのであれば、全学年に配っていただきたいなという思いがありまして、このような質問をさせていただきました。続けるのですから、しっかりと周知徹底、方法をもう一度お伝えいただければと思いますので、これは終わります。それ掛ける９５％だとしても。","respondent":"野呂瀬学務課長","answer":"学務課としましても、いろいろとこういう就学人口のシミュレーションを重ねてまいりました。当面は学校選択の運用で対応していきたいと考えております。","voiceIndex":14,"id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"私からは３４８ページ、教育指導費、３５９ページ、品川図書館運営費、３６７ページ、学校図書館運営費についてお伺いしたいと思います。私も昨年の第２回定例会で防災世界会議に触れつつ、レジリエンスの視点から品川区の防災対策の強化について幾つか提案もさせていただきました。こうした流れを受けて、一層の防災教育の充実が求められるところですが、新年度の防災教育の取組みについてお知らせください。","respondent":"村尾学校支援担当課長","answer":"安全への実践的な能力、態度、また習慣等の形成におきましても、いつ地震が起こるかわからないという現状の中ですので、各学校での避難訓練を中心に子どもたちに実践的に、もし地震等があった場合、どのような行動をするのか、またどのような判断をするのか。","voiceIndex":17,"id":"exchange-007"},{"speaker":"つる委員","kind":"質問・要望","question":"防災の教科化についても議論がされているところでありますので、子どもを通じた防災意識の啓発は「釜石の奇跡」を見ても明らかでありますので、一層の充実を図っていただきたいと思います。次は防災教育という視点で、就学前の子どもたちに対する防災教育についてお尋ねをいたします。今日は教育費ですので、幼稚園について、どのような防災教育を現在行っているか教えてください。","respondent":"竹田保育課長","answer":"防災に関する絵本、紙芝居等は幾つか種類があります。それぞれの園で随時読み聞かせ等を行うとともに、月１回は避難訓練を行い、幼保一体施設や小学校と同じ敷地の園では合同でやっているところです。","voiceIndex":19,"id":"exchange-008"},{"speaker":"つる委員","kind":"質問・要望","question":"今ご答弁がありましたとおり、さまざまな種類で絵本だとか紙芝居で防災について意識を啓発していくものがあると思います。そうしたものを活用しながら今後も就学前の教育の現場においても、そうした防災教育の工夫をしながら進めていただきたいと思います。次に、がん教育についてお尋ねします。改めて品川区も医師やがん経験者らの協力を得たがん教育を実施することを求めますけれども、いかがでしょうか。","respondent":"村尾学校支援担当課長","answer":"次年度におきましても、校長役員会等の場を活用しながらぜひ提案のございましたがん協会との連携、また各学校での取組みについて、今後研究をしてまいりたいと考えているところです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"ぜひ命の大切さを育むがん教育の推進を積極的にお願いしたいと思います。次にいきます。１８歳選挙権が来年の参議院議員選挙から適用される方向で現在法案も提出されているところであります。昨年の決算特別委員会の総括の中で、私も社会保障教育について質問させていただきましたが、改めてこの社会保障教育について先駆的に取り組むことを求めたいと思いますが、いかがでしょうか。","respondent":"村尾学校支援担当課長","answer":"子どもたちにとって、社会保障という一つの切り口だったと思いますけれども、このような活動をまた学校でそれぞれ社会科等の連携も含めながら、どのような形ができるのか、またどのような方向ができるのかという可能性についても。","voiceIndex":23,"id":"exchange-010"},{"speaker":"つる委員","kind":"質問","question":"二十代の投票率が低いという中で、住民投票になると、逆に若い方々が積極的な議論をして住民投票に参加をしていった全国的な事例もあります。この人権教育という観点でＬＧＢＴをはじめとする性的少数者への学校での教育について、どのような取組みを考えられているのか教えてください。","respondent":"村尾学校支援担当課長","answer":"今回さまざまな部分で取り上げられています性的マイノリティーにつきましては、現在も国のほうで人権教育の年間計画であったり、また先生方への正しい知識、理解を深めるための研修会等について検討が始まっておりますので、区といたしましても、その辺の内容を確認しながら。","voiceIndex":25,"id":"exchange-011"},{"speaker":"つる委員","kind":"提案","question":"図書館に移ります。そうしたことも含めて、以前、平成２５年の決算特別委員会、そして平成２６年の予算特別委員会でも学校図書館の名前を児童・生徒から募って命名したらどうか提案させていただいて、この計画の中にも明記をされております。まだ１校というふうに理解しておりますが、その図書館の名前と、また今後どのようにそうしたところの推進を図っていくのか教えてください。","respondent":"中元品川図書館長","answer":"今後今回の改訂版をこれから広く配付するなどして、このような取組みをご紹介して進めていけたらと思っているところです。","voiceIndex":27,"id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"推進計画を学校等に配っていただいていたのですが、やり方とかは当然学校単位でやると思うのですが、そのあたりは、何かアドバイスという形を教育委員会のほうとしてやっていくのか教えてください。","respondent":"中元品川図書館長","answer":"私どものほうで学校図書館担当でありますとか、そういうところから学校図書館サポートからのお知らせという広報物を不定期ではありますが、このような先進的な取り組みをご紹介するなどというところでサポートさせていただければと考えています。","voiceIndex":29,"id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"これはちょっと地域から聞いたお声を今お伝えしているのですが、ただその中に児童向けとか絵本とか、そういうジャンル分けは当然ある中で、絵本とか児童向けの中でも、幅広い年代があるので、例えば３歳とか４歳とか５歳とか、年齢別に何歳向けぐらいなのかということまでわかると非常に選択をしやすいという声があったのですが、そのあたりのシステム改修とか、もう少し簡単な方法でできるのか。","respondent":"中元品川図書館長","answer":"すみません、こちらは書誌データというものを事業者のほうから購入する形でダウンロードしておりまして、そちらのほうのデータで持っていないと実現が難しいところがあります。","voiceIndex":31,"id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"ごめんなさい、今のリストはペーパーで配付ということですか、インターネット上であるのか。","respondent":"中元品川図書館長","answer":"館のほうではペーパーですが、図書館のホームページに子どものページという入り口がございまして、そちらから入っていただきますとブックリストの表示もあります。随時こちらも定期的に更新をしていますので、お使いいただければと存じています。","voiceIndex":33,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"大きいシステムの改修とかではない範疇で、より一層使いやすい、わかりやすい検索にしていただきたいというふうに思います。悪戦苦闘を突き抜けて！予算特別委員会で新しい年度がスタートするに向けて、まさに今、行政の皆さんも悪戦苦闘する中で準備を進められていると思いますが、未来を託す子どもたちのために、よりよき教育環境の充実を求めて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-016"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"私からは３５５ページ、スクール・プロモーション、３４９ページ、３６３ページのＩＣＴに関連して、３５１ページ、３５２ページの小中一貫教育について質問します。初めに、スクール・プロモーションですが、これはどのような事業なのか教えてください。ＩＣＴについては、昨年の秋からスタートされたと思うのですが、約半年間行ってきてどうだったかというのをまず教えていただきたいと思います。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"このプレゼンをつくるに当たっては、学校現場、または子どもたちだけではなく、地域にいらっしゃるＩＣＴに強い方、そのような地域人材の方にぜひ講師になっていただいて、子どもたちと一緒に学校の魅力を発掘していただいて。昨年、２学期に導入されまして、当初はいろいろ戸惑うところもあったのですけれども、研修体制も整っておりまして、各教員に対しては業者から設置のときに使い方の研修をやっております。","voiceIndex":37,"id":"exchange-017"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"先ほど課長の答弁の中で、地域の人材を活用という話もありました。ＩＣＴなのですが、タブレット端末を利用する際に、ヘルプもサポートも一括しての契約をすると非常に経費削減になるので、先ほど委託というふうにあったのですが、このヘルプデスクというのですかね、というのはどこの経費に入っているのか、そこを教えてください。","respondent":"野呂瀬学務課長","answer":"平成２６年度予算では、いわゆる設置みたいなのが新規事業でしたが、設置したのを平成２７年度予算は運用していくと、そういう形で計上しております。","voiceIndex":40,"id":"exchange-018"},{"speaker":"石田（し）委員","kind":"質問","question":"経費削減になる部分もあると思うので、さまざまなところで一括契約みたいなものをぜひやっていただければなと思います。そんな中で、これまで小中一貫教育についてさまざまな評価、またいろいろな検証をされてきたかと思いますが、簡単で構いませんので、どのような評価をこれまで行ってきたのか、またこれからどのような評価を行っていく予定なのか、その辺を教えてください。","respondent":"渋谷指導課長","answer":"そのほか、やっぱり一番重要な子どもたちの意識、また先生たちの意識、保護者がどのように受けとめているのか等々については、それぞれアンケート調査を実施して、経年でずっと推移を見守っていきたいというふうに思っているところです。","voiceIndex":42,"id":"exchange-019"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"本当にたくさんの自治体が日野学園をはじめとする品川の学校に小中一貫教育の視察に来られていると思うのですが、そういった視察に来られた自治体からも、例えばこんなところがうちとは違っていいねとかいうのも僕は聞くことができると思うので、ぜひそういった幅広いところからヒアリングをしていただいて、今と前と何が違うのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは３６３ページの学校環境整備事業と、３６７ページの就学援助費、学校給食についても若干伺いたいと思います。学校環境整備事業ですが、小中学校のプールです。ぜひシャワーを温水にしていただきたいと思います。しかし、時代も変わり、生活様式も大分変わっています。学校のプールもぜひ温水にしていただきたいと思いますけれども、いかがでしょうか。","respondent":"品川庶務課長","answer":"それからあと、どうしてもシャワーを浴びるのに支障のある子、例えばアトピー性皮膚炎がある子とか、そういう子についてはそれぞれの学校で対応という形でやっているような状況です。","voiceIndex":46,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"７月から９月で夏の暑い時期だから温水にする必要があるのかとおっしゃいますけれども、既に民間のプールも、また区の一般開放している公園のプールも、どこもプールのシャワーは温水です。ぜひ学校も温水に私はすべきだと思います。学校の整備は時代とともに変わってきます。ぜひ学校の改築時はもちろん、既存校についてもシャワーを温水にしていただきたいと思いますけれども、改めていかがでしょうか。","respondent":"品川庶務課長","answer":"答弁が少し重なるかとは思いますが、やはりプールというのは暑い時期に入るというものですから、そこまで温水にというところをこだわるかどうかというところは少し疑問に思います。やはり、原則は水という形でシャワーはやっていく方向で考えております。","voiceIndex":48,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ子どもの教育環境の整備を進めてほしいと思います。続いて、就学援助です。就学援助の援助対象品目ですけれども、これは全額実費なのか、それとも補助率というものがあるのか、ちょっと仕組みを伺いたいのと、ここに生徒会費、ＰＴＡ会費が就学援助の援助品目の対象になっていない理由は何か伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"委員が持っているその表をよく見ていただきたいのですけれども、各区はほとんど就学基準の１.１倍、１.２倍を推移しているところを、品川区は１.２５倍ということで、他区よりも手厚くやっているということで、それは平成２７年度からも継続しているということは。","voiceIndex":50,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"伺ったのは、生徒会費、ＰＴＡ会費がなぜ対象でないのかと伺ったのですけれども、要するにほかがやっていないからというのが区の理由なのでしょうか。生徒会費やＰＴＡ会費、これは負担がかかるわけですから、社会の実態に合わせて対象にしたり、金額を引き上げることも私は必要だと思いますけれども、理由とあわせて伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"先ほども申しましたけれども、なぜ支給していないかというよりも、ＰＴＡ会費、生徒会費も含めて生活に困窮している方については就学援助という制度を通じて一定の補助をしているということで、言うならば、現行の制度の中に生徒会費、ＰＴＡ会費で支払うような負担は。","voiceIndex":52,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"ここになぜ生徒会費とＰＴＡ会費が入っていないのかと伺いました。ぜひ対象にすべきだと思いますので、この点、改めて伺いたいと思います。区は盛んに材料は保護者負担でと法律を説明しますけれども、国の基準に上乗せして、子育て支援としてぜひ給食の材料費に公費を入れて、献立の充実や保護者負担の軽減も進めていくべきだと思いますけれども、あわせていかがでしょうか。","respondent":"野呂瀬学務課長","answer":"それと、学校給食ですけれども、学校給食法で施設や設備に要する経費や人件費等は区の負担、それ以外の食材費については保護者の負担と決まっていますので、それから見ても給食費については公費を投入する考えはございません。","voiceIndex":54,"id":"exchange-025"},{"speaker":"藤原委員","kind":"質問・要望","question":"３５５ページのインクルーシブ教育なのですけれども、ここはなぜこういう新たな名前をつけたのかということと、事業内容を教えてください。幼保一体ではない単独の４園の園長がまず４人、２クラスずつですから、教諭が８人、用務員が４人だとしても、数字的に合計１６人になるのですけれども、ここで１人合わないと私は思うのですけれども、その辺についても教えてください。","respondent":"村尾学校支援担当課長、品川庶務課長、野呂瀬学務課長、堀越人事課長","answer":"実際に本区の今インクルーシブ教育につきましては、小学校２校が通級学級を指定して、通級学級に通っている子どもに対して。３６５ページの屋内運動場整備ですが、こちらは冨士見台中学校の体育館の床の張り替えを予定しています。ですから、ずっといわゆる「不検出」という形で報告をいただいて、それをホームページ等でアップしています。幼稚園の教員の人数ですけれども、教員につきましては１２名、それから再任用フルタイムの教員が１名おりますので、４園で１３名の配置。","voiceIndex":57,"id":"exchange-026"},{"speaker":"藤原委員","kind":"質問","question":"数値が高くないということで安心させていただいたのですけれども、でしたら、どこかで区切りをつけないといけないと思いますので、もうという思いも私はあるのですけれども、やっぱり環境に強い学務課長としては、やりたいのかなという思いもあるのですけれども、もうそろそろ数字的にも結果が出ているわけですから、区切りをつけなくてはいけないと思うのですけれども、その辺についてはいかがでしょうか。","respondent":"村尾学校支援担当課長、野呂瀬学務課長","answer":"本区では、平成２５年度から３年間モデル事業を進めております。このインクルーシブ教育は、今後、平成２８年度からいわゆる全国の全ての学校で取り入れる、そういう事業です。いろいろ意見があると思うのですけれども、区としましてはさまざまな意見、またその予算作成のときに、その時点で適時適正に判断させていただきたいと思います。","voiceIndex":62,"id":"exchange-027"},{"speaker":"藤原委員","kind":"確認","question":"インクルーシブなのですけれども、全校でやっていくおつもりなのですねというのをもう一回再確認でお願いいたします。","respondent":"村尾学校支援担当課長","answer":"区のほうでは、全校で平成２８年度から実施していく方向です。さらにこのインクルーシブについては、品川区はまさに文部科学省から委託を受け、先行的に研究を今進めているところです。","voiceIndex":65,"id":"exchange-028"},{"speaker":"吉田委員","kind":"提案","question":"これはもともと小山台小学校で何年か前からやってきた英語学習を平成２６年に新たに２校、三木小学校と城南小学校ですかね、モデル校として追加して、また平成２７年度にはさらに１４校実施ということなのですけれども、まず確認なのですが、小山台小学校がやってきた英語学習はどのようなものか紹介していただくのと、日本人英語専科指導員学習指導とはどんな指導なのでしょうか。","respondent":"渋谷指導課長","answer":"小山台小学校の取り組んだ中身とカリキュラムはほぼ同一なものです。中身につきましては、音と文字の関係性、元素記号みたいなものがあるのですが、例えば子音、母音、そういった音素というものと文字とのつながりをしっかりと認識する、音素認識を高めるものですね。","voiceIndex":68,"id":"exchange-029"},{"speaker":"吉田委員","kind":"意見","question":"どんな資格を持っていらして、すばらしい方がそろっているのかなと思うのですが、平成２６年度は何人だったのかということと、それから平成２７年度は何人の採用をお考えなのか、また先生方はどういう勤務体制なのか、その辺の採用の仕方、資格、平成２６年、平成２７年、それぞれの人数と勤務体制をお願いします。","respondent":"渋谷指導課長","answer":"今ご説明したように、大変専門的な知識だったり技術が必要だということで、今回新たに１０名追加するに当たっては公募させていただきました。","voiceIndex":70,"id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"そのとき、課長のほうで月１回の英語の研修がありますというお話だったので、月１回の英語の研修でどうやって英語力を子どもたちに教えていただけるのかなとちょっと心配だったのですけれども、担任の先生方の協力体制、担任の先生も一緒にいらっしゃると思うのですけれども、担任の先生と英語の先生との協力体制をお聞きしたいと思います。","respondent":"渋谷指導課長","answer":"児童の習熟状況の判断等から活動のステップを上げていったりだとか、英語に関することの指導をしております。担任の先生はＪＴＥと一緒に教壇の前に立って、児童の様子を把握して学級をコントロールするという役割、またＪＴＥとともに授業を進める。","voiceIndex":72,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、時間がないので次にまいりまして、国際理解の教育に関してなのですけれども、グローバル品川を目指して計画が進んでおりますが、小学校はすばらしい今のようなお話がありました。次のステップ、中学校に入る内容なのですけれども、国際理解教育の中のグローバル人材育成塾が開始から２年経過しましたが、改めて内容と、もう一つイングリッシュキャンプ、ついでにこの二つをお願いします。","respondent":"渋谷指導課長","answer":"今年度新規事業として、中学生のイングリッシュキャンプというものをやらせていただくような予定です。","voiceIndex":74,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"「パスポートの要らない英国」ですか、ちょっと調べさせていただいたのですが、すごくすばらしいところで、数多くの学校が利用しているようなのですけれども、希望者８０名だけでは寂しい。その機会を設けて、対象を広げて、これからいっていただきたいなと、私のこれは願いなのですけれども、ちょっとその辺を最後に一言お聞かせください。","respondent":"渋谷指導課長","answer":"公立の中学校でこれだけ大規模で送り込むのは品川区が初めてですので、そういった実績を踏まえて、また成果を検証して、今後考えていきたいというふうに思っております。","voiceIndex":76,"id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問","question":"４時間ほどで３・１１から丸４年になります。千代田区では九段会館で非構造部材が崩落をして、お亡くなりになる事故があり、品川区でも区有施設で一部事故がありました。昨年の定例会の議事録を見ると、教育長が「小中学校で６７か所の該当箇所があるということを調査でわかった」とおっしゃられているのですが、これはやはり全校でやる五十何校のうち、複数か所あるということなのかどうか教えてください。","respondent":"品川庶務課長","answer":"そうしますと、夏休みに全てをやるということになりますと、例えばプール開放なんかをやっている学校は、夏休み期間中全部使えないというような状況も出てしまいますので、日程に関しましては、学校別にそれぞれ校長先生と話し合いながらやっていくような予定になりますので。","voiceIndex":79,"id":"exchange-034"},{"speaker":"あくつ委員","kind":"質問・要望","question":"工事監理の監理というのは、現場監督の管理とはちょっと違うということで、工事を設計図書と照らし、それが設計図書のとおり実施されているかいないかを確認するということで、建築士が行うとあるのですけれども、これは平成２６年度に調査を行った会社が行うということなのか教えてください。","respondent":"品川庶務課長","answer":"発注の仕方なのですけれども、これは現在検討している段階なのですが、場合によっては１校のみで発注する場合も出てきますし、基本的にはまとめて発注というような形を考えております。","voiceIndex":81,"id":"exchange-035"},{"speaker":"あくつ委員","kind":"確認","question":"さまざまなちょっと細かいことを伺いました。一般質問で、款は違いますが、最新の労務単価、資材価格を反映させた適正な予定価格、改正品確法運用指針も出ましたけれども、まさに今度は教育委員会庶務課が発注者になって、そして施設整備課と連携をとられると思うのですが、この辺のお考えを確認させてください。","respondent":"品川庶務課長","answer":"そのメンテナンスをやるに当たって、発注の方法ですが、これは当然、品川区共通で言えるのかもしれませんが、地元業者を基本的には重視した形、それから適正価格に基づいた形で入札もかけていくというような考えで庶務課のほうもやっていきたいと考えていますので。","voiceIndex":83,"id":"exchange-036"},{"speaker":"あくつ委員","kind":"質問","question":"次、３６５ページ、便所改修工事費、毎回やらせていただくのですが、昨年は３月１２日、１日後ですが、予算特別委員会でも同じ質問をさせていただきました。学校トイレの改修、今年は３校、８,０２３万円、今回のトイレ改修の対象の学校を教えてください。これは補助金を使っていると思うのですが、この理由を教えてください。","respondent":"品川庶務課長","answer":"例年のトイレの改修費用に比べて、今年度はやや落ちているというところはありますが、やはり全体のメンテナンスの費用等を考えますと、今年度はトイレ費用を少し落としていくことで進めているというような状況です。","voiceIndex":85,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"質問","question":"非構造部材で減ったということで、よくわかりました。ＴＯＴＯの全体の出荷数を見ると、１９７６年は和洋半々で出していたのが、現在は９９％が洋式であると。何か促す場があるのか、学校避難所となった場合、やっぱり混乱してしまうと思うのですけれども、その辺の考え方というのは何かあるのか教えてください。","respondent":"品川庶務課長","answer":"そういう面では、やはり衛生面等を気にするということで、和式トイレのほうを使うという方もいるのかなと思いますので、学校としては全部を洋式にするという体制はやはり基本的には考えておりません。一部には、和式を残すという考え方です。","voiceIndex":87,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"もう一つ、これも毎回質問させていただいているのですが、改修の際には、児童がトイレの使い方、デザインなどを一緒に考えるような場をつくってほしい。これは３年前に質問させていただいて、浅間台小学校とか三木小学校で取り入れていただいたということなのですけれども、現在何校の小学校が子どもたちの意見を活かしたトイレ改修を行っているのか教えてください。その効果が何かあれば教えてください。","respondent":"品川庶務課長","answer":"具体的にはタイルの色とか、そういうものを決めてもらったりとか、そのようなことをやっております。現在は、平成２４年からこのデザインをしていただくということを始めていまして、平成２４年から平成２６年の間で現在のところ９校やっているという状況です。","voiceIndex":89,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回は２校、８,５４９万円ですか、一般財源ということですが、伊藤学園と日野学園、これを人工芝生化にした理由を教えてください。こういう説明だったと思うのですが、今回はスポーツ振興くじ、補助金の状況として、人工芝を対象としたスキームがあるのかないのか、もしあるのだとしたら、品川区はエントリーをしているのか教えてください。","respondent":"品川庶務課長","answer":"先ほどのトイレの件、当然子どもたちが色を選んでやっておりますので、非常に子どもたちも親しみを持ちながらトイレを使っているというような効果が出ているかと思います。それから、人工芝につきましては、今年度、日野学園、それから伊藤学園と２校進めていく予定です。","voiceIndex":91,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"粉じんが原因であるということを今日ご答弁いただいたわけですけれども、前々から申し上げていますが、特に小規模校ですね、一貫校は施設の面でかなりハード整備されていますけれども、これは何回か申し上げましたが、小規模校はさまざまな努力をされているわけですけれども、教職員の努力ではどうにもならないので、こちらも力を入れていきたい。そこのところを最後にご答弁いただけますでしょうか。","respondent":"品川庶務課長","answer":"補助金のほうにつきましては、今回計上はしておりませんが、申し込みはしております。それから、人工芝等につきましては、地域の状況とそれから学校の校庭、基本的には土でと考えていますが、そういう状況を踏まえましてかえていきたいと考えております。","voiceIndex":93,"id":"exchange-041"},{"speaker":"鈴木（博）委員","kind":"質問","question":"教育費全体を拝見して、アレルギー対応の予算を表示した箇所を探しましたが、見つかりませんでした。この間の一般質問等における食物アレルギー対応の質問で、食物アレルギーの検証、エピペン講習、アレルギー対応食器の購入など、さまざまなアレルギー対応の取組みをお伺いしましたが、なぜアレルギー対策費として予算に計上されていないのか、その理由をお尋ねいたします。","respondent":"野呂瀬学務課長","answer":"アレルギー対応についてのお尋ねです。アレルギー対応費として予算に計上されていないということですが、アレルギー対応については、従前より給食費等で対応を行っているところです。","voiceIndex":96,"id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"給食費で対応している。ほかにはあまり費用がかかっていないというお答えは理解いたしました。予算書に食物アレルギーの計上が全くないというのはいかがなものでしょうか。予算措置の項目を上げ、食物アレルギーに対する確実な対応を明示することは、しっかり品川区がアレルギー対応を行っているというメッセージにもなると思われますが、教育委員会のご見解はいかがでしょうか。","respondent":"野呂瀬学務課長","answer":"アレルギー対応につきましては、何よりも必要なのが教職員等の危機管理意識の向上だと考えております。それが一番重要だと考えています。このために必要な予算措置等は今後も行い、アレルギーの事故の防止に努めていきたいと考えております。","voiceIndex":98,"id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"質問","question":"第３回定例会に引き続き、眼科色覚検査についてお訪ねいたします。学校健診で色覚検査を行う意義は大きいと考えます。品川区では色覚検査は原則どなたが行っているのでしょうか。眼科校医の先生方と色覚検査の進め方、検査の方法、配慮の仕方等について、ご相談などは密になされているのでしょうか。ご説明をお願いいたします。","respondent":"野呂瀬学務課長","answer":"色覚検査を誰が行うべきか、検査の方法や進め方につきましては、今現在、学校保健会の学校医師部会および品川区眼科医会等と相談調整を行っているところです。","voiceIndex":100,"id":"exchange-044"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"先ほどお話がありました文部科学省の「学校において予防すべき感染症の解説」の本文でも、「診断は診察に当たった医師が身体症状およびその他の検査結果等を総合的に判断して行われるものであり、学校から特定の感染症の実施、ノロウイルスやインフルエンザ検査を求める必要はない」と述べられております。今、教育委員会のほうからご説明を伺いましたが、了解いたしました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":104,"id":"exchange-045"},{"speaker":"松永委員","kind":"質問","question":"私からは３４９ページの教職員研修について、３５１ページのいじめ防止対策について、同じく３５１ページの教育相談事業と調査研究事業について、時間がありましたら３６５ページの学校運営費について伺いたいと思います。３４９ページの校長研修等とありますが、この研修内容について、また教育事情視察の内容についてお願いいたします。","respondent":"村尾学校支援担当課長","answer":"校長研修会のお尋ねです。校長研修会は、本年度は２回実施しております。具体的な内容といたしましては、１回目は体罰防止に向けてということで、アンガーマネジメント研修を行いました。","voiceIndex":106,"id":"exchange-046"},{"speaker":"松永委員","kind":"質問","question":"校長研修等では、本年度予算に比べて８４５万８,０００円から１,５３９万６,０００円と増えておりますけれども、内容が変わったのでしょうか。","respondent":"村尾学校支援担当課長","answer":"この校長研修等の中に、実は学校経営監、指導員２名分の人件費が含まれているということで、金額的には大きくなっているというふうになっております。","voiceIndex":108,"id":"exchange-047"},{"speaker":"松永委員","kind":"質問","question":"理解できました。次に、３５１ページのいじめ防止対策について伺います。先月、川崎市で痛ましい事件が発生いたしました。それを受けて、たしか文部科学省では全国の公立の小中高を対象に緊急全国調査を実施するという報道があったと思いますが、この全国調査の内容と、また品川区ではどのような結果が出たのか教えてください。","respondent":"村尾学校支援担当課長","answer":"品川区でも文部科学省からおりてきた調査を実施いたしました。調査の内容は、「７日間連続して欠席し、さらに被害等、また暴力行為等、同様のものが考えられる事案はあるか」というような調査内容でございました。","voiceIndex":110,"id":"exchange-048"},{"speaker":"松永委員","kind":"質問・要望","question":"品川区でこういうことはないということであります。そのために、いじめ防止プログラムについてご説明いただきたいと思います。","respondent":"村尾学校支援担当課長","answer":"これは暴力防止プログラムといいまして、小学校の３年生と５年生が実施し、暴力を受けたときの対応の仕方であったり、またどのように相談をしていけばいいかというような学習です。いじめ防止等プログラムというものがここの中に入ってあります。","voiceIndex":112,"id":"exchange-049"},{"speaker":"松永委員","kind":"質問","question":"いじめ等根絶普及啓発では、前回たしか３１４万２,０００円から来年度は４１万３,０００円となっておりますけれども、その内容について改めて伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"本年度、各地域また関係団体にリーフレットを配る予定だったのですが、今後、いじめ条例等の制定もございまして、これについては本年度できませんでしたので、実際には来年度等を含めて検討していくということで、金額はこのようになっております。","voiceIndex":114,"id":"exchange-050"},{"speaker":"松永委員","kind":"質問","question":"学級風土調査について伺います。この学校風土調査では、全校で７年生を対象にしていると伺っておりますが、なぜ７年生だけなのでしょうか。","respondent":"村尾学校支援担当課長","answer":"そこでこの７年生を対象に子どもたち、各クラスの学級の様子を踏まえながら、その結果につきましては、各学校の担任、または管理職が確認をし、より学級等の運営、また指導に活かすため、７年生というふうになっております。","voiceIndex":116,"id":"exchange-051"},{"speaker":"松永委員","kind":"質問","question":"小学校でも、そうしたいじめの事件が発生していると思いますが、私は小学校高学年、４年生から中学２年生までにそういった調査を広げていったほうがいいのではないかと思います。低学年に関しては、教員との、昔の交換日記のような方法をとってみてはいかがでしょうか。ぜひご検討いただけたらと思いますが、その点について伺います。","respondent":"村尾学校支援担当課長","answer":"このＱＵ、またはｈｙｐｅｒ－ＱＵというのも実際には学級満足を調べるような調査でございまして、小学校についてはそこで子どもたち、またはクラスの様子をはかっていこうというふうに考えているところです。","voiceIndex":118,"id":"exchange-052"},{"speaker":"松永委員","kind":"質問","question":"３５１ページの教育相談事業と調査研究事業の内容について伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"調査研究事業費につきましては、これは実技研修ということで、理科、図工、美術、技術、家庭科、また音楽等の実技に関する研修を教員のほうが集まって、夏休み等が中心になるのですけれども、そのような形の部分になっております。","voiceIndex":120,"id":"exchange-053"},{"speaker":"松永委員","kind":"質問","question":"教育相談事業についてですが、品川区の教員の方から相談に来られたこともあると思いますが、相談内容とか、もしご紹介できたら伺いたいと思います。年間どのくらいの教員の方が相談に来られたのでしょうか、伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"かかってくる電話相談については２７４件と、やはり多くの相談が入っております。これにつきましては、それぞれセンターの心理士が、来室については親との相談や、また子どもとの直接相談等を含めて実際に進めているところです。","voiceIndex":122,"id":"exchange-054"},{"speaker":"松永委員","kind":"質問","question":"調査研究事業についてですが、これは教員対象ということで、これは自主的に行うものなのでしょうか。そしてまた、何回も実技研修を行うことができるのでしょうか。","respondent":"村尾学校支援担当課長","answer":"一応基本的には予算取りもありますけれども、各年間１回、内容的には２回興行ということで行っているところが中心です。","voiceIndex":124,"id":"exchange-055"},{"speaker":"松永委員","kind":"意見","question":"最後に、今年の４月１日から設立予定の品川区立教育総合支援センターですが、いろいろな専門分野の方が対応できるセンターに生まれ変わろうとしておりますが、それに向けての意気込みをお聞かせください。","respondent":"村尾学校支援担当課長","answer":"まさに今までさまざまな課題があった、いわゆる教育相談に関する窓口、またそれぞれの連携の仕方と課題を今までもずっと相談をしてきまして、実際に４月から相談窓口の一本化、また組織体制を関連する組織が一緒になりますので、それにおける対応力、それから機動力を高め。","voiceIndex":126,"id":"exchange-056"},{"speaker":"松永委員","kind":"確認","question":"最後に、３６５ページの学校運営費について伺います。ここでは１点だけの確認なのですが、平成２６年度には以前、空港周辺環境整備で２校に２００万円とあったと思うのですけれども、平成２７年度では掲載されていない理由について伺いたいと思います。","respondent":"野呂瀬学務課長","answer":"平成２６年度で補助が終了したものです。","voiceIndex":128,"id":"exchange-057"},{"speaker":"横山委員","kind":"確認","question":"私は、３４９ページの品川区研究学校、３５３ページのイングリッシュキャンプ実施、３５５ページのしながわドリームジョブ、そして３６３ページの学校環境整備事業についての確認をします。１点目に、先ほど吉田委員から質問がありましたが、イングリッシュキャンプの実施について、２３区初のイングリッシュキャンプの実施ということで、大きなインパクトを与える事業かと思います。","respondent":"渋谷指導課長","answer":"平成２７年度のグローバル人材育成塾の説明会に合わせて、このイングリッシュキャンプの説明も行う予定です。今のところ、４月の第３土曜日に説明会を実施する予定です。","voiceIndex":132,"id":"exchange-058"},{"speaker":"横山委員","kind":"質問","question":"こちらは本当に先ほど申し上げましたけれども、２３区初ということで、またこのブリティッシュヒルズを私も数年前からずっと注目しているのですけれども、こちらの設備はすごくすばらしいものがあります。２点目なのですけれども、学校環境整備事業についてお伺いいたします。工事期間の授業、部活動など、生徒、保護者、近隣の地域の方々などへの影響と対策についてもあわせて教えてください。","respondent":"品川庶務課長","answer":"取得の金額ですが、約２億３,０００万円となっています。それから、工期につきましては、大体７月から工事を始めまして、完了は１月末となっております。近隣関係の周知に関しましては、これから説明会を行っていく予定です。","voiceIndex":134,"id":"exchange-059"},{"speaker":"横山委員","kind":"質問","question":"すみません、ちょっと今、私の質問がちょっと早かったのでもう一度申し上げます。近隣の方への影響と対策について、こちらを教えてください。","respondent":"品川庶務課長","answer":"近隣への影響ですけれども、土地の高低差が多少ありますので、擁壁工事等、そういう部分で振動等が発生する可能性が若干あるです。","voiceIndex":136,"id":"exchange-060"},{"speaker":"横山委員","kind":"質問","question":"高低差のために擁壁工事によって振動が発生する旨、住民の方ですとか、保護者・生徒の方に説明をしていただくということでよろしいでしょうか。次、３点目なのですけれども、品川区研究学校についてお伺いいたします。通塾率の高い小学校において、学力の二極化、児童の学力差の課題があります。","respondent":"渋谷指導課長","answer":"今、委員がご説明いただいたのは、第二延山小学校が研究学校として１年次の中間発表を行ったものです。","voiceIndex":138,"id":"exchange-061"},{"speaker":"横山委員","kind":"質問・要望","question":"授業の改善、教員の指導方法、児童の学習法と学習観の変容など、実施校の意見、そして報告会で他校の教員等によるアンケートの実施をしていたかと思うのですけれども、そちらの結果がもしありましたら、１年目の成果を教育委員会としてどのように捉え、区全体の学力向上に活かしていくお考えなのか、そして来年度、２年目の研究内容と課題についてもお伺いいたします。","respondent":"渋谷指導課長","answer":"家庭や地域への理解と促進ですが、先ほども申し上げたとおり、ＰＴＡ等々にも家庭学習のあり方、どのような声かけがいいのか、見守り方がいいのか等について、ぜひ提案をしていただきたいと考えているところです。","voiceIndex":140,"id":"exchange-062"},{"speaker":"横山委員","kind":"質問・要望","question":"４点目なのですけれども、しながわドリームジョブについて、若手職員からの発案ということでお聞きしました。そこでお伺いいたします。将来の夢を持ち、かつその実現に向けて具体的に努力をする児童・生徒を育てるために、どのような指導、そして支援が必要でしょうか。しながわドリームジョブの詳細な内容に合わせて、品川区のお考えをお聞かせください。","respondent":"渋谷指導課長","answer":"そういう流れとともに、中学校では一部、しながわ寺子屋等々、いろいろな職業の実際のお話を聞くような機会を設けるような取組みを一生懸命やっているところですが、今回のしながわドリームジョブについては、さらにそれを小学校段階に下げて、しかも一般の企業の方に限らず。","voiceIndex":142,"id":"exchange-063"},{"speaker":"横山委員","kind":"質問・要望","question":"私は今年１月に品川区の成人式と、あと２分の１成人式にも出席いたしました。しながわドリームジョブと２分の１成人式を線で捉えまして、２分の１成人式の前にさまざまなロールモデルとの交流を通して、児童への価値ある複数の選択肢の発見を支援していただきたいと考えますが、しながわドリームジョブにご協力をいただく講師の選定方法と対象学年について、最後に教えてください。","respondent":"渋谷指導課長","answer":"講師の選定方法については、まさに今検討しているところで、できるだけ区民の中で身近なところから、そういった人材の発掘に努めていきたい、またそういった方たちには、今後、教育大使のような形でさまざまな場面でかかわり合っていただきたいというふうに考えているところです。","voiceIndex":144,"id":"exchange-064"},{"speaker":"塚本委員","kind":"質問","question":"初めに、３５７ページの特別支援教育費に関連してなのですが、事務事業概要には、見ますと、平成２７年４月に浅間台小学校と上神明小学校に特別支援の固定級を開設する予定であるというふうに書いてありますけれども、特別支援の固定級につきまして、いわゆる発達障害、情緒障害の固定級というのが品川区の小学校、また中学校、今どのような設置になっているのかということを最初にお伺いしたいと思います。","respondent":"村尾学校支援担当課長","answer":"品川区においては、情緒学級の固定級というものはございません。","voiceIndex":147,"id":"exchange-065"},{"speaker":"塚本委員","kind":"質問","question":"基本的には小学校については通級という形でいろいろこれに対応しているというふうに思いますけれども、中学校の通級はあると思いますけれども、固定級はないということで、いわゆる通級における対応ということでありますけれども、固定級を望む親御さん、発達障害をお持ちのご両親で、固定級でのそういった教育を望むという場合に、品川区としてはどのような説明というか。","respondent":"村尾学校支援担当課長","answer":"品川区における情緒学級の固定級についてのご質問だと思います。現在２３区内におきましては、いわゆる情緒障害等における固定学級を設置しているのは、２３区内では小学校が３校、そして中学校が２校というまだ現状です。","voiceIndex":149,"id":"exchange-066"},{"speaker":"塚本委員","kind":"質問・要望","question":"そういう中で、固定級の中でしっかりとしたそういう対応をしていただきたいという要望が、やはり一定程度あるのだろうと思うのですね。この中で、品川区としてもそういったニーズに応える上では、やはり固定級というものを小学校、中学校に設けていくという必要性もあるのではないかと思いますので、もう一度その点についてご答弁いただきたいと思います。","respondent":"村尾学校支援担当課長","answer":"実際にそのような声があることについては十分承知しています。ただ、先ほども申し上げたとおり、今後、固定級を必要とする子どもたちの人数であったり、国また都全体の流れ等を踏まえまして、しっかり検討していくことになるかなというふうに考えております。","voiceIndex":151,"id":"exchange-067"},{"speaker":"塚本委員","kind":"質問","question":"共働きの場合に、朝、急に休校になってしまったので子どものお昼のこととかのために休まなければいけないということは難しいし、また早目に出勤した場合に、子どもが自分で登校する、しないというのを警報などを見ながら判断するのは大変難しいというようなことで、もうちょっと早く判断できないのかという話が大変にあったかと思いますけれども、そのことを受けて。","respondent":"村尾学校支援担当課長","answer":"実際には本年度、平成２６年度に各学校、それから保護者のほうには今委員のご説明いただいたとおり７時、９時という段階で、前回の１０月の件がありまして、こちらでもさまざま検討したのですけれども、また急に対応を変えるよとなると。","voiceIndex":153,"id":"exchange-068"},{"speaker":"塚本委員","kind":"質問・要望","question":"急な変更はということは、一定程度そういうことはあるのかもしれませんけれども、やはりこれだけいろいろなお声がある中で、確かに前日、よその区なんかでは早目に休校という判断をしている区なんかもありますけれども、朝になってみたら見事に晴れていたみたいな、今回の大雪なんかはまさにそんな感じで、今、天気予報なんかは、基本的には早目早目に予報を出すので。","respondent":"村尾学校支援担当課長","answer":"今まさにこちらのほうで検討し、また校長役員会等でも検討している中で、方向性といたしましては、今委員のおっしゃるとおり９時は実際にはいろいろな問題があるだろうということで、７時の時点での判断というふうに方向性としては考えております。","voiceIndex":155,"id":"exchange-069"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、３５１ページのいじめ防止対策に関連してお聞きしたいと思います。そしてあと、この品川区でもいじめによって子どもがみずから命を絶つという悲しい事件がありましたけれども、それによってＨＥＡＲＴＳなどをつくられて、対策がとられているわけですけれども、このＨＥＡＲＴＳ、また学校現場でつかんでいる現在のいじめや学校の現状、そしてまた問題や課題が今あるのかどうか伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"２番目については、品川区でいじめ等さまざまな問題が起きたときに対応できるということで、委員おっしゃるとおり、ＨＥＡＲＴＳが区に設置されました。","voiceIndex":158,"id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"やはり大人には見えないところでいじめは起きます。その子どもたちに寄り添い、いじめを発見し、解決するかぎを握るのが教員だと思います。しかし、その教員がいじめの対応の時間が足りないと。一般紙の調査でも７割以上が時間が足りないということを教員が答えているわけですね。このような状況を一刻も早く改善させるべきだと思うのですけれども、いかがでしょうか。","respondent":"村尾学校支援担当課長","answer":"それがいじめの早期発見もそうなのですが、教員だけではなくて、保護者会等でもとにかく親にも相談できるような、そういうような触れ合う時間も特に大切にしてほしい、そのような形でいじめの早期発見については努めているところです。","voiceIndex":160,"id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"質問","question":"先日、小学校５年生の子どもを持つ友人と会いまして話をしていたところ、子どものほうからいろいろな学校での悩みや愚痴などが出されたのですけれども、そんな深刻なものではなかったのですけれども、そういったことを「先生には相談しているの」ということを聞きましたら、「先生は忙しいからだめなの」と、子どもさんから、そういった声が出されたので、ちょっと私も驚いたのですけれども。","respondent":"村尾学校支援担当課長","answer":"先生方が、子どもから見るとすごく忙しそうに見えるということは、こちらの教師側の問題かもしれないのですが、その中で、区のほうでは目安箱であったり、またたまたまその先生にも相談ができないようなときに。","voiceIndex":162,"id":"exchange-072"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり今の教員の皆さんの多忙化には、上からの押しつけの教育改革が大きくのしかかっているのだと思います。ぜひその大もとのところを考えていっていただきたいと思います。ですので、その子どもたちに安心して安全に学べる環境をしっかりと提供していくことが必要だと思いますけれども、教員と子どものストレス、そして多忙化の関係をどうお考えでしょうか。","respondent":"村尾学校支援担当課長","answer":"それにおきましても、子どもたちのストレスについては、一つは市民科の中で例えばストレスコントロールの授業を取り入れたり、いろいろな場面で学校では対応しておりますし、家庭においてもぜひ子どもとの会話を増やしてほしいとか。","voiceIndex":164,"id":"exchange-073"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういうもとで、学校や家だけではなかなか解決できない部分もあるのかなというところでは、私たち区議会としても安心安全な教育環境をつくっていくことに本当に全力を尽くしていくわけですけれども、それにプラスして、スクールカウンセラーやスクールソーシャルワーカーの皆さんなども配置されているというところですけれども、平成２６年度の予算には。","respondent":"村尾学校支援担当課長","answer":"内容につきましては、巡回相談員ということで、今までスクールカウンセラーは各学校に週１日配置になっておりましたが、今回、巡回相談員ということで、小学校と中学校をグループ化して、そこを２週間に一遍、学校に訪問させていただいて。","voiceIndex":166,"id":"exchange-074"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、子どもたちと接するというか、学校に行く回数が減ったということなのか、そして人数は変わりないのか、そして雇用形態も伺いたいと思います。","respondent":"村尾学校支援担当課長","answer":"実際は巡回相談員につきましては、昨年度１２名いたところを実際に１０名という形でスクールカウンセラーになっております。区内の小中学校を１０ブロックに分けて、そこを２週間に一遍、配置するです。勤務については全て非常勤職員ということで進めているところです。","voiceIndex":168,"id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"では人数が減っているということですね。そして、回数も減っている、これだけ学校環境が大変な中で、本当に大事な役割になっていますので、ぜひ増やしていただきたい、そして正規雇用で働いていく、そして子どもたちの命を本当に守る、いじめを学校からなくしていく、この対策を強化していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":170,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問","question":"私は、３６７ページの教育振興費の就学援助費と、３４９ページの教育指導費、巡回相談員等経費についてお伺いをいたします。来年度、新年度も同様ということで評価をしておりますけれども、やっぱり区長の英断ということなのでしょうか。さきの第１回定例会で、教育次長が就学援助費は社会状況を見て検討していく旨の答弁をいたしました。この答弁の真意を伺います。","respondent":"野呂瀬学務課長","answer":"社会状況と変化の中には、当然いわゆる、経済状況だとか、例えば区内の就学人口だとか就学援助の認定率だとか、もちろん区の財政状況、今後どういうふうな形で進んでいくかという見極め、そういうのを総合的に勘案して、それで社会状況の変化を見極めながら判断する。","voiceIndex":172,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問・要望","question":"品川区の就学援助費受給者が小学生では２３％、中学生では３５％です。次、今も出ましたけれども、スクールカウンセラー等派遣費が平成２７年度には巡回相談員等経費ということで、今説明もありましたけれども、変更に至った課題が何なのか、そして変更したことで解決が図られるのか、そして期待される成果についてどのようなものを持たれているのかお伺いをいたします。","respondent":"村尾学校支援担当課長","answer":"ただ、小中一貫教育を進めている品川区ですので、その部分につきましては、小学校と中学校をグループで回ることによって子どもたちの９年間の学びの一つの視点としてカウンセラーが対応できるというふうになっております。","voiceIndex":174,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"今までスクールカウンセラーというのは、心のケアということで対応されてきて、子どもたちが相談をする、今おっしゃるところによれば、教育委員会とか指導者側がどういうふうな合理的配慮とか、子どもたちに向き合えることが、教師ができているかというような発想で変わっているように聞こえるのですけれども、本来スクールカウンセラーが配置をされた意味というのは。","respondent":"村尾学校支援担当課長","answer":"その部分につきましては、まさに心の部分についてはそれぞれの都費、また区の巡回相談も同じような形で子どもたちにかかわることについて変わりはございません。","voiceIndex":176,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問・要望","question":"そこはしっかりとやっていただきたいと思います。それから、スクールソーシャルワーカーですけれども、２名から４名に新年度は増員されるということで大変評価をしております。幸い品川区にはスクールソーシャルワーカーがおりますので、福祉の視点で子どもを救済できたケースというのは、区内にあったのか、そのような事例があれば紹介してください。","respondent":"村尾学校支援担当課長","answer":"まさに来年度からスクールソーシャルワーカー４名ということで、より幅広く子どもたちの対応ができると考えております。本年度、スクールソーシャルワーカーのかかわりについては、実際に福祉とつながったというケースについても何件か報告を受けております。","voiceIndex":178,"id":"exchange-080"},{"speaker":"井上委員","kind":"意見","question":"具体的には橋渡しと。やっぱりスクールソーシャルワーカーは環境整備で、その子どもが置かれている、子どもをいかにいろいろな環境資源を使って救っていくかということなのですけれども、紹介できる範囲で、もう少し具体的にお願いします。","respondent":"村尾学校支援担当課長","answer":"具体的にはちょっとなかなかこういう場で説明が難しいところなのですが、実際には福祉関係につなげてみたり、また各関係の、警察関係とつながりながら、その子の健全育成を図っていくとか、いわゆる子どもに応じた地域、また家庭、それから本人の結びつき。","voiceIndex":180,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問・要望","question":"ですから、ここのところでせっかく品川区が持っているスクールソーシャルワーカー、教育委員会の中で頑張り過ぎると、結果的に子どもを追い詰めてしまうので、ぜひ信頼し合って事業を進めていただきたいというふうに思います。私も見にいってきましたけれども、やっぱりモデル事業を持っている品川区ですから、ぜひご覧いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":182,"id":"exchange-082"},{"speaker":"沢田委員","kind":"質問・要望","question":"３５７ページの教科書採択事務についてお伺いをします。安倍内閣になって教育改革が大変進みました。この開かれた採択ということで幾つか質問させていただきたいと思います。この委員会について、まずどのような形でこのメンバーが選任されているのか、それからどれくらいの期間で、どのような客観的な調査を行っているのかを詳しく教えてください。","respondent":"渋谷指導課長","answer":"教科用図書調査検討委員会では、ここで教科書採択に必要な調査資料を作成するために、この下にさらに教科書調査研究会を教科ごとに置いて、そこでの資料作成を依頼して、そこから上がってきたものについて。","voiceIndex":184,"id":"exchange-083"},{"speaker":"沢田委員","kind":"質問","question":"必要な客観的な調査というのは、ここでやられているということでしたけれども、具体的にどのような調査をされているのか、その前段階での教職員の方たちによる教科書調査研究会から上がってきた教科書に関するデータをもとにした客観的な調査というのはどういったことをされているのか教えてください。","respondent":"渋谷指導課長","answer":"例えば、内容については発達段階に対する配慮がされているのか、内容のわかりやすさ等配慮はされているか、教科の特質に即した内容の重点化や考え方への配慮はされているか、発展的な学習内容について配慮されているか、それ以外にも構成および分量、あるいは表記および表現。","voiceIndex":186,"id":"exchange-084"},{"speaker":"沢田委員","kind":"質問","question":"それに関連して、昨年の一般質問の中でも、教科書採択の採択理由を明確に公表すべきという質問に対して、今後はより開かれた教科書採択を目指し、採択理由も公表するという答弁を区からいただきました。この採択理由を公表するということについて、これをどのような形で公表をされていくのか、内容等、方法等についても聞きたいと思っています。","respondent":"渋谷指導課長","answer":"次年度、中学校の教科書採択が行われます。この要綱、要領については、今後きちっと公開するということで見直す予定です。内容、方法については、ただいま研究中ということで、今この場で確定的なことは申し上げられません。","voiceIndex":188,"id":"exchange-085"},{"speaker":"沢田委員","kind":"質問・要望","question":"このようなことから、先ほどの教科用図書調査検討委員会での客観的な調査ということでありましたけれども、調査を行うに当たっては、やはり数値、比較、点数評価とかをしていくべきではないかと思うのですけれども、そういったところのお考えというか、点数化して、しっかりと評価をしていくということに関するお考えをお聞かせください。","respondent":"渋谷指導課長","answer":"次年度の要領については、先ほどもご答弁の繰り返しになりますが、今後検討していくところですが、なかなか例えば地域性について点数化をするというと、その部分での評価基準をどういうふうにするのかというところが大変難しい問題だというふうに思っております。","voiceIndex":190,"id":"exchange-086"},{"speaker":"沢田委員","kind":"質問・要望","question":"先ほどもありましたけれども、今年の７月に中学校の教科書採択があります。ただ、やはり教科書が教育の基本であって、教科書をもとに授業を進めていくということを考えたときに、これからの日本を背負っていく子どもたちがしっかりとその教科書をもとに勉強していくわけですから、それをしっかりとした過程で、見える明確な基準のもとでしっかりと客観的な調査を行っていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":192,"id":"exchange-087"},{"speaker":"大倉委員","kind":"提案","question":"午前中も渡部委員から質問がありましたが、スタンプカード事業、これは私の知っているところでも、町会長は知っているけれども、ほかの方が知らなくて、そこではそういった、これはどこにあるのですかというところの質問とか、お問い合わせはなかったのですが、ずっと１か所に、袋に入れて置いてあって、これはどうやって使うのだろうという質問を町会の人から逆に受けて、しっかり周知というのを。","respondent":"品川庶務課長、上垣外生活安全担当課長、小林施設整備課長、村尾学校支援担当課長","answer":"このスタンプカード事業、先ほどご答弁したとおり、なかなか学校選択制を敷いている中で。これを受ける窓口もそれなりの対応が必要であるということで、検討課題がたくさんありますので。それとあと、温度と湿度の確認を行っております。その報告をもとに最近の床の隙間等はかなり落ち着いてきたかなという考えを持っております。その表にはアイシグナルのマークがついており、またＨＥＡＲＴＳ専用電話の電話番号も載せているところです。","voiceIndex":194,"id":"exchange-088"},{"speaker":"大倉委員","kind":"質問・要望","question":"子ども地域活動支援については、景品も縄跳びとかヨーヨーとかさまざま、そういった景品というふうに伺っています。まもるっちに関しては、番号を登録してはどうですかということだったのですけれども、なかなか難しくて、１個のチャンネルで一つの相談窓口、ここへ電話すると何か困ったことができたら話を聞いてくれるよということが、窓口が多いという部分で必要だと思ったので聞きました。","respondent":"小林施設整備課長","answer":"これは現実的にわかりました。業者と打ち合わせをしている段階で、床下の換気量が過大過ぎたのではないかということがありましたので、まずはその対策を講じていきましょうということで装置をつけたところです。その後、隙間が落ち着いてきたというのが目視でわかりました。","voiceIndex":199,"id":"exchange-089"},{"speaker":"こんの委員","kind":"質問","question":"私からは、３６１ページの地区図書館運営費、３６３ページの学校環境整備事業、３６９ページの小中一貫校標準服費、この３点でお伺いします。学業に必要なものなので、これは全家庭に買っていただくというものですけれども、いわゆる専門の業者がずっとつくってこられたものだと思うのですけれども、今現在、おおよそで結構です、冬服で１人当たりどれぐらい金額がかかっているのか、教えてください。","respondent":"中元品川図書館長、品川庶務課長、野呂瀬学務課長","answer":"特に障害者サービス、児童サービスにつきましては、各地区館から障害者の方に訪問するサービスも今用意をしておりますし、児童サービスにつきましても。土のグラウンドなのですけれども、おおむねですけれども、大体３５校程度が土のグラウンドとなっています。１５校、中学校はありまして、大体２万７,０００円から３万３,０００円、３万４,０００円の範囲ですので、平均しますと３万円ぐらいかなです。","voiceIndex":202,"id":"exchange-090"},{"speaker":"こんの委員","kind":"提案","question":"今、最大で２０冊まで借りられましたでしょうかね。こういうのはいかがでしょうかというところです。それから、障害者の方に既にされているということですが、宅配というようなサービスを妊婦さんとかあるいは高齢者の方にもどうなのでしょうかというところもお願いしたいと思います。それから、校庭の土です。それで、就学援助を受けていらっしゃる方々も、１年生と５年生ですかね。","respondent":"中元品川図書館長、野呂瀬学務課長、品川庶務課長","answer":"１点目のカートの導入ですが、ちょっと実施に当たっては検討する課題が大きいかなと考えています。品川区の図書館、地区館は小さい館が多うあります。基本的に制服は私費でやっていただくものですし、デザイン等もＰＴＡの意見も取り入れているというのも聞いておりますので。校庭の件につきましては、現在体育館等もいろいろ利用しながら工夫はしている状況ですが。","voiceIndex":206,"id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"私からは３６７ページの防災ヘルメット、３５１ページのいじめ防止対策費、３７３ページの学校改築推進費です。防災ヘルメットなのですが、設置状況はどういうふうになっているでしょうか。訓練はどのような訓練で使われていますか。それと、どこに保管していますかということをまずお聞きしたいと思います。","respondent":"野呂瀬学務課長","answer":"設置状況ですけれども、中学１年生に上がるときに全員に配って、これはまさに今日は３・１１ですけれども、３・１１以降、その翌年に全中学生に配りました。それ以降は毎年中学校に上がるときに、いわゆる７学年になる人数に全て配付しているという状況です。","voiceIndex":211,"id":"exchange-092"},{"speaker":"西本委員","kind":"質問・要望","question":"７年生に配付をして訓練をしているよ、保管のほうは何か邪魔になっている部分があるのですよね。その場合に、今、折り畳み式のヘルメットがあるのですよ。これは学校だけではなくて、防災課も関係するかと思いますけれども、折り畳み式ですと持ち歩きもできるということで、非常にいいものが出ているので、ぜひご検討していただきたいと思いますのでいかがでしょうか。","respondent":"野呂瀬学務課長","answer":"それとやはり、折り畳み式は強度の面だとかコストの面でいろいろ課題があるということで、今配付は普通のヘルメットをしています。","voiceIndex":213,"id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"２月２７日に伊藤学園でいじめ防止に関する取組みというテーマで大井第一小学校、山中小学校、伊藤学園の取組みをお聞きしました。そのアンケートは、こそこそ話は何を話しているのですか。やっぱり、山中小学校のやっていることの意義というのをしっかりと受けとめて、根絶協議会とか、啓発の取組みをやっていますけれども、少し見直しを図ってはどうかと思うのですが、品川区の見解をお聞きします。","respondent":"村尾学校支援担当課長","answer":"全小学校、中学校から代表の子どもたちが出て、さまざまないじめ等の取組みをやる会なのですけれども、その中でも、やはりそれぞれの各学校の生徒会の方たちや児童会の子たちが本当にいじめに向かっていろいろな企画をして、また取組んでいるということもありましたので。","voiceIndex":215,"id":"exchange-094"},{"speaker":"西本委員","kind":"質問","question":"非常にいい取組みだと思います。まさにこれがいじめ根絶の根底になるのではないかなというふうに私は本当に思いましたので、ぜひとも全校に広がるように啓発をお願いしたいと思います。そして、小中一貫校は６校で終わりなのでしょうか。一応６校で終わりですよということなのですが、今後そういうことも含めて検討段階に入っているのか、全くそれは考えないという方向でいくのか、いかがでしょうか。","respondent":"品川庶務課長","answer":"一貫校の件ですが、６校までということで言い切ることはできないというような状況です。ただ、今後つくっていくというところに関しましては、いろいろと研究をしながらやっていきたいと考えております。","voiceIndex":217,"id":"exchange-095"},{"speaker":"西本委員","kind":"質問","question":"順番を考えていない、順番はいろいろな状況によって変えていただければいいですけれども、でも当然ながら、今改築されていないところがあるわけでして、そこは順次、当然考えているのですよね。と考えています。それから、一貫校につきましても、いろいろ５年先なのか、１０年先なのか、これは見直しというのは図っていくのだろうなと思いますが、その辺のご意見はいかがでしょうか。","respondent":"品川庶務課長","answer":"改築に関しましては、先ほど言いましたように老朽化の順番等を考えていきたいと思います。","voiceIndex":219,"id":"exchange-096"},{"speaker":"渡辺委員","kind":"質問","question":"３５３ページ、合同部活動実施経費を中心に関連も含めて伺っていきます。今部活に関しては、すごく期待も大きいですし、いろいろな要素が、地域からもそうですし、あるかと思います。それとあと、これも平日の日数、活動日数というのですかね、例えば部によってもちろん違うのですが、あと土日、祝日の活動状況、これも大まかで構わないです。","respondent":"渋谷指導課長","answer":"特に女子の中学生については運動離れが進んでいるということが現実として認識されているのかなというふうに感じているところです。","voiceIndex":223,"id":"exchange-097"},{"speaker":"渡辺委員","kind":"質問・要望","question":"７割と３割というような形で。この点の仕組みをどうしていくか、意向をくみ取るといいますか、要望をくみ取るのを今後どのように発展させていくかを聞きたいのが一つです。でも、そこに学校が求める部活動の顧問の教員を配置するために、指導力と連動させた教員異動を行う必要がある」というのをこの委員会は提言されています。この辺は今どう活かされているのかを知りたいです。その点がもう一つ。","respondent":"渋谷指導課長","answer":"子どもたちが野球をやりたいからといって野球部をつくったり、またフェンシングをやりたいからフェンシング部をつくったりということは、指導体制等々で非常に難しいということでありますので、そういう意味においては、なかなかとっても実現できない意向調査等は行っていないし。","voiceIndex":225,"id":"exchange-098"},{"speaker":"渡辺委員","kind":"質問","question":"ここからはチャレンジという思いで、今後を考えたときに、それぞれの学校の中では、教員の方の配置で難しいと。おそらく全区的な展開、あれもこれもはいけるわけはないのですが、モデルあるいは段階的に全区的な支援の形というのは、おそらく競技によっては十分達成される可能性があると思います。こういうところでの含み、応用というのは、考えられるのかどうか、伺いたいと思います。","respondent":"渋谷指導課長","answer":"いずれかの形で、できないからやらないではなくて、子どもたちがきちっと運動ができたり、また文化・スポーツに推進できるような体制について、品川区としても前向きに取り組んでいきたいと考えているところです。","voiceIndex":227,"id":"exchange-099"},{"speaker":"向委員","kind":"質問","question":"私からは、３５５ページ、国際理解教育についてということで、グローバル教育についてお伺いしたいのですが、その前に、３５３ページ、イングリッシュキャンプということで、ブリティッシュヒルズに行きますということで、ほかの委員からも先ほど幾つか質問が出ていました。","respondent":"渋谷指導課長","answer":"ああいうマントを部屋ごとに貸し出してくれたり、またそういった文化そのものを体験するです。ただ、英語の中身については米国、イギリスとか、その部分での違いを大きく感じるようなところはないので、子どもたちの戸惑いはないかなというふうに思っているところです。","voiceIndex":230,"id":"exchange-100"},{"speaker":"向委員","kind":"質問","question":"わかりました。品川区のグローバル教育についてお伺いしますが、来年度も本当にさまざまな新規事業が出てきています。最初にお伺いしたいのは、品川区が考えるグローバル教育が目指すところ、例えば品川区からどんどん本当に海外に、世界に羽ばたく人材をどんどん出していきたいとか、海外留学をする子どもたちの数を増やしたいとか、ちょっと簡単にお伺いしたいと思います。","respondent":"渋谷指導課長","answer":"近くは、オリンピックがあり、国際的な窓口となる品川区としては、そういったところで十分にハンディキャップを背負わずに、堂々と自信を持って活躍できる子どもたちをぜひ品川区では育てていきたいと考えているところです。","voiceIndex":232,"id":"exchange-101"},{"speaker":"向委員","kind":"質問・要望","question":"委員長にも許可をとったので、例えば、大学、これは大阪大学のパンフレットなのですけれども、「世界適塾」ということで、まさに世界に通用する人材を育成しようと、日本は今後、子どもも減っていきますし、そんな中で、大学のランクも世界的に見ると決して高いとは言えない、１０位以内に入っている大学は国公立で幾つあるでしょうかというような状況にもあり、危機感を本当に抱いていたり。","respondent":"渋谷指導課長","answer":"イングリッシュキャンプの部分につきましては、基本的には宿泊費と食費の部分については、これは日常生活してもかかるわけですので、その部分について自己負担をしていただくと。研修費や交通費については公費で負担でということで考えているところです。","voiceIndex":234,"id":"exchange-102"},{"speaker":"向委員","kind":"質問・要望","question":"わかりました。海外留学すれば一番いいことなのですが、海外留学に行ければ語学を学べるし、海外の文化とかも知れるし、もちろん自分が、大げさかもしれないけれども、１人のちょっとした外交官になったような気分で、日本のことも紹介する機会にすごく恵まれるので、このあたりは本当に区の事業としてもバランスのよさというものを求めていきたいなと思うのですが、お考えをお願いします。","respondent":"渋谷指導課長","answer":"そういった子どもたちが生き生きと表現できる機会というものを今後もぜひ多く取り入れていきたいと考えております。","voiceIndex":236,"id":"exchange-103"},{"speaker":"向委員","kind":"質問","question":"ご答弁、ご丁寧にありがとうあります。さまざまな危機管理的なところで言うと、本当に海外に出ることはリスクも多くて、ただあえてリスクを犯して、やっぱり海外に飛び出していって、知力と体力の限界に挑戦するというのですか、そういったところで得られるものというのは本当にはかり知れないものがあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":238,"id":"exchange-104"},{"speaker":"山元委員","kind":"提案","question":"品川区の図書館といたしましては、これを受けて、目標とか、そういう不読率の目標をもし掲げているのであれば教えていただきたいと思うし、また今回図書１万８,０００冊ですか、いろいろ買っておられますけれども、特に小中学生の不読率が高いわけですが、子どもたちにとって興味深い本を選んだかなと思いますが、その辺の基準はどのように選んだのか教えてください。","respondent":"中元品川図書館長","answer":"１点目の不読率の目標ですが、東京都のほうはこのような手法でやっておりますが、品川区のほうでは特にそういうものは、目標として、不読率としてはとってございません。","voiceIndex":240,"id":"exchange-105"},{"speaker":"山元委員","kind":"質問・要望","question":"ある中学校１年生は、７,０００冊も読んだ子がいるなんていう話もありまして、そこの館長は子どもたちが自分の成長を振り返ることがこの通帳を通してできる、またこれは本当に人生の宝物になるのではないかと、そんなお話をされておりました。この辺、今すぐとは言いませんが、先々何かこういうＤＶＤとかを返す方法を、何か簡単な方法を考えていただきたいと思いますが、いかがでしょうか。","respondent":"中元品川図書館長","answer":"その辺のところで、ちょっと大変口が当初から二つに分かれて、入り口が二つとか施設上つくれればできるのですけれども、ちょっと課題が大きいところでございまして、ちょっとしばらく、当面ちょっと実施は難しいのかなと考えています。","voiceIndex":242,"id":"exchange-106"},{"speaker":"山元委員","kind":"質問","question":"いろいろ考えていただいた上で延長時間ということでしたので、了解いたしました。その辺、やはりお金のかかることではありますけれども、将来的にこれだけ携帯電話がたくさん皆さんお持ちになって、ほとんどの方がお持ちになっているわけですので、その辺、図書館に携帯電話ボックスというのですかね、その辺のお考えはいかがでしょうか。","respondent":"中元品川図書館長","answer":"地区館が本当に小さいところもございまして、設置するのは、今、実は本自体も置き場所に困っている、これ以上、少しでも本を多くしたいのですけれども、なかなか本も増やせない状況でございまして、本当に限られた面積でやらせていただいておりまして。","voiceIndex":244,"id":"exchange-107"},{"speaker":"山元委員","kind":"質問・要望","question":"緊急の電話ですので、４階まで走ってというのはあれなんですが、いずれにしましても本当にこれからやはりそういうのが必要になる時代が来るかと思いますので、どうか前向きに考えていただきたいと思います。どうかよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":246,"id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"３５７ページ、特別支援教育費、あと教科書採択事務、３６５ページ、便所改修、お願いいたします。この点を質問しますけれども、どのように変わっていくのか、また内容について教えていただきたいのが１点。特別支援学級、固定級がどうなっていくのか、あと情緒障害等の通級学級がどう変わっていくのか、この３点を教えてください。","respondent":"村尾学校支援担当課長","answer":"どのように変わっていくかということですが、３点目の通級学校はどう変わるのかと多分一緒のセットでご説明をさせていただければと思いますが、現在通級学級に拠点校がありまして、さまざまな近隣の小学校から子どもたちが週１回、２回通っている現状があります。","voiceIndex":249,"id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"通級学級は、子どもたちが移動するのではなくて、支援が来るということなのですけれども、同じ障害を持っていらっしゃる子の状態を複数で見ていて支援をするのと、また個別に来て、その子だけで、その子だけを見ていくということも大事かもしれませんが、その辺の違いのところで、通級学級をなくさないでほしいという親御さんたちの声がかなり聞こえてくるのですけれども、その辺についてのお考えというか。","respondent":"村尾学校支援担当課長","answer":"本年度も、また昨年中も特別支援教育の研修会をやっておりますし、まさに各学校に特別支援コーディネーターという教員を１名各学校で指名し、その教員を中心に各学校でこのインクルーシブ教育の推進。","voiceIndex":251,"id":"exchange-110"},{"speaker":"飯沼委員","kind":"質問・要望","question":"もう一つは、普通学級に在籍をしているお母さんから、介助員と学習支援員のところを必要な時間をつけてほしいという要望も届いているのですが、一人ひとりお子さんの様子が違うと思いますけれども、週に１回で半日しかついていないという訴え、いろいろ事情はあると思うのですけれども、特別な行事とかだけではなくて、やっぱり必要なときにおいては日常的に安定した環境を持つ意味で介助員とか。","respondent":"村尾学校支援担当課長","answer":"３点のご質問だと思います。１点目なのですけれども、通常学級とそれから特別支援学級との交流につきましては、これはやっぱり設置校についてはさまざまな形で現在交流は進めているということはこちらのほうで認識しております。","voiceIndex":253,"id":"exchange-111"},{"speaker":"飯沼委員","kind":"質問・要望","question":"私は保育園で仕事をしていたときがあるので、本当に日常的に分け隔てなくというか、どの子も受け入れられる、お互いにそういった環境というのはすごく大事なので、ぜひここは深めて、把握はできているのでしょうか、各学校の状況、ぜひ把握をしていただきたいなと思うのが、お母さんからは、図工や体育、音楽などの授業と、あと行事と給食など、交流の学習、１年から続いていて。","respondent":"村尾学校支援担当課長、品川庶務課長","answer":"基準等につきましては、先ほども言いましたとおり、介助員、それから学習支援員につきましては、やはり介助員の基準は、教室からの飛び出しが頻繁なり、また安全確保が困難等。傍聴人の人数につきましては、以前１０人という枠だったのですけれども、これを３０人に拡大しているという経緯もありますので、現在のところ３０人以上に拡大する考えはございません。","voiceIndex":255,"id":"exchange-112"},{"speaker":"飯沼委員","kind":"質問","question":"時間がなくなって、トイレなのですけれども、改築の順番は決まっていないようですけれども、トイレがとても汚くて、子どもに選ばれないというところで、ぜひ改修を前倒しでやってほしいのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"各校の状況によって全体的に、総合的な考えで改修は行ってまいります。","voiceIndex":258,"id":"exchange-113"},{"speaker":"松澤委員","kind":"質問","question":"２点お聞きします。１点目が、１項教育総務費、４目の社会教育費、３５７ページの文化財保護事業について、２点目が２項の学校教育費に関連して、３６３ページ、防災教育についてお伺いしたいと思います。１点目の文化財保護ですけれども、平成２３年、２４年度と区内の絵馬調査をしているのですね。あれが文化財になるのかならないのか、その辺の基準、どのように基準をしてこれは選んでいるのでしょうか。","respondent":"品川庶務課長","answer":"絵馬の文化財指定の基準ですけれども、基準につきましては、制定年代、それから文化財的な価値、希少性等も踏まえまして文化財保護審議会で決定をしているというような状況です。","voiceIndex":261,"id":"exchange-114"},{"speaker":"松澤委員","kind":"質問","question":"絵馬というと社殿に飾ってあるので、毎年毎年傷んでくるような気がするのですね。当然文化財ですから、補助金が出ているのかどうかわかりません。もし、これがみんなはげ落ちてしまったら文化財としての価値がなくなるというのでしょうか。これの修復なんかをしたときに費用が出るのかどうか、あるいは修復したらだめになってしまうのですかね、その辺、いかがでしょうか。","respondent":"品川庶務課長","answer":"絵馬の修復に関しましては、現在のところ区の指定文化財、これに入っておりますと、基本的には補修等をした場合には、経費の５割から６割、これを補助するというようになってあります。","voiceIndex":263,"id":"exchange-115"},{"speaker":"松澤委員","kind":"質問","question":"ただ、みんな掘った跡は必ず埋め戻して、そこへ建物を建ててしまいますから、文化財がないということになるとそのままにしてしまうのでしょうけれども、あれは何も申告しないとそのまま壊してしまう、当然ながら申告すると工期がおくれてしまいますので壊したりしてしまうのですが、この辺は貝塚があるよ、住居跡があるよというので。","respondent":"品川庶務課長","answer":"こちらは文化財保護法によりまして、必ずこういう工事をやるときには届出をするということになっておりますので、その法に準じて行っていただくということになってあります。","voiceIndex":265,"id":"exchange-116"},{"speaker":"松澤委員","kind":"質問・要望","question":"はい、わかりました。あの辺は貝塚が出るかもしれない。崖から区道１本、家を潰してやりますので、この辺の工事を慎重にしていただきたい。これは申し入れておいていただきたいというふうに思います。それと文化財の中で、木造の神社仏閣等と、こういうものが含まれているという話は聞かないのですけれども、品川区ではそういう建物についての文化財保護という規定はないのでしょうか。","respondent":"品川庶務課長","answer":"品川区内で今建物の文化財指定、指定文化財は一つあります。１か所、居木神社末社、これの旧松原家屋敷神というところが指定をされてあります。","voiceIndex":267,"id":"exchange-117"},{"speaker":"松澤委員","kind":"質問","question":"そうしますと、木造の建物が文化財として登録される条件みたいなものはありますでしょうか。その辺、ちょっと詳しくお願いします。","respondent":"品川庶務課長","answer":"文化財登録に関しましては、ちょっと先ほどと答弁が重なるところもありますが、やはり文化財価値、それから希少性等、この辺の部分を文化財保護審議会で検討して決定するというような流れになってあります。","voiceIndex":269,"id":"exchange-118"},{"speaker":"松澤委員","kind":"質問","question":"わかりました。それで、結構です。もう１点のほう、防災教育について、午前中にも質疑があったのですけれども、「防災教育には防災学習と防災訓練がある」という答弁がありましたけれども、防災学習はどんな学習をしているのかというと、時間ですね、年間か月か、１週間か知りませんけれども、どれぐらいこれに時間をとっているのかをお聞きいたします。","respondent":"村尾学校支援担当課長","answer":"市民科においては、それぞれ３時間程度、１・２年生から８・９年生まで、それぞれ地震また火災等の対応、また適切な対処方法、また高学年、中学校におきましては、組織のつくり方、また活動の方法等について学習をしています。","voiceIndex":271,"id":"exchange-119"},{"speaker":"松澤委員","kind":"質問","question":"災害時には冷静に判断、行動できる防災の人材を育てるということで、各校１０名から２０名の部員を育てるのだそうです。これはやはり、私は防災教育の根本は訓練と被災地などに行って現場を見るということだと思うので、これほど荒川区が力を入れようというのですけれども、品川区での取組みはいかがなものでしょうか。","respondent":"村尾学校支援担当課長","answer":"ただ、現段階で、区のほうでこの被災地のほうに子どもたちをということは考えてはいないのですが、ただ現在、区の中学校においては、ポンプ隊等、地域のいわゆるそういう総合防災訓練、またそういう災害において、子どもたちのできる部分、どのようなところができるか。","voiceIndex":273,"id":"exchange-120"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり、防災対策、区長も今年度の施政方針の中で防災対策を第一番にと言っておりますけれども、私はよく高校生のことを質問するのですね。高校生は体力的にも大人ですよ。それぞれ学校教育の仕方、それぞれの区で違いますけれども、私はこのニュースを見て、一度視察に行って改めて本会議で質問しなくてはと思っているのですけれども、改めて子どもたちの防災教育について一言いただきたいと思います。","respondent":"村尾学校支援担当課長","answer":"なので、中学生におきましては、それぞれ学校はもし災害が起きた場合、拠点になりますので、そこにいたときに、例えば物資を運ぶとか、その辺で中学生としてできる範囲の活動について考えていこうと、それは思っております。","voiceIndex":275,"id":"exchange-121"},{"speaker":"高橋委員","kind":"意見","question":"ちょっと項目がわからないのですが、小中学校における自転車に関する交通安全指導、それからこれもちょっと項目がわからないのですが、おそらく特色ある教育活動経費になるのかと思います。それから、３５７ページ、グローバル人材育成塾についてお尋ねします。そして、今年度、昨年度で結構ですので、その小中学生の自転車による事故が、どれぐらいあるか、もしおわかりになればお願いします。","respondent":"村尾学校支援担当課長","answer":"１点目の自転車安全教室の実施についてのお尋ねです。現在、区のほうでは、自転車安全教室ということで、学校によっていろいろな形で教室を開いているところがあります。","voiceIndex":278,"id":"exchange-122"},{"speaker":"高橋委員","kind":"質問","question":"今お話があったように、１５件が自転車との関係と、もちろんお子さんご自身がけがをした場合のことについては、いろいろな保障があるのですが、逆に報道でもあったような、対人や対物の、賠償責任が生じた例は先ほどの事故の中であるのでしょうか。そして、そういった自転車保険というのでしょうか、それに加入しているかどうかを学校としては把握をどの程度されているか。もししていなければそれで結構です。","respondent":"村尾学校支援担当課長","answer":"２点のご質問だと思います。今回の自転車等の事故で、賠償問題が起きたというのはこちらのほうではまだ聞いておりません。それから２点目、子どもたちが自転車事故等の賠償保険の加入をしているかどうかについては、その辺の調査をしたことはございません。","voiceIndex":280,"id":"exchange-123"},{"speaker":"高橋委員","kind":"質問","question":"報道でも多額の賠償をというような事件が他の自治体でもありました。これはほかの自治体の小学校、中学校で入っているところがあります。これはＰＴＡのこともあるし、教育委員会としてなかなかお話ししにくいところもあると思うのですが、ほかの自治体で学校の判断で入っているところがあるのですが、こういった保険の存在についてどのようにお考えでしょうか。","respondent":"品川庶務課長","answer":"委員のおっしゃるとおり保険の内容としましては非常にいいものかというふうには思いますが、若干ちょっと営利の部分もありますので、教育委員会としてどのようにご紹介できるかというのは、少し難しいところではあるかというふうに思います。","voiceIndex":282,"id":"exchange-124"},{"speaker":"高橋委員","kind":"質問","question":"学校の児童・生徒が万が一そういったことになったときに、こういうものがあるという存在を知っていただく必要があるのではないかなというふうに思います。グローバル人材育成塾のほうなのですが、先ほど成果についてお話しいただきましたけれども、その一方で、課題が幾つかあったと思います。その課題についてご説明をお願いします。","respondent":"渋谷指導課長","answer":"その主な退塾の理由としては、レベルが低過ぎる、逆にレベルが高過ぎる、それから３年生、９年生の場合は受験のため、また入学当初、７年生が申し込んだときに部活動の活動の見通しがなっていなかったために。","voiceIndex":284,"id":"exchange-125"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうなのですね。今課題についていろいろ分析されているので、平成２７年度の授業がぜひレベル分け等、あるいは補助でいろいろな形でできるように、期待を持って塾を受講している中学生の気持ちに応えるような授業にしていただきたいと思います。これは教育委員会のほうに申請してオーケーが出たといいますが、これに対する評価はどのようなことでしょうか。","respondent":"渋谷指導課長","answer":"ただ、今実践している学校については、そういった集団行動等、また親元を離れての生活を体験させる時期として４年生も一つの選択肢としてあるということで、ここの部分については、学校の取り組みについて注視してまいって。","voiceIndex":286,"id":"exchange-126"},{"speaker":"高橋委員","kind":"意見","question":"５年生の初めての宿泊、日光につながる実績のある宿泊研修ですので、教育委員会としてもバックアップのほうをお願いいたします。平日なのでボランティアの方にお手伝いいただいたりというようなところもありますので、人的あるいは財政的、それで、これは特色ある教育活動経費ではないので、独自の中でやっていらっしゃるので、そこをフォローしていただけるとよろしいかなと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":288,"id":"exchange-127"},{"speaker":"あべ委員","kind":"質問・要望","question":"私からは、３４９ページ、巡回相談員等経費ならびに３５１ページのいじめ防止対策費について。それから３４９ページの教育指導費全般にかかってくるかと思います、人権教育といいますか、先ほども出ていましたＬＧＢＴへの配慮について、それから３５７ページ、教科書採択事務について、これは簡単な確認です。それから、３５９ページ、図書館について、特に資料費の部分についてお伺いしたいと思います。","respondent":"村尾学校支援担当課長","answer":"スクールソーシャルワーカーにつきましては、まさにいじめ対策チームではありますけれども、今後不登校の子どもたち、また川崎の事件ではありませんが、虐待もそうなのですが、問題行動、非行等についても十分対応していこうというふうに考えております。","voiceIndex":290,"id":"exchange-128"},{"speaker":"あべ委員","kind":"提案","question":"同じいじめ防止対策の中で、学級集団アセスメントとそれから学級風土調査と、それぞれ学校現場の信頼を得ているということで、以前提案したものとしては大変うれしいのですけれども、この学級診断アセスメント、これは本年度より予算が増えていますけれども、何校で実施なのかということと、それ以上に希望があった場合にはどうするのか、待ってもらうのか。","respondent":"村尾学校支援担当課長","answer":"そこには、平成２５年度から進めているさまざまな各学校の取組み等を紹介する中で、まさに自校でもぜひ子どもたちの様子、学級の様子を調べてみたいということで、現在は増えている状況です。希望がございましたら、これにつきましては推進している現状です。","voiceIndex":292,"id":"exchange-129"},{"speaker":"あべ委員","kind":"質問・要望","question":"先生方の力量を上げていくにもプラスになるものがあると思いますので、ぜひよろしくお願いいたします。いじめ防止対策なのですけれども、いろいろな対策があると思います。それぞれ長所があると思いますが、なかなか固い話になりがちなのですよね。次に移ります。こういったことはすぐできることですので、ぜひやっていただきたいと思うのですが、一言お願いします。","respondent":"村尾学校支援担当課長","answer":"このような流れを踏まえまして十分こちらのほうでも検討させていただきたいと考えています。","voiceIndex":294,"id":"exchange-130"},{"speaker":"あべ委員","kind":"確認","question":"ぜひよろしくお願いいたします。簡単に教科書採択について確認したいと思います。そういった意味で、教育的観点から教科書というものを選んでいくという姿勢が、私は一番基本にあると思っているのですが、その点、教育委員会としてはどのようにお考えかということを確認したいと思います。あわせて、図書館についても伺います。","respondent":"渋谷指導課長、中元品川図書館長","answer":"先ほどもご答弁申し上げたとおり、この教科書採択に伴う調査基準そのものが教育的にどうなのかということを現場の先生を中心に研究していただいて、そのことを資料にまとめたものを教育委員のほうにご提供して。資料充実費のところですが、地区館の分につきましては、次のページ、３６１ページの中ほどに地区図書館運営費という中に、２行目に指定管理者運営委託という項目があります。","voiceIndex":296,"id":"exchange-131"},{"speaker":"あべ委員","kind":"確認","question":"これの簡易鑑定というのでしょうかね、見た方から、これはぜひ保管の環境を何とか考えて、その中で地域の資料としてということはできないだろうかというお話をちょっと伺って、書庫というのは、チョウの保管にもなかなか適しているところではないかと思うのですが、例えば大崎図書館で、新たな図書館で書庫をつくられるのであれば、押し入れ半分の分ぐらいらしいのですけれども。","respondent":"中元品川図書館長","answer":"基本的な考え方といたしまして、大崎図書館移転先のほうに共同書庫のほうも今段階では持っていく方向で検討している状況です。","voiceIndex":299,"id":"exchange-132"},{"speaker":"あべ委員","kind":"質問","question":"すみません、新しいほうの書庫でというふうな意味でお伺いしました。","respondent":"中元品川図書館長","answer":"新しいほうの書庫、まだちょっと現在準備調整中ですので、ちょっと現段階でのお返事はできません。","voiceIndex":301,"id":"exchange-133"},{"speaker":"浅野委員","kind":"質問","question":"続いて聞きますけれども、学校ＩＣＴ活用経費ですが、プロジェクター、小学校１９校、中学校５校、タブレット端末、小学校８校、中学校２校、特別支援教育用タブレット端末を配備して、それぞれ活用されたと先ほども伺ったところです。それぞれの設備について期待していた効果というものが出すことができたのかどうかということについて伺います。","respondent":"渋谷指導課長、野呂瀬学務課長","answer":"すみません、今教科別の人数は手元にないのですぐにお答えできないのですけれども、大体各校２名ぐらいですと３０名前後が英語の教員というふうに推測できるところです。ＩＣＴをどんな形でやっているかと、アンケートですけれども、教員アンケートの結果ですけれども、最初に入れた当時はちょっとあれだったのですけれども、最近活用頻度が多くなってきて、小学校にアンケートをとったところ。","voiceIndex":304,"id":"exchange-134"},{"speaker":"浅野委員","kind":"質問","question":"それとＩＣＴのほうですけれども、利用した教科はわかったのですけれども、プロジェクターはそこそこ使っていますが、タブレット端末はどうだったのでしょうか。それとあと、これは評価をされているかと思いますけれども、今後全校に展開をするという、このような計画はいかがでしょうか。","respondent":"野呂瀬学務課長、渋谷指導課長","answer":"それと今後の配置ですけれども、一応計画上は小規模支援ということで配備しましたので、今のところはこの１０校でいきたいです。しかしながら、固有教員については英語の資格等々を積極的に推進するように努めてまいりたいというふうに思っているところです。","voiceIndex":307,"id":"exchange-135"},{"speaker":"浅野委員","kind":"質問・要望","question":"３７１ページの心臓検診なのですけれども、数字をちょっと勘定したところ、昨年に比べて予算が１.４倍ぐらいになっているので何か変わっているのか、これは小中を含めてですけれども、教えてください。これは結構厳しい要望かなと思いますけれども、地元の方の声をしっかりと受けとめていただければと思います。それぞれご答弁をお願いします。","respondent":"野呂瀬学務課長、品川庶務課長","answer":"学校保健のことですけれども、いわゆる金額が増えたというのは予定人数の増、それと検診、これは単価契約でやっていますので、その単価アップ等です。ただ、学校の管理上どうかというところもありますので、その辺も学校といろいろ話し合って、門の設置については考えていきたいと考えています。","voiceIndex":310,"id":"exchange-136"},{"speaker":"浅野委員","kind":"質問・要望","question":"単価アップにしてはかなりのアップかなというふうに思うのですけれども、中身は本当にそれでいいのかというのを再度お伺いしたいと思います。門についてですけれども、これは地元説明会、どのぐらい出られるかちょっとわかりませんけれども、地元の方のお話をぜひとも真摯に聞いていただければと思います。要望です。","respondent":"野呂瀬学務課長","answer":"単価アップとあとは人数の増です。","voiceIndex":313,"id":"exchange-137"},{"speaker":"須藤委員","kind":"質問","question":"いろいろお話を伺っていると、今の教育というのはできないと言っては悪いけれども、成績の悪い子を引き上げてきて、ずっと上げてくるような雰囲気があるのだけれども、やはり頑張っている子をもっと伸ばしてやる、いわゆるリーダーがまた下を引っ張っていくぞという考え方も一つあろうかと思うのだけれども、そういう考え方についてはいかがでしょうか、教えてください。","respondent":"渋谷指導課長","answer":"先ほど来、るるご質問いただいている、例えば中学生のグローバル人材育成塾については、まさに今後英語の力を身につけて国際社会に出ていきたい、そういう意欲のある子どもたちを拾い上げる、伸ばしていこうというのが取組みの一つですので、できない子はもちろんですが。","voiceIndex":316,"id":"exchange-138"},{"speaker":"須藤委員","kind":"意見","question":"今どっちかというと、どうしても何かあっても人のせいにしたりとかというのが、大人社会でも非常にあって、責任をとらないよというような風潮が非常に見られているので、そうではなくて、しっかり自覚を持って育っていくようにお願いしたいと思います。それから３５３ページの品川区教育フォーラム開催経費とあります。","respondent":"渋谷指導課長","answer":"場所については、午前中は品川区内全ての小中学校、小中一貫校を会場として授業公開と、各学校の取組みの発表を行っていただく予定です。","voiceIndex":318,"id":"exchange-139"},{"speaker":"須藤委員","kind":"質問","question":"品川区も区長が非常に教育にはしっかり関心を持っていらっしゃると思うのだけれども、そういったいわゆる教育再生首長会議というのに区長が入っていたら、ありがとうと言いたいのだけれども、もし入っていらっしゃらないようだったら、そういうものの関心があるかどうか、お聞きになって、教育委員会と一緒に仕事をしていくということが必要ではないかと思うのだけれども、いかがでしょうか。","respondent":"渋谷指導課長","answer":"今回の教育委員会制度は、今までの教育委員会だけの問題でなく、区長部局も含めて子どもの育ちについてどういうふうに考えていくのかということが重要なテーマになろうかと考えていますので、また区長、この後日程調整も必要ですが、ぜひご登壇いただいて。","voiceIndex":320,"id":"exchange-140"},{"speaker":"須藤委員","kind":"質問・要望","question":"「志」というのは、もっと深いものだと思う。ですから、さっき言った「向上向下の道」なんていうのも、英語にしようとしたってなかなか意味がついてこないと思う。ただ、ウェルカムというだけでどうのということでは決してないと思うので、それを子どもたちに教育していくことをよく承知しておいていただきたいと思うのですが、いかがでしょうか。","respondent":"渋谷指導課長","answer":"武道も他地区ではやっておりませんが、小学校５年生から日本の武道をしっかり学ばせて、伝統文化を大切にする心を育んでおります。そういったものを大切にしながら、なおかつ国際社会でも活躍できる子どもたちをしっかり育ててまいりたいというふうに考えているところです。","voiceIndex":322,"id":"exchange-141"},{"speaker":"須藤委員","kind":"質問・要望","question":"そういった日本の国というものを一体感を持って進めていくということが、このオリンピック・パラリンピック推進事業の中に入ってきてほしいと思っている。ですから、そういったものを上手に活用していくことが、教育の世界だけではなくて、広くそういう事業が世間で営まれてきているのですから、そういった方向性をとっていったらいいのではないかと思うのですが、そのあたりもお聞かせください。","respondent":"村尾学校支援担当課長","answer":"まさに東京でオリンピック・パラリンピックが開かれるというこの大きな動きの中で、品川区においてもまさに体力向上という一つの施策を大きく打ちまして、子どもたちにとって運動することの楽しさ、また運動することが今後。","voiceIndex":324,"id":"exchange-142"},{"speaker":"須藤委員","kind":"質問","question":"今家庭の中でいろいろお子さんたちを育てる力が足りないよというようなことがあって、学校教育に頼るところが非常にあると思うのだけれども、基本はやはりお子さんたちが家庭でしっかり育てられて、それから学校でというのでいくのだと思うのだけれども、このあたりはどういうふうな支援をしていくのか教えてください。","respondent":"品川庶務課長","answer":"家庭教育支援ですけれども、今回、家庭教育のチェックシート、それから家庭教育のブックという二つのものを作成しております。チェックシートは、大体２０から３０項目ぐらいの問いを出しております。それで、イエス・ノーというような形で編集をしております。","voiceIndex":326,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"私は３４８ページ、教育指導費の中で全国学力テストについてちょっとお聞きしたいと思います。昨年テストがありました。小学６年生、中学３年生を対象に国公立の小中学校に通う約２３０万人と私立の小中学校も約半分参加したようですが、そのテストの結果を、本人の学力を本人や保護者に対して、「あなたはこのぐらいの位置にあるよ」ということをきちんと報告しているのでしょうか。","respondent":"渋谷指導課長","answer":"ですから、子どもが基礎的なＡ問題ができている、できていない、また発展的なＢ問題ができている、できていない、領域ごとにどんなところに弱点があるのか等々について、子どもたち、また保護者の方は情報を知ることができる、そういうような内容です。","voiceIndex":329,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"やはり、そういうことをきちんと義務教育の間に教えてあげるのが教育委員会の仕事ではないのですか。そうやって、いつまでも大事に、あなたはこの程度はできて、この程度はできませんよ、それを教えて、子どもたち、親はどういうふうに自分の実力を、納得すればいいのですか、そうではないですか。ちょっとご見解をお聞かせください。","respondent":"渋谷指導課長","answer":"子どもたちの相対的な順位をお知らせするということが教育委員会の大きな使命であるかというと、それは全く違うというふうに考えております。子どもの学びは勉強だけではありません。人間性の育成、その他非常に多くのことを学校教育の中で学びます。","voiceIndex":331,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"今そうおっしゃいますけれども、実際、社会に出てどうですか。１回新入社員として入れないと、今度中途採用ということで、なかなか入れません。今、公務員になるといったって、就職が大変ではないですか。でも、なぜ教育委員会の皆さんは、いや、そこまでやる必要はない、私たちはそんなことはしませんよと言い切れるのですか。どうですか、もし自分の子どもがそうだとしたら、同じことを思われますか。","respondent":"渋谷指導課長","answer":"そういう意味において、単純に順位だけとか、成績だけで進路選択を図っていくというふうな考え方については、我々としては考える予定ではありません。","voiceIndex":333,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"お聞きします。根本的に学校というのは何のためにあるのですか。これはさっき生きる力、社会で働き生き抜いていく力もありますけれども、もともとは勉強するため、学問を学ぶためにできたのではないのですか。では、教育委員会、違うのですよね。社会は変わっていません。実際、実社会はどうなのだということを真剣に考えてほしいのですね。もし、ご見解がありましたら、お願いします。","respondent":"渋谷指導課長","answer":"学校教育の意義ですが、しっかりと勉強、基礎的な学力をつけるのはもちろんですけれども、社会に出るための準備をするというのが学校の大きな役目です。一つの問題集を解いて、偏差値７０をとって、それでよしとするのは学校ではありません。","voiceIndex":335,"id":"exchange-147"},{"speaker":"南委員","kind":"質問","question":"３６１ページの御殿山小学校西側敷地図書館建設工事設計費、２,５００万円計上されていますが、この問題について質問します。スケジュールを教えてください。","respondent":"中元品川図書館長","answer":"西側敷地につきましては、現在調整中ですので、まだ最終的なスケジュールにつきましては確定していないと認識しております。","voiceIndex":342,"id":"exchange-148"},{"speaker":"南委員","kind":"質問・要望","question":"私は御殿山西側敷地に今までの計画では大崎図書館が移転していくと、こういうことになっていると思います。その辺をちょっと確認したいと考えています。それで、当初の計画では大崎図書館にあるビジネス関連の図書については、北品川五丁目の産業支援交流施設に入ると。そして、この大崎図書館が現在実施している住民へのサービスというのは、どのような内容なのか、それについて伺いたいと思います。","respondent":"中元品川図書館長","answer":"そのような中で大崎の新しい場所、そちらの産業交流支援施設の近くに、そういう場所ができるということがありましたので、そちらのほうに大崎図書館が移転するほうが、連携が図れるのではないかという方向で現在検討しています。","voiceIndex":344,"id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"この図書館が移転された後には、開発ビル内の後かどうかちょっとわからないですけれども、時期的にちょっと教えていただきたいですけれども、西口の開発ビル内の１５０m2のスペースに取次施設を、そして芳水小学校が改築したときに、その中に取り次ぎサービスを入れるというふうにしているのですけれども、そこでは一般的な図書館のサービスが行えるのかどうか、そこについて伺いたいと思います。","respondent":"中元品川図書館長","answer":"現在予算要求の準備を進めている芳水小学校の改築計画の中で、大崎図書館の取り次ぎサービスなどの設置を検討していくです。","voiceIndex":346,"id":"exchange-150"},{"speaker":"南委員","kind":"意見","question":"そこの二つの取り次ぎサービス、閲覧もできるというふうになるのですけれども、そこでは今、大崎図書館が行っている一般サービス、それができるのかどうかということのお答えがなかったので、簡潔にお願いします。","respondent":"中元品川図書館長","answer":"大崎駅西口のスペースですが、そちらのほうで取り次ぎサービスを行うに当たりましては、現在のところまだ調整中ですけれども、図書館の指定管理者のスタッフを配置することで検討していますので、当然レファレンスに関する部分とか。","voiceIndex":348,"id":"exchange-151"},{"speaker":"南委員","kind":"質問","question":"大崎図書館利用者に対して移転計画があることを知らせているのでしょうか。私どものほうで利用者の方にアンケートをとったときに、非常に反対が多かったのですね。区は区民がとりわけ利用者の方がこんな意見を持っているということをご存じなのかどうか、そして移転計画を知らせないまま進めていくつもりなのかどうか、その辺について伺います。","respondent":"中元品川図書館長","answer":"遜色なく行えるかというところでは、大崎駅西口はある一定程度、現在の予定ですと１５０m2の場所をお貸しいただけると伺っておりますので、現在大崎図書館で行っております児童サービス等も行えると考えております。","voiceIndex":350,"id":"exchange-152"},{"speaker":"南委員","kind":"質問","question":"館内では掲示して知らせているということですか、ちょっとその辺。今言ったように、区民に知らせないまま、しかも補助２９号線の道路計画を強引に進めるために、まだまだ使える、３０年しかたっていないところの施設である大崎図書館を移転させるなどは、とんでもないことだというふうに思うし、この計画はやめるべきだというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":352,"id":"exchange-153"},{"speaker":"いながわ委員","kind":"質問","question":"私から３６３ページの非構造部材に関してと、３６５ページの通学路の防犯カメラについてお伺いします。午前中にも非構造部材に関してはいろいろ質問がありました。先ほど６７か所ですか、見つかったというのですが、これはおそらく今年度の調査・設計の中で見つかったものだと思うのですが、今まではそこまで深くは調べていなかったということなのかどうなのかというのをお聞かせください。","respondent":"品川庶務課長","answer":"今年度、八潮でその工事は完了する予定です。それで、今回平成２７年度に予算要求で上げているものは、平成２５年７月１２日に交付されているのですけれども、建築基準法施行令というものがあります。この中で、特定天井について耐震化しなさいということで法令が出ています。","voiceIndex":354,"id":"exchange-154"},{"speaker":"いながわ委員","kind":"質問・要望","question":"この６７か所というのは、さっき特定天井で天井のみ、ちょっとその辺、詳しく教えていただきたいのですが、例えばバスケットゴールもそれに当たるという話も聞いておりますし、さまざまな部分があると思いますので、その辺をお聞かせいただくのと、あと非構造部材というのはいろいろなものがあると思います。","respondent":"品川庶務課長","answer":"学校の家具類ですね、家具類に関しましては、家具転倒防止ということで、今年度の予算の中で全て行っていくような形で進めております。","voiceIndex":356,"id":"exchange-155"},{"speaker":"いながわ委員","kind":"質問・要望","question":"入札ですから、もしかしたら区外から入ってくる業者もあると思うのですが、私の思いとしては、ぜひそういう母校愛ではないですけれども、何十年ぶりに母校に帰って、そういったのをいろいろと工事をするというのは一つの愛着にもつながるのかなという思いがあるので、その辺をしっかりと品川区内の業者にという、それは入札なのでどうなるかわからないですが。","respondent":"品川庶務課長","answer":"すみません、ちょっと朝の説明で、私の説明不足だったかもしれませんが、来年度の非構造部材、こちらは夏休みを中心には行っていくのですけれども、夏休み以外、要するに７月から１０月以外でも地域の関係とか、学校の行事の関係、それから地域開放とか。","voiceIndex":358,"id":"exchange-156"},{"speaker":"いながわ委員","kind":"質問","question":"計画的にしっかりとお願いします。今回の設置工事１４校とありますが、校数というか、設置台数としてまずお伺いしたいということと、その下に小学校通学路防犯カメラ維持管理費が１６校とあるのですが、昨年の補正でついたカメラの維持管理費なのかなと、でもこれを足しても３０校で、小学校的には足りないのではないかと思うのですが、その辺をお聞かせください。","respondent":"品川庶務課長","answer":"来年度は１４校今度設置を行っていく予定です。基本的には各校５台までというような形で行っております。ただ、今年度、５台全部設置した学校というのもあるのですけれども、例えば３台とか４台とか、そういうふうに設置した学校もあります。","voiceIndex":360,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問","question":"３５１ページのいじめ防止対策費、それから３７３ページの幼稚園運営費に関連してお伺いします。いわゆる学校の要請待ちだったということですけれども、先ほど品川区ではそうならないようにするというふうに答弁で伺ったのですけれども、具体的にはどのように対応していくのか教えてください。","respondent":"村尾学校支援担当課長","answer":"これにつきましては、定期的に回るとともに、まさに学校のほうで少し課題を抱えているところには何回か連続して通うと、こちらからなるべく学校のほうにソーシャルワーカーが出向いて学校の状況をつかみながら、教育委員会の中で情報を共有し、よりよい適切な支援等を進めている。","voiceIndex":363,"id":"exchange-158"},{"speaker":"たけうち委員","kind":"意見","question":"そういったことが品川区的にはどうなのかということと、それから先ほど大阪市の例をあべ委員は引かれていましたけれども、名古屋市のほうではこうしたスクールソーシャルワーカーとか、スクールカウンセラー、警察ＯＢ等で「子ども応援委員会」というのをつくって、いわゆる問題があるところに巡回して訪問していくと、こういう対応をしているそうなのですけれども、その辺も含めて。","respondent":"村尾学校支援担当課長","answer":"現在、指導課のほうに配置しておりますＨＥＡＲＴＳには、スクールソーシャルワーカー、それからスクールカウンセラー、そして警察ＯＢ等専門職が入って、さまざまな課題に対応できるように努めているところです。","voiceIndex":365,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"確認","question":"いじめ対策の中で、今学校で通学安全確認業務委託ということで、いわゆるシルバーセンターの方たちが交通安全と、なおかつ、あと不審者対策で巡回していただいたりしていますけれども、そういった方たちとの連携というのですかね、いわゆるこうした方たちというのは、学校以外で、いわゆる登下校中に、特に下校中だと思うのですけれども、私なんかもたまに見るのですけれども、中学生が何人かで。","respondent":"村尾学校支援担当課長","answer":"学校のほうで対応し、それがちょっと課題としては大きい場合については当然スクールソーシャルワーカー、いわゆるＨＥＡＲＴＳのほうに連絡が来ると、間接的にはなりますけれども、つながっているというふうに考えております。","voiceIndex":367,"id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最後になりますけれども、この条例が東京都のほうでほぼ改正されると思うのですけれども、そうなると、品川区のほうでも、所管が違うところで条例が改正されるのですが、今の案だと幼稚園、いわゆる就学前の子どもたちの部分が改正されると思うのですけれども、そうなったときに、品川区として子どもを所管する部署として、今日は幼稚園の部分で結構なのですが。","respondent":"竹田保育課長","answer":"今までも近隣の方に極力ご迷惑をかけないような形で数々工夫してまいりました。今後も引き続き工夫するとともに、子どもは社会の宝とも言われておりますので、ぜひ地域の方にもご理解いただくように粘り強くお声かけをさせていただきたいと考えています。","voiceIndex":371,"id":"exchange-161"},{"speaker":"たけうち委員","kind":"意見","question":"そういう角度ではなくて、いわゆる品川区として条例改正をするかどうかということを所管としてどういうふうに担当部署とやりとりするのかということです。","respondent":"竹田保育課長、三ツ橋環境課長","answer":"今時点では所管としては考えておりません。環境確保条例上の一部を改正するということになりますので、粛々と区としても……。","voiceIndex":373,"id":"exchange-162"},{"speaker":"伊藤委員","kind":"確認","question":"質問に入る前に、川崎で悲惨な事件がありました。品川区ではこういう事件が絶対に起こらないような体制をぜひよろしくお願いいたします。就学事務費のところですけれども、いわゆる消えた子どもの問題が一時期話題になりましたけれども、品川区では就学年齢に達しておりますが、通学していない子どもの把握、人数、それからその後の対応、所在確認はされておりますでしょうか、確認をお願いいたします。","respondent":"野呂瀬学務課長","answer":"今品川区は、居所不明の子どもはおりません。","voiceIndex":377,"id":"exchange-163"},{"speaker":"伊藤委員","kind":"確認","question":"わかりました。その確認がとれれば、ここではいいです。なので、よくモデル町会や自治会をつくって展開していくと思うのだけれども、そういうふうに仕切り直すべきだと思うのですが、いかがでしょうか。","respondent":"品川庶務課長","answer":"子ども地域活動支援についてですが、現在も地域活動課と連携した形で進めている状況です。","voiceIndex":379,"id":"exchange-164"},{"speaker":"伊藤委員","kind":"質問","question":"確かに町会長に説明はあったのかもしれないけれども、それを町会でどう具体化していくか、うちの町会もいろいろな行事をやっています。ですから、今地域活動課と連携するとおっしゃったけれども、町会長に説明すると同時に、より具体的に町会に説明に入っていかないと、この事業の目的は達成されないのではないかなという思いを強くしたので、改めて答弁をお願いいたします。","respondent":"品川庶務課長","answer":"この事業は、当初もちょっと周知が足りないということで、午前中も答弁したのですが、大体２０町会ぐらいに教育委員会としても出向きまして、このスタンプカードの事業の説明を行っております。","voiceIndex":381,"id":"exchange-165"},{"speaker":"伊藤委員","kind":"質問","question":"この目的自体はすごくいいことなのですね。それから、教職員の人材育成に関連すると思うのですけれども、先日私宛てにメールがありまして、匿名で具体的な学校名は記載されていなかったのですけれども、３年数か月前に区立学校内で教師から体罰を受けたと。だから、体罰根絶宣言をしている品川区教育委員会としては、こういうことに対しての再発防止策をどうお考えでしょうか、お聞かせください。","respondent":"渋谷指導課長","answer":"体罰については、これは大人のすることであるので全体に許されないことなのだということで、強い決意を持って今後もしっかりと取り組んでまいりたいと思っているところです。","voiceIndex":383,"id":"exchange-166"},{"speaker":"伊藤委員","kind":"質問","question":"メールにはもっと具体的なことが書いてありますけれども、匿名なのでここであれですけれども、要はこういうメールが来たということは、教育委員会にはもっと頑張ってほしいと思うし、この保護者の方はそういうことを経験なさったのかもしれない。かもしれない、断定できないので。","respondent":"渋谷指導課長","answer":"いずれにしても、体罰がなくなるように、これでいいということはないと考えていますので、繰り返し繰り返し粘り強くしっかりと指導してまいりたいと考えています。","voiceIndex":385,"id":"exchange-167"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。それからあと、区固有教員に関連して質問します。去年の１１月にオークランドに国際平和友好でお伺いしました。スケールが大きいなと思ったのですけれども、国の違いもあるでしょうけれども。つまり何を言いたいかといいますと、品川区の区固有教員に対して、こういう機会を設定すべきではないでしょうか。","respondent":"渋谷指導課長","answer":"引き続き固有教員の質の向上については積極的に図り、また魅力ある品川区の固有教員ということでアピールできるような仕組みを考えてまいりたいと思っているところです。","voiceIndex":387,"id":"exchange-168"},{"speaker":"伊藤委員","kind":"質問","question":"だから、そういうことを今世界的なレベルでやっていらっしゃるわけだから、よく国際理解教育とか、それから世界に羽ばたく人材をつくっていくとおっしゃっているわけではないですか。そういうところの研修プログラムなり、それから一定の成績を上げた方は頑張った成果として、そういうふうなことをしてあげるなり、そういう温かい配慮をすべきであると思うのですが、いかがですか。","respondent":"渋谷指導課長","answer":"ただ、１年だとかということになると、大変予算もかかることですし、またいろいろありますので、そういった研修のあり方については今後前向きに研究させていただきたいというふうに思っているところです。","voiceIndex":389,"id":"exchange-169"},{"speaker":"伊藤委員","kind":"提案","question":"今日で款別の審査は最後ですから、一言お話ししますけれども、私たちは区の理事者よりも品川区民に近いという自負がありますので、委員会でいろいろ出された意見や提案、それから指摘等は十分受けとめていただきまして、建設的な意見だけ受けとめていただきまして、平成２８年度の予算に反映していただきますようお願いします。終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":391,"id":"exchange-170"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":125469,"voices":392}},{"id":"h27-20150317-3","meetingId":"h27-c-budget","date":"2015年3月17日","dateIso":"2015-03-17","committee":"予算特別委員会","time":"午前１０時００分～午後 ４時５２分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を112件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"おはようあります。品川区議会自民党を代表いたしまして、総括質疑を本多健信委員とともに行います。先般、川崎市で中学１年生の男子生徒が殺害されるという、大変に痛ましい事件が起きました。先般の款別審査の中で、文部科学省からの通知に基づいて品川区も調査したというお答えがありましたが、区としての調査、また現況、このような点につきましてご回答いただきたいと思います。","respondent":"田村教育次長","answer":"それで、不登校については、要因が必ずしもいじめなどに限らず、なかなか集団生活になじめない、あるいは学力的に若干、普通のクラスで授業するのになかなか抵抗があるとか、さまざまな理由がありますので、特に不登校というだけの対応ではなく。","voiceIndex":2,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"それでも、この可能性を少しでも減らしていくためにも、スクールソーシャルワーカーや児童相談所との連携というのもこれからも必要になっていくと思いますので、その辺についてもまたお答えをいただきたいのでお願いします。これも、例えば部活動等で連絡手段としても必要だという点もあるとは思うのですが、学校での指導体制、それと同時に教育委員会からの指導体制についてお聞きいたします。","respondent":"田村教育次長","answer":"それと最後が、関連機関と連携して組織的に対応すると。大きな括りで３つの項目が、東京都の教育長から指示がありましたので、それを品川区の形に変えて、東京都の文書と同時に、品川区に対応できる文書を各学校に周知して徹底を図ったです。","voiceIndex":4,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"不登校については、先ほどお話がありましたけれども、連携をとってうまく対応していただきたいと思いますので、よろしくお願いします。では、防災関係の質問に移らせていただきます。自民党から強く要望しておりました品川区災害対策基本条例が昨年４月に施行されました。４年前の東日本大震災の教訓を踏まえ、防災対策として、今までの取組み状況と成果についてお答えをお願いいたします。","respondent":"松代防災まちづくり事業部長","answer":"以上のような取組みの成果としては、区の防災体制整備を具体化することができ、また地域における防災意識が高まったことで、自主的な防災訓練の実施や応急対応訓練の実施といった取組みが活発になったなど、成果が出たと考えているところです。","voiceIndex":6,"id":"exchange-003"},{"speaker":"鈴木（真）委員","kind":"確認","question":"そのときはもう防災の、当日の状況の確認しかできない状況だったのですが、その中で、この４年間進めていただいて、区民の意識というのは確かに上がってきているというのは感じております。２７年度における重点事業については何であるのか、またどのように進めていくのか、この点についてもお答えをお願いしたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"平成２７年度の防災対策の重点事業ですが、まず災害に強いまちづくりとして、木密地域不燃化１０年プロジェクトや細街路拡幅整備などを進めるとともに、避難所機能の強化や津波・浸水等への対策にも引き続き取り組んでまいります。","voiceIndex":8,"id":"exchange-004"},{"speaker":"鈴木（真）委員","kind":"意見","question":"今、お答えにもありました、東京都が策定した木密地域不燃化１０年プロジェクトの取組みについてですが、不燃化のための特別支援を行う不燃化特区３地区を追加することによって、９地区になってまいります。既に実施している６地区においての、支援の内容と成果についてお答えをお願いしたいと思います。それだけ力を注いでいく中で、今後の折衝の方向性という点についてもお答えをお願いしたいと思います。","respondent":"藤田都市環境事業部長","answer":"新たに住宅支援あるいは不燃化コンシェルジュ、未接道宅地の解消等を行うなどを進めまして、さらに力を注いでまいりたいと考えています。","voiceIndex":10,"id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"担当部署の方はよく区民の方と話し合いをなさった上で進展させていただきたいと思いますので、どうぞよろしくお願いします。今後、そのことを考えますと、各地域でもこの訓練の必要性もあるのではないかと考えますがいかがでしょうか。この辺も考えますと、帰宅困難者や滞留者対策について、これからどうやっていくのか、改めてお聞きしたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"ターミナル駅における取組みですが、平成２５年度に目黒駅周辺帰宅困難者対策協議会を設立しまして、目黒区と連携して、具体的な対策の協議や訓練を実施したところです。","voiceIndex":12,"id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ぜひその辺の新たな設立に向けてご努力もお願いしたいと思いますので、よろしくお願いします。この建物につきましては、今までも出ておりますが、固定資産税の問題があるのではないかという話も伺っております。空き家に対しての６分の１の減免もなくなっていく方向性にあるときに、その辺の情報が区のほうに何か入っているのか、その点につきましてもお答えをお願いしたいと思います。","respondent":"藤田都市環境事業部長","answer":"ＪＲの広町社宅についてですが、これまで平成２４年１１月にＪＲと区のほうで、開発構想に向けた検討会を設置し、本年度につきましてもＪＲと協定を締結し、検討を進めているところです。","voiceIndex":14,"id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"２年間ということですが、それだけ出てきたということは、やはりこれから区としても次の方向を早目に考えていかなければいけないと今思いました。もちろん、それもそうですし、これから先どう考えていくのか、私も今聞いた中でどういうふうに考えるべきかというのもあったのですが、検討状況、これから区としてどういうふうに進めていくか、その点をもう一回お答えをいただきたいと思います。","respondent":"藤田都市環境事業部長","answer":"ＪＲのほうの意向としては、住宅等を建てたいというような意向もありますので、こうしたものと兼ね合いながら、どのような形で整備を進めるのがいいのかしっかりと協議し、いずれにしても大井町の明日につながるような、にぎわい、活気のあるまちづくりを進めたいと考えています。","voiceIndex":16,"id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"駅前の大変な大きな土地です。ぜひ、にぎわいのあるまちづくりに努めていただきたいということを要望しておきます。別の件なのですが、荒川区が先日、都市公園法に規定する公園に社会福祉施設を建設できるよう特区申請を行いましたということが出ておりました。都市公園法の解除についての課題と、区としてこの解除に対する考え方について教えてください。","respondent":"松代防災まちづくり事業部長","answer":"区としましては今後、国や他自治体の状況などについてさらなる情報収集を行いまして、活用できる制度は積極的に取り入れていきたいと考えておるところです。","voiceIndex":18,"id":"exchange-009"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"考え方はわかりました。前から聞いていたことがあるのですが、東品川文化センター、シルバーセンターで、あそこは都営住宅が一緒に建っております。その中で、区内にこういう、前が公園になっていて、建替えたとき、以前の建物の容積率が使えなくなってしまうような、そういう建物というのはほかにも見受けられるような気がするのですが、何カ所ぐらいあるのか、その辺を教えていただきたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"このため、現在の住宅敷地で新たに建替えを計画した場合、委員のご指摘のとおり、同様の規模の住宅は建たないという状況です。このほか、このような課題を抱える同様の形態の住宅につきましては２カ所ほどあります。","voiceIndex":20,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"質問","question":"この容積率の緩和というか、もとに戻していく形ですが、公園の指定を外せばもとのとおり建てられるのかどうか、その辺が私もちょっとわからないのですが、その辺はどう考えたらいいのでしょうか。それと同時に、これを東京都に対して、区のほうから働きかけをすることはできないものなのか。","respondent":"松代防災まちづくり事業部長","answer":"委員からお話がありましたように、現行の法令の中では、公園敷地内に住宅を組み込んで建替えを行うということは非常に困難な状況だと認識しております。","voiceIndex":22,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"特区申請に今回もう時期的にも当たらないかもしれないのですけれど、何かそのような、新しい政策的にも、いろんなところで考えていっていただいて、品川区にとってメリットのある政策を展開していっていただきたいと思いますので、ぜひよろしくお願いしたいと思います。次に介護保険制度についてお聞きいたします。改めて、今回の改正の趣旨と、また大きな改正点についてお答えをお願いしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"それから３つ目としては、低所得者の保険料の軽減を拡充するということで、今まで以上に軽減を図っていくと。それから４つ目が、一定所得のある利用者については自己負担を２割へ引き上げるということで、やはり負担の公平化の部分が入っているという、このような改正点です。","voiceIndex":24,"id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最初に地域支援事業、新しい総合事業について確認させていただきたいと思います。現行の訪問制度、訪問介護利用者約１,３００人、通所介護１,６００人という資料がありました。この方々に対するサービスについて変更が生じてくるのでしょうか。サービスに対する基盤整備の点についても十分できているのかどうか、この点についてお答えをお願いいたします。","respondent":"榎本健康福祉事業部長","answer":"今回の総合事業ということで、訪問介護・通所介護のサービスの部分が地域支援事業に入ってくるという形です。ただ、平成２７年４月から品川区は実施していきますけれども、現状の要支援の利用者は、サービスを継続利用できることを基本としてサービスを組み立てております。","voiceIndex":26,"id":"exchange-013"},{"speaker":"鈴木（真）委員","kind":"質問","question":"それと、総合事業の利用者の方は大幅な増加がこれから見込まれていくと思いますので、その辺につきまして、介護予防に関して、特別養護老人ホームなどの利用というのは考えていかれないのかどうか、そこら辺もお考えをお聞きしたいと思います。元気な高齢者のボランティア参加について、こういう総合事業に対しても協力できないのかとか、そこら辺について区としてのお考えをお聞きしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"１点目の要支援者への説明ですけれども、やはり総合事業に当たって、介護サービスを提供する事業所に対してまず説明会を行っております。介護予防訪問事業・予防通所事業等の種類・内容・費用、あとＱ＆Ａを示して、事業移行を円滑に進めていくものです。","voiceIndex":28,"id":"exchange-014"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"やはりこれも心配される方が多いと思うのです。要介護度１・２の方もそうですし、要支援の方がこれから先、進んだときどうなるのということも、時々我々もお聞きします。その辺につきましてお考えをお聞きしたいと思います。医療との連携という点につきまして、区の中でどのように進めているのか、またこれからどう展開を図っていくのか、その点につきましてお聞きしたいと思います。","respondent":"榎本健康福祉事業部長","answer":"将来的な方向としましては、今、介護のほうで、地域包括支援センターシステムを持っておりますので、それとの整合性をどう図れるのかというものも視野に入れて、さらなる検討を進めてまいりたいと考えています。","voiceIndex":30,"id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"介護保険制度全体、またこれから品川区の福祉ということを考えた場合、福祉という面でもちょっと人が、経験者が少ないという点も考えてはいるのですが、これからの人材をどうするかという点も含め、区の全体の方向性につきまして、また新たな課題、この辺も考えまして、厚生委員会を担当していただいております山田副区長から一言お答えをいただきたいと思いますが、よろしくお願いします。","respondent":"山田副区長","answer":"今般も在宅生活を充実していくということで、各種の手当て等を含めて支えていくというところにボリュームを置き、なおかつセーフティーネットである施設建設については、障害者の施設であるとか、特別養護老人ホームも平成２８年・平成２９年と２カ所。","voiceIndex":32,"id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"改めていろんな政策をつくっていただいて、ご支援をお願いしたいと思います。今、２点、防災と介護についてお聞きしました。この協働について、町会という問題がやはり出てくると思うのですが、この町会に対する支援の仕方、考え方について、もちろん検討会をやっていることは承知しておりますが、改めて区としての考え方をお聞きしたいと思うのですが、よろしくお願いします。","respondent":"中川原地域振興事業部長","answer":"現在、区で進めております町会・自治会のあり方と区との協働に関する調査研究会におきましては、町会・自治会の実態調査を行いまして、現在、町会・自治会の現状、抱えている課題や負担等をお聞き取りするとともに。","voiceIndex":34,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"町会の加入促進をこれからも図っていただきたいと思いますし、条例化ということもぜひお願いしたいのですが、やはり私も町会に入っている中で、人がなかなか、役員がいないというのが一番の課題になっている。最後にもう一点、お聞きさせていただきたいと思います。その中で、今後の品川区の施策の展開、品川区の将来像につきまして、改めて濱野区長のお考えをお聞きしたいと思います。","respondent":"濱野区長","answer":"そうした財政的な影響と同時に、今お話のように、施設の老朽化の問題。こうしたことについても対応していかなければならないということで、課題は山積していると考えています。","voiceIndex":36,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"法人住民税２３億円のマイナス、大きな金額も出てくるというお話もありました。これからも我々、よりよい品川区として、「住み続けたいまちしながわ」を目指して、区長、行政部局、議会も一緒になって頑張っていきたいと思いますので、どうぞよろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-019"},{"speaker":"本多委員","kind":"質問","question":"鈴木真澄委員に引き続き、自民党の総括質疑を続けます。初めに代替地の考え方について伺います。例を４つ挙げまして質問したいと思います。西大井４丁目のふれあい作業所がこみゅにてぃぷらざ八潮を活用したとき。大崎シルバーセンターの建替えを現在やっておりますが、上大崎シルバーセンターに活用という、この４例について、暫定的とはいえ代替地として機能したのか、それぞれについてお聞かせください。","respondent":"榎本健康福祉事業部長、中川原地域振興事業部長","answer":"それで、距離的にはちょっと遠くて、３キロ弱ぐらいの移転の距離だったのですけれども、やはり八潮でのふれあい作業所につきましては、地域でのふれあい祭り等を２回実施しまして。現在に至るまで、伊藤学園温水プールを終了したことによる苦情は１件もなく、むしろ豊葉の杜学園温水プールについて、快適であるという声が区に届けられているところです。","voiceIndex":40,"id":"exchange-020"},{"speaker":"本多委員","kind":"質問","question":"通所についてはちょっと困難というか、迷惑な部分もあったということで、「距離」についてちょっと質問をしていきたいと考えています。例えば地域、民間の銭湯を見ると、南品川の１丁目から６丁目、東大井の１丁目から６丁目で銭湯がなくなったというようなケースは、やはり地域では、「近所でそういう施設が欲しい」というような意見があります。","respondent":"桑村副区長","answer":"今お話があったように、入居施設だとか、例えば通所施設、集会施設ですとか、大きなホールがあるとか、施設によっていろいろ状況が変わります。利用者の状況も年齢層もかなり違いますし、どういう場所にというのは、なかなか一定の基準では難しいのだろうと思います。","voiceIndex":43,"id":"exchange-021"},{"speaker":"本多委員","kind":"質問","question":"ルールをつくるのが難しいというのは十分理解しております。それと、あわせて新年度からの組織改正が行われますが、そういった場合、代替地を考えるときに、所管だけで考えることなく、できれば、全庁とまでは言わなくても横串で考えれば、もっと、こんなところにこんな活用場所があるとか、そういった工夫ができるのではないかと思うのですが、その２点についてお聞かせください。","respondent":"桑村副区長","answer":"そういった施設をどうやって探すかですが、もちろん所管課でも探すのは当然ですけれども、全庁的な意味からすれば、企画部門が間に入りまして、施設の有効活用という面で別途検討させていただいているのが今までの現状ですし、これからも続けていきたいと考えているところです。","voiceIndex":45,"id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"今後とも区政を進めていく上で、代替地がかなり必要になってくるケースがたくさんあると思いますが、ぜひスープが冷めない距離というものを目指して進めていただきたいと思います。それと、次に関連して質問していくのですが、平成３０年に竣工予定の芳水小学校内に、現行の大崎図書館の機能を整備できないか、伺います。西口につきましては、１カ所で充実していただきたいと思いますが、いかがでしょうか。","respondent":"田村教育次長","answer":"それで、そういう計画の中で大崎図書館の話がございましたので、大崎図書館の取り次ぎサービス的な設置も、芳水小学校の中で、今考えているのは、大崎図書館の取り次ぎサービスと閲覧コーナー、あと地域交流コーナー、地域の方が利用できるスペースということを、現在。","voiceIndex":47,"id":"exchange-023"},{"speaker":"本多委員","kind":"質問","question":"その経緯につきましては十分理解しております。本格設計は平成２７年度、これからですので、設計につきましては、もう済んでいるのはプロポーザルだと思うのです。主眼は、「機能を大崎駅西口」ということで、その区議会の意思をどう反映されるのか、その２点、もう一度お願いします。","respondent":"田村教育次長","answer":"もちろん、増加についても引き続き、これから各論に入っていきますので、検討してまいりたいと考えております。","voiceIndex":49,"id":"exchange-024"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ前向きに進めていただきたいと思います。次の質問に移ります。２つ目は、まちづくりについて伺います。そこで伺います。特に海外との交流促進の点で、深夜・早朝便に対応したバスダイヤとターミナル設備を確保していただきたいと考えますが、いかがでしょうか。五反田と羽田空港とが海上交通でつながるよう、東京都との連携を図っていただきたいと考えますが、いかがでしょうか。そして桜です。","respondent":"松代防災まちづくり事業部長","answer":"次に本桟橋につきましては、平時は民間利用が中心となることから、平成２７年度より需要推計や民間ニーズを把握したルートの検討、施設規模等の調査を行う予定です。","voiceIndex":51,"id":"exchange-025"},{"speaker":"本多委員","kind":"質問・要望","question":"中期的・長期的に取り組んでいく内容ですが、平成２７年度もしっかり取り組んでいっていただきたいと思います。ほとんど民間のバスが参入しておりません。東急バスが一部、ちょっと入っていますけれど、ほとんど山手線内の中のバスを見ると、都バスが主流になっているのですが、そういうのというのは、もっと民間活力というのを導入しないのか。現状をどう捉えているかお聞かせください。","respondent":"松代防災まちづくり事業部長、藤田都市環境事業部長","answer":"そういう中にあって、今ご質問にもありました正式な名称についても、さまざまな角度から検討し、またご意見を伺いながら決めていければと考えておるところです。いろんな形でバスの運行については申し入れをしていくことは可能ですけれども、その中で、それぞれのバス事業者が効率よく運行できるのがまず第一だと考えていますので、さまざまなご要望をお聞きする中で、何が効率的なのか。","voiceIndex":53,"id":"exchange-026"},{"speaker":"本多委員","kind":"提案","question":"わかりました。バスについては、現行をどう捉えているのかをお聞かせいただきました。次の質問に行きます。臨海部と大崎駅間の増発・増便を働きかけてはいかがでしょうか。そして、大崎と大井町はりんかい線で３分ですが、料金は２１０円です。りんかい線の大崎・大井町駅区間を限定で、ＪＲと同額の１６０円となるように提案してはいかがでしょうか。この点についてお聞かせください。","respondent":"藤田都市環境事業部長","answer":"そういう中で、現段階では料金についての見直しは難しいのかと考えています。","voiceIndex":56,"id":"exchange-027"},{"speaker":"本多委員","kind":"質問","question":"せっかくりんかい線があるので、活用して人のにぎわいのまちづくりにつながればと思って質問いたしました。次の質問に行きます。１つには、防災や祭礼といった、地域とのつながりを持つ地域行事・地域活動の活性化があります。２つ目、ここからは副都心大崎についてです。３つ目はホテル・宿泊機能の充実です。ゆうぽうとは閉館しますが、この点、宿泊機能についてお聞かせください。","respondent":"藤田都市環境事業部長","answer":"さらにこの春に竣工を迎えます北品川５丁目第一地区の再開発でも、スーパーマーケット等の商業施設の導入を図り、地区内のみならず周辺の方々にもご利用いただけるような店舗等をつくる予定となっています。","voiceIndex":58,"id":"exchange-028"},{"speaker":"本多委員","kind":"質問・要望","question":"ホテル一つとりましても、かなりリーズナブルなホテルが人気があったり、本当にホテルの数だけメニューがあると思いますので、ぜひ誘致等、できることを最大限やっていただきたいと思います。今、京都の清水寺では、平成の大改修というものをやっております。こういうことというのは日本人の感覚だと思いますが、品川区の将来へ向けたまちづくりについて、思いをお聞かせいただきたいと思います。","respondent":"藤田都市環境事業部長","answer":"計画を立てる中では、人口動向のように、そのスパンの中では様子に変化が見られるようなものもあり、その課題にすぐ解決しなければいけないこと、それが１００年後に、ストレートではありませんけれども。","voiceIndex":60,"id":"exchange-029"},{"speaker":"本多委員","kind":"意見","question":"今度、本当に目先のことをちょっと聞きますが、再開発組合の負担でさまざまな施設設備が整備されましたが、今後、更新の時期となり、当然、区の負担となります。品川駅東西自由通路の液晶ビジョンを参考に、まちの情報発信力を確保していく必要もあると思いますが、この点についてお聞かせください。","respondent":"藤田都市環境事業部長","answer":"こういった面では、区としても、さらなるにぎわいづくりに向けまして、エリアマネジメントとともにコンテンツの充実等に努めてまいりたいと考えています。","voiceIndex":62,"id":"exchange-030"},{"speaker":"本多委員","kind":"質問・要望","question":"有事の際、一番必要とされるのが、笛を所持すること、持参するという話が出ておりましたが、所持する習慣がないため、携帯電話の電話メーカー業界ですとか、国とかに、笛の機能を持たせた機器の開発を働きかけてみてはいかがでしょうか。それとあわせて、そういう笛が必要なときというのは、人を呼ぶということですから、初動体制などの心がけなどについてお聞かせください。","respondent":"松代防災まちづくり事業部長","answer":"今後も、災害時の正しい判断、行動についての知識などの啓発とあわせて、災害時に役立つ用品等について普及・啓発に取り組んでまいります。携帯そのほか、さまざまな民間での防災器具、そういった中でのものが今いろいろと提供されております。","voiceIndex":64,"id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"次の質問に行きます。教育について、教育委員会制度が改正され、教育長は、教育委員会の長、そして教育委員会事務局の長として二重に機能を持ち職責を負います。品川区の小中一貫のさらなる推進を期すという意味で、教育長のご決意をお聞かせください。","respondent":"中島教育長","answer":"今後の方向性ですが、現在、推進委員会で検討している内容、また浜川中学校地区で実施している品川区版コミュニティスクールとも言える内容、こういったものを、今後研究をさらに深めまして。","voiceIndex":66,"id":"exchange-032"},{"speaker":"本多委員","kind":"質問・要望","question":"決意を聞かせていただきました。それで、グローバル給食のことについて聞いていきます。私も全く同趣旨の質問をいたします。日本の伝統文化と品川の文化財等の意識を深めていただきたいと思います。１つの例文を取り上げます。「なまはげは児童虐待」という意見があるそうです。万事、説明や理屈が求められる時代だからこそ、無形文化財が一層重要になってきています。この点についてお聞かせください。","respondent":"田村教育次長","answer":"ですから、そういうのを考えますと、広い意味で言葉遣いあるいはマナー、家庭の教育力が低下して、そういうしつけがなかなか家庭の中でできない、集団生活になじめないということからしても、やはり無形文化財、あるいは広く一般の文化だとか習慣の重要性というのは。","voiceIndex":68,"id":"exchange-033"},{"speaker":"本多委員","kind":"質問","question":"ぜひ受容性をお願いいたします。最後に、東京オリンピック・パラリンピックに向けまして、品川区内の小中学校の全校の特色を参画させる仕組みづくりを伺います。それに、大きなセレモニーだと全校は無理だと思うのですが、アスリートを迎えるときとか、何かしらの形で今から準備して、全校が東京オリンピック・パラリンピックに参画できるよう、その仕組みづくりについてお聞きします。","respondent":"田村教育次長","answer":"四年半ぐらいですか、東京オリンピック・パラリンピックが開催されるということで、そういうきっかけを利用して、委員ご指摘のとおり、各校、特色を出してさまざまな取組みを実施しております。","voiceIndex":70,"id":"exchange-034"},{"speaker":"本多委員","kind":"意見","question":"何か、国の創生の話みたいに、みずから手を挙げるということで答弁をいただきました。ぜひそうなるように、受け皿をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-035"},{"speaker":"塚本委員","kind":"質問","question":"品川区議会公明党を代表して、こんの委員とともに総括質疑を行います。初めに、区の防災対策について伺います。３・１１東日本大震災以降、これまで品川区が取り組んできた防災対策の成果について、総括的にご答弁ください。平成２７年度濱野区長の施政方針では、引き続き防災対策を重点課題としています。災害に強いまちづくりのため、どのような施策を実施していくのか、区の方針をお聞かせください。","respondent":"松代防災まちづくり事業部長","answer":"今後の防災対策につきましても、平成２７年度も重点施策と据えまして、木密地域不燃化１０年プロジェクトの推進、また避難所等の整備、これまで進めてまいりました事業の継続的な進め方。そういったものにしっかりと取り組んでまいる所存です。","voiceIndex":74,"id":"exchange-036"},{"speaker":"塚本委員","kind":"提案","question":"これからも防災にしっかりと取り組んでいくのだというところが確認できたと思いますけれども、ただいまご答弁いただいたものも含めまして、品川区議会公明党といたしましても、３・１１以降、防災対策について幾多の政策を提案してまいりました。デジタルサイネージなど、新たな情報媒体も活用した施策を求めますが、いかがでしょうか。","respondent":"松代防災まちづくり事業部長","answer":"特にデジタルサイネージによる情報伝達については、災害時協力協定により、区の災害時情報発信の一元化システムからデジタルサイネージに情報を提供する仕組みを構築しています。今後は災害時情報の提供に協力する事業者の確保について検討を進めてまいります。","voiceIndex":76,"id":"exchange-037"},{"speaker":"塚本委員","kind":"質問","question":"実際に、受け手の側としての事業者を探すということでございましたが、この辺につきまして、何か具体的にもう少しお答えできるものがあれば伺いたいと思います。そこで質問です。崩れる危険性がありそうな崖・擁壁に対しては、目視による調査だけでなく、より詳細な調査を実施して、危険性を正確に把握すべきと思いますがいかがでしょうか。区として考えられる施策をお聞かせください。","respondent":"松代防災まちづくり事業部長、藤田都市環境事業部長","answer":"今後とも、こういった例を踏まえまして、さまざまなところで民間の力をお借りする中で、そういったことの構築に努めていきたいと考えております。エリアにつきましても、ただいま申したとおり、補強のための支援については、区内全域でやるといっても、実際に実施するのは擁壁がある場所になりますので。","voiceIndex":78,"id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"燃えにくいまちづくりについて伺います。そのため、平米当たりの工事単価が、他の工事よりも高くなる傾向があるのではないでしょうか。現行平米単価２万１,０００円は、耐震化支援事業と比べて自己負担額が多くなる場合はないのか教えてください。そして、不燃化特区の事業の目的を損なうことがないよう、きめ細かな支援が必要と考えますが、区のご見解をお聞かせください。","respondent":"藤田都市環境事業部長","answer":"こうしたことを考慮いたしまして、平成２７年度につきましては、今回の予算の中でもご提案申し上げていますとおり、単価を５,０００円アップいたしまして２万６,０００円とすることで、所有者の負担軽減を図りまして。","voiceIndex":81,"id":"exchange-039"},{"speaker":"塚本委員","kind":"提案","question":"ここで質問ですけれども、木造住宅密集地域の解消のため、空き家の除却で空地をつくることは、区の空き家条例第１４条で言うところの有効活用を促進することになるとの理解でよいか、お伺いいたします。空き家の除却においても、文京区のような固定資産税が非課税となる施策によって、不燃化特区以外の木造住宅密集地域でも密集の解消を進めてはいかがかと提案いたしますが、区のご所見をお伺いします。","respondent":"藤田都市環境事業部長","answer":"こうした制度につきましては、木密地域の改善のための特別な支援策として不燃化特区のエリアの中で行われているものですので、ほかの地域でも展開することは困難かと考えています。","voiceIndex":83,"id":"exchange-040"},{"speaker":"塚本委員","kind":"質問","question":"木密の解消のためにさまざまな手法を利用・活用していただいて、不燃化領域率が上がるということが得られればと思いますので、よろしくお願いしたいと思います。款別審査でも質疑のあったところですが、改めて、有識者検討会がまとめた報告書の内容とはどのようなものであり、今後、品川区に及ぼす影響について伺いたいと思います。","respondent":"松代防災まちづくり事業部長","answer":"しかしながら、本検討会の報告書については、本年２月に発表された感震ブレーカー等の性能評価ガイドラインを足がかりとしまして、密集市街地における重点的な普及促進や普及方策を検討するためのモデル調査の実施など。","voiceIndex":85,"id":"exchange-041"},{"speaker":"塚本委員","kind":"質問","question":"さきの有識者検討会では、既存の住宅にも設置が広がるよう自治体に要請しています。このことに関しても款別審査で質疑がありまして、区は、「広報や情報提供に努める」との答弁でありましたが、感震ブレーカーの現状の課題をよく見きわめた上で、購入あっ旋や取り付け工事助成なども検討の余地があるのではないかと思いますが、ご所見をお伺いします。","respondent":"松代防災まちづくり事業部長","answer":"機器の性能評価をはじめ、設置における技術的な基準や手法もこれから整理されるなど、多くの課題もあります。こうした状況を把握した上で、感震ブレーカー等の普及における対応を検討していくことが必要であります。","voiceIndex":87,"id":"exchange-042"},{"speaker":"塚本委員","kind":"質問・要望","question":"よろしく検討のほうを進めていただければというような思いです。次に、子育て支援のさらなる充実を求めて質問いたします。平成２７年度予算案で、（仮称）しながわネウボラネットワーク検討と、国の子育て世代包括支援センターとの関連性の違いについて教えてください。（仮称）しながわネウボラネットワーク検討を始めるに至った背景と、品川区の子育て支援のどのような課題を検討するのか教えてください。","respondent":"金子子ども未来事業部長","answer":"一方、これから区で検討してまいります（仮称）しながわネウボラネットワークは、国の制度を参考としまして、品川区独自の、妊娠から出産、子育てまでの切れ目のない支援を行おうとするものです。","voiceIndex":89,"id":"exchange-043"},{"speaker":"塚本委員","kind":"意見","question":"さて、平成２６年６月１２日に開催された品川区子ども・子育て会議では、病児・病後児保育についての議論がなされ、現在の病児保育２施設、病後児保育４カ所では、ニーズに対して足りないという議論がありました。その上で、他自治体や民間事業者が実施している訪問型の病児・病後児保育をどのように評価するかもお聞かせください。","respondent":"金子子ども未来事業部長","answer":"先ほどと同じように、子どもの体調急変時に緊急の対応を必要とされていること。さらに家庭で子どもと１対１の対応となることから、労務管理の問題などがあります。加えて、行政がこれを支援するとなれば、利用要件について事業者との調整が必要となってくる。","voiceIndex":91,"id":"exchange-044"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、ご答弁を伺いました。いずれにいたしましても、現状の病児・病後児保育の課題を解決するために、他自治体の事例、あるいは民間でいろいろ進められているものもよく参考にしながら研究・検討を進めていただきたいという思いですので、どうぞよろしくお願いしたいと思います。そして、利用実績が上がらない理由について区の見解を伺います。","respondent":"金子子ども未来事業部長","answer":"支援の中身は、一般に産前は出産予定日より１カ月前から５日を限度、産後は退院した翌日から１年以内で１０日を限度としております。なお、２０歳未満の若年出産の場合は産後の日数を１５日、多胎児につきましては３０日と限度を拡大しております。","voiceIndex":93,"id":"exchange-045"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、「虐待に」という１つの前提の中でということでしたので、在宅子育ての日常生活において求められている支援とは何であるのかということをきめ細かく捉えていくべきではないかと考えています。その上で、現在の支援では足らざるところを適切に支援する体制を整備すべきと思いますが、区のご所見をお伺いします。","respondent":"金子子ども未来事業部長","answer":"今後につきましては、先ほど申し上げました、（仮称）しながわネウボラネットワークの検討の中でニーズをきめ細かく把握しまして、支援策について検討してまいりたいと思っています。","voiceIndex":95,"id":"exchange-046"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうした中で、平成２７年度より子ども・子育て支援新制度が本格実施となり、今後、品川区における待機児童対策をどのようにお考えになっていくのでしょうか。今回、残念ながら１次、２次とも不承諾となってしまった方々への支援策が求められますが、こうした現状を区が分析し検証した上で、今後の子ども・子育て支援新制度の中でどのように反映され、対策が図られていくのか、お考えをお聞かせください。","respondent":"金子子ども未来事業部長","answer":"加えて平成２２年度からは入園申込者の急増に対応しまして、緊急総合対策として、既存保育園の定員拡大・弾力化、あるいは児童センター、小学校を活用した受け入れ枠の拡大を図ってまいりました。","voiceIndex":99,"id":"exchange-047"},{"speaker":"こんの委員","kind":"質問・要望","question":"この事業計画によれば、例えば施設型給付施設の保育園では、毎年二、三園ずつ整備する計画になっていますが、今後の保育施設整備は、公有地活用など、どのように実行されようとお考えでしょうか。先ほどのご答弁でもありました、「積極的に」とありましたけれども、こうした国の動きを注視しながら、品川区としても総合的な保育施設のいわゆる福祉施設の整備も要望したいと思います。","respondent":"金子子ども未来事業部長","answer":"今後の保育施設の整備についてのご質問ですけれども、先ほどもお答えしましたとおり、人口動向あるいはニーズを踏まえながら、これまでどおり民間事業者からの提案による認可保育園あるいは小規模保育事業あるいは認証保育所などの整備をするとともに。","voiceIndex":101,"id":"exchange-048"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで、子ども・子育て支援新制度に基づく保育の必要性の区分認定など、今後の短時間就労対応型保育事業はどのように展開されようとお考えでしょうか。保護者の働き方や子育てなどのライフスタイルが多様化する中、短時間就労を希望する子育て家庭を支援するための短時間就労対応型保育事業の拡充を要望します。それぞれご見解をお聞かせください。","respondent":"金子子ども未来事業部長","answer":"こうした意味で、今後のニーズというのは変化が予測されますので、このニーズの動向を見て、具体的な対応については今後検討してまいりたいと考えています。","voiceIndex":103,"id":"exchange-049"},{"speaker":"こんの委員","kind":"意見","question":"ぜひニーズを捉えて拡充をお願いしたいと思います。さて、共働きの子育て家庭では、できれば出産後、在宅でゆっくりと子育てをしたい。そう願う保護者は少なくありません。今後ますます女性の活躍が期待される中で、安心して両立できるワークライフバランスの必要性を考えれば、育児休業をしっかり取得できるよう後押しをすることが必要と考えますが、ご見解をお聞かせください。","respondent":"金子子ども未来事業部長","answer":"平成２５年度では４８６名の申し込みに対して１４７名が内定しております。この制度は平成２０年６月から開始した制度でありまして、その間、受け入れ枠を拡大してまいりました。希望者が多いこと、また育休明けまで安心して過ごせることから一定の高評価があると考えています。","voiceIndex":105,"id":"exchange-050"},{"speaker":"こんの委員","kind":"質問・要望","question":"ぜひ、さまざまなニーズを捉えての保育施策、そして品川区の待機児童対策を求めてこの質問を終わります。近年、高齢化が急速に進行する中、高齢者が生き生きと暮らすことのできる社会の実現が求められます。今後の見通しとして、単身や夫婦のみの高齢者世帯が増加し、介護も含めニーズが多様化する中、地域包括ケアシステムの構築に向けた高齢者の住まいについてはどのようにお考えでしょうか。","respondent":"榎本健康福祉事業部長","answer":"今後の方向性ですけれども、高齢者住宅、建設型・借上型ともに、将来的に維持管理の方法、いろいろ課題はありますけれども、継続していきたいと考えています。","voiceIndex":107,"id":"exchange-051"},{"speaker":"こんの委員","kind":"質問","question":"このサービス付き高齢者向け住宅という１つの方向性をされていますけれども、この住宅は医療や介護、生活支援サービス、そうしたものがついておりまして、家賃は少し高目に設定されております。こうした相談窓口の開設により、今後、高齢者の生活実態や困窮度合いなど、どのように把握され対応されようとお考えでしょうか。民間賃貸住宅など、高齢者の住まいへの支援についてもお聞かせください。","respondent":"榎本健康福祉事業部長","answer":"今年の４月から生活困窮者自立支援法が施行されていきます。その中で、区といたしましては、第２庁舎の３階のところに相談窓口を新たに設置しまして、生活に困窮されている方々の自立支援相談等、支援の実施をしてまいります。","voiceIndex":109,"id":"exchange-052"},{"speaker":"こんの委員","kind":"提案","question":"関係部署との連携というお話が出ました。高齢者の多くは住み慣れた地域で可能な限り住み続けたいと望んでいます。円滑な居住確保のためには、孤独死や室内事故あるいは家賃滞納などのリスクを懸念する大家へ協力を求める支援策が必要と考えます。課題解決の具体策としては、これまで区議会公明党より、居住支援協議会の設置を提案してきました。ご見解をお聞かせください。","respondent":"榎本健康福祉事業部長","answer":"居住支援協議会の設置というお尋ねですけれども、先行している区等の動向も踏まえまして、効果的な課題解決に結びついているかなど、そういうことを研究していきたいと考えています。","voiceIndex":111,"id":"exchange-053"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで、全国的にも品川区的にも問題になっております空き家や空き室の中には、例えば平成２０年度の東京都の空き家総数７５万戸のうち、活用可能とされる腐朽・破損なしの空き家数は５５.２万戸で、活用可能なその空き家を活用するという考え方を品川区にも持っていただきたい、このように求めますが、いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"したがいまして、まずは今回の空き家調査をもとに、民間の需給ベースに乗せるべき物件、もしくは区が関与すべき物件等、さまざまな想定がされてまいりますので、空き家活用のモデルケースなどを検討しつつ、継続的に調査・研究をしていきたいと考えています。","voiceIndex":113,"id":"exchange-054"},{"speaker":"こんの委員","kind":"意見","question":"ぜひ、調査・研究をしていただきながら、実態調査後、ぜひ品川区でもそのような活用をお願いしたいと思います。以上をもちまして、区議会公明党の総括質疑を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":115,"id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"よろしくお願いします。は待機児童対策についてお伺いいたしたいと思います。平成２７年度においても７００名余の受け入れ枠を増やしていくところだと伺っておりますが、前年度よりも保育園入園の不承諾数が増えており、さらには子どもの人口が増加していることから、今後も待機児童の増加が危惧されるところであります。待機児童対策について、品川区の現状について伺います。","respondent":"金子子ども未来事業部長","answer":"私立保育園、認証保育所、家庭的保育事業の開設支援など、平成２２年度から平成２６年度まで、ご紹介がありましたとおり、５年間で２,９７９人の受け入れ枠の拡大を実施してまいりました。","voiceIndex":118,"id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"初めての子育てで、まず何がわからないかがわからない、そういった声も、地域を回る中で伺っているところであります。メルマガ配信など、区から主体的に育児情報の発信を行うことは今後可能でしょうか。アクセスのしやすさ、気軽さ、より早く、より多くの方に拡散力のあるＳＮＳの活用も、既存のホームページとあわせて検討していただきたいと思いますが、お考えをお聞かせください。","respondent":"金子子ども未来事業部長","answer":"情報に関してのお尋ねですけれども、区ではさまざまな所管で多くの子育て支援の事業や相談を実施しておりまして、これらの周知というのは非常に重要なことだと考えております。","voiceIndex":120,"id":"exchange-057"},{"speaker":"大倉委員","kind":"質問・要望","question":"こういったメール発信とかＳＮＳの利用とかというのは、ぜひとも今後、検討していただきたいと思いますので、よろしくお願いいたします。次に、育児が安心してできる環境の整備についてお尋ねします。品川区として、一時保育の育児支援の制度について現在抱えている課題は何があるとお考えでしょうか。今後、それぞれの制度について拡充を図っていただきたいと考えておりますが、お考えをお聞かせください。","respondent":"金子子ども未来事業部長","answer":"具体的なお尋ねとして、保育園での一時保育のお尋ねがございました。今、区立の各園では最大２名枠を確保しているわけなのですけれども、多くの待機児童がいる中で、なかなか受け入れ数、それから即時性といいますか、すぐに緊急に対応するというのが難しいところがあります。","voiceIndex":122,"id":"exchange-058"},{"speaker":"大倉委員","kind":"質問・要望","question":"もう一方で、人の不足というのが問題なのでしょうか。次に防災について質問いたします。幅広い防災訓練への参加について伺います。現在の防災訓練の実施状況や訓練の内容についてお知らせください。あわせて防災訓練の参加数の現在の考え方について伺います。防災訓練への若い世代の参加が、今、残念ながら少ないことが私は課題と考えていますが、区のお考えをお聞かせください。","respondent":"松代防災まちづくり事業部長","answer":"総合防災訓練の実施状況ですが、毎年、１３の地区防災協議会が主催し、９月から１１月に１２の会場で実施されております。","voiceIndex":124,"id":"exchange-059"},{"speaker":"大倉委員","kind":"質問","question":"そういった若い世代も取り込むために、現状とはまた違う活動が必要になるのではないでしょうか。区としては、どういった点に若い世代を取り込むための課題があるとお考えでしょうか、お聞かせください。共助の考え方から言えば、地域の防災訓練にも参加して、顔の見える関係づくりも非常に大切と考えますが、区のお考えをお知らせください。","respondent":"松代防災まちづくり事業部長","answer":"訓練を通してつながりができれば、総合防災訓練以外の訓練への参加や、避難行動要援護者への支援体制づくりなど、発災時の地域における共助の基礎の強化が期待できる。波及効果も大きいと考えておるところです。","voiceIndex":126,"id":"exchange-060"},{"speaker":"大倉委員","kind":"質問・要望","question":"ぜひ若い世代も防災訓練へ参加できるよう、また参加しやすいように取り組んでいただきたいと思います。そこにちょっとかかわってきますが、次に子どもの防災訓練への参加について伺います。子どもの参加状況は、先ほど数字が多少出ていましたが、参加状況とあわせて、区の対応についてもお伺いいたします。","respondent":"松代防災まちづくり事業部長","answer":"区としても対応が必要だと認識しており、これまでも、児童センターを利用する子どもたちをセンターの活動の一環として訓練に参加いただいたり、学年単位や学校単位での訓練に参加するなど、子どもの訓練参加促進に取り組んでおります。","voiceIndex":128,"id":"exchange-061"},{"speaker":"大倉委員","kind":"質問","question":"そうした、子どもが防災訓練に参加しやすいようなプログラムを考えていく必要があると考えますが、区のお考えをお伺いします。ＮＰＯ団体などと協力して、子どもに向けた防災訓練を行っていくような試みは可能でしょうか。子どもが防災訓練に参加することで、子ども自身の防災意識が高まること、親の防災訓練への参加というメリットが大きいと思うのですが、区のお考えをお知らせください。","respondent":"松代防災まちづくり事業部長","answer":"具体的な協力につきましては、協力いただける団体や、必要な協力・連携の仕組みなど、地域ごとの状況により異なるため、各地区の防災協議会ともご相談しながら検討する必要があると考えているところです。","voiceIndex":130,"id":"exchange-062"},{"speaker":"大倉委員","kind":"確認","question":"それと同じ事態に陥っていないでしょうか、区の現状をお聞かせください。特に協定の確認について、その後の実効性をしっかり担保するような取組み、例えば数年に１度、見直しや更新、改定を行っていく等の必要があると考えますが、どのように進展しているのかお聞かせください。協定について、今後新たに結んでいく予定があるのか、将来の展望を踏まえて区のお考えをお聞かせください。","respondent":"松代防災まちづくり事業部長","answer":"今後の協定の見直しや確認についてもこれまでの取組みを継続してまいります。協定内容の見直しや更新につきましては、適宜、実施して行う予定です。このような体制により、協定の具体的な見直し・確認は、３年から５年に１度の頻度で行っていきたいと考えております。","voiceIndex":132,"id":"exchange-063"},{"speaker":"大倉委員","kind":"質問・要望","question":"災害に備えて、防災協定は万が一のときに重要な生命線であると考えております。しっかりと協定内容が機能しているのか、これからもしっかり確認を行っていただきたいと思います。これからも安心して住み続けられる、住み続けたい品川区のために、引き続きご努力よろしくお願いします。以上で質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":134,"id":"exchange-064"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"大倉委員に引き続き、民主・改革ネットを代表して総括質疑を行います。私からは、住む、働く、遊べる品川区のまちづくりについて、そして国際都市品川区に向けての取組みについて質問をいたします。初めに観光施策についてであります。品川区の観光について、まず区の考えを教えていただきたいのと、観光といって何を頭に浮かべるでしょうか。それもあわせてお答えください。よろしくお願いします。","respondent":"中川原地域振興事業部長","answer":"来年度は１０年ぶりに、基本指針である観光アクションプランの見直しを図るとともに、５年後に控えました２０２０年東京オリンピック・パラリンピック開催を見据えましてさらに組織改正を行いまして、文化・芸術・スポーツ部門との連携強化も図っていくものです。","voiceIndex":136,"id":"exchange-065"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そんな中で、東京都で今、「ＥＡＴ 東京」という、メニューを多言語化するアプリ等も開発されて、実際に今、運用がされていると思いますが、そういったものもぜひ活用していただいて、区内の例えば商店等にも、そういった多言語化のメニューの導入だったり、あとは写真を撮るというのは、例えば写真スポットを品川区として、ここだったらこういう写真が撮れるというものを、ぜひ街角等に。","respondent":"中川原地域振興事業部長","answer":"町歩きのグループとか、休日に近隣から訪れるファミリー層とか、ゲストハウスに宿泊する、暮らすように旅する方々、そして東京にビジネスで来訪したビジネスマン等、そういった状況を具体的にイメージしながら。","voiceIndex":138,"id":"exchange-066"},{"speaker":"石田（し）委員","kind":"提案","question":"それは、来てもらうだけではなく泊まってもらって、その泊まってもらった人たちにどうやって品川区の魅力を発信してもらうかというのも新たな展開だと思いますので、その辺の考えを教えていただきたい。提案ですが、私は品川区を、「アートのまち」にしてみてはどうかと思います。そういった水辺の取組み。そういったことによって観光施策の充実に取り組めると思いますが、改めて区の考えをお知らせください。","respondent":"中川原地域振興事業部長","answer":"品川区の場合は、民間の方々にもそうしたアイデアを持つ方々がたくさんいらっしゃいまして、今、区にもいろいろなアイデア、提案を寄せていただいているところですので、そうした民の力と、区が税金を使ってやるべきご支援とをさまざま組み合わせながら。","voiceIndex":140,"id":"exchange-067"},{"speaker":"石田（し）委員","kind":"提案","question":"この議会からも、さまざまな場面で、花火大会の提案をしていますが、ぜひ、品川区を知ってもらうためには訪れてもらうのが一番の効果でありますので、そういった花火大会の実現に向けてもぜひお願いしたいと思います。事前情報で判断するわけでありますので、海外のガイドブックやパンフレットにぜひとも品川区の取組みを紹介するようなアプローチをかけるべきだと思いますが、その点もお答えください。","respondent":"中川原地域振興事業部長、山田副区長","answer":"そういった意味で、行政が直接関わっていない中にも、このまちには全国から人を呼べる力がたくさんありますので、そういったものを、先ほどご提案のＳＮＳとか、これはインターネットの口コミだと思うのですが。花火も、生の花火だけではなく、これを使ってということも、ある意味では民間の方がおっしゃる点もありますので、有効に、総合的に考えていきたいと考えています。","voiceIndex":142,"id":"exchange-068"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"もう既に実現しているのであれば、私がここでこういった質問をする必要はないので、ぜひとも、区民の声をもちろん聞いて、さまざまな民間の活力も使いながら区として取り組んでいただければと思います。私としては、例えば区民憲章など、いいものはそれを軸に、品川区の強みを活かした施策へと進んでいっていただきたいという思いもありますので、その辺もぜひお答えください。よろしくお願いします。","respondent":"桑村副区長","answer":"ちょっと前段のご質問ではないのですけれども、後段のシティプロモーションあるいは観光アクションプラン、またはマスタープラン等の連携ということについてお答え申し上げたいと思います。","voiceIndex":145,"id":"exchange-069"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"まさに私が考えているものと共通する考えだと思いますので、ぜひ進めていっていただきたいと思います。住み続けてもらうための施策、そして住んでもらうための施策について、どのような取組みをされていくのか、区のお考えを教えてください。","respondent":"中川原地域振興事業部長、桑村副区長","answer":"そのほか、勤労者共済会も、この間、改善・改革を進めてまいりまして、福利厚生の面でも、２３区の中でも充実している状況であり、中小零細企業の方々が働き続けていただけるまちでありたいということで努力をしてまいったものです。基本は、長期基本計画を確実に実施していくというのが基本の考え方ですけれども、今、区として求められているのは、安全で安心なまちをいかにつくっていくかということなのだろうと思います。","voiceIndex":147,"id":"exchange-070"},{"speaker":"石田（し）委員","kind":"質問","question":"もう既に大倉委員から、防災、また子育てについては質問していますので、多くは語りませんが、ぜひ、ＳＮＳも含めて、情報社会の中で、これからは各自治体を住民が選んでもらう。そういった住民の意識が高まってくるのだと思いますので、ぜひそうして選んでもらう。そこで、働く人に対しての質問ですが、公契約条例について少し質問させてください。よろしくお願いします。","respondent":"中山総務部長","answer":"こういうふうな動きにもしっかりと区としては対応しながら、事業者の安定的な運営、また工事の質の確保といったものを図っていきたいと、このように考えております。","voiceIndex":150,"id":"exchange-071"},{"speaker":"石田（し）委員","kind":"質問","question":"ぜひ今後もしっかりと検討していただき、取り組んでいただければと思います。国際都市品川に向けての取組みについて質問します。英語教育について、区の取組みと考えについてまずお聞かせください。」 そういった、コミュニケーションを重視した英語教育に進むべきだと思いますが、そこの区の考えをお答えください。それと、これまでの成果と今後の取組みについてもあわせてお答えください。","respondent":"田村教育次長","answer":"現状での取組みですが、小山台小学校のカリキュラムの実施を、現在、３校で実施しているということでございまして、その中で、イングリッシュキャンプを実施したり、あるいは外国人の講師と英語のコミュニケーションを図る機会をつくったということ。","voiceIndex":152,"id":"exchange-072"},{"speaker":"石田（し）委員","kind":"質問","question":"先日、東京青年会議所が主催した英語スピーチコンテストに、私も参加し、聞かせていただきましたが、その中で子どもたちが夢について語りました。次にグローバル人材の育成について質問します。品川区は今、グローバル人材を育成しようとしている中で、私はまずは区の職員にもその意識を持ってもらいたいと思いますので、例えば育成体制として留学制度など、そういったものも導入するべきではないか。","respondent":"中山総務部長、田村教育次長","answer":"職員の育成・専門性という観点からお答えいたします。海外派遣を東京都の場合で調べますと、１人当たり、場所によってもちろん違うのですが、１年間派遣すると約２,０００万円の費用がかかるということで。このようなことを考えてあります。","voiceIndex":154,"id":"exchange-073"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"そういったボランティアの育成にも努めていただきたいと思いますが、その点をお答えください。海外に目を向けるということで、日本の文化と伝統を守るといった視点も出てくるかと思います。そういった中で、日本、東京、品川区を紹介、また語れるような教育プログラムだったり、昔ながらの建物・風景の保存といった、日本の文化伝統を守る施策について区の考えをお答えください。","respondent":"中川原地域振興事業部長、田村教育次長","answer":"東京オリンピック・パラリンピックに向けましても、組織委員会や東京都からまだ具体的な内容は示されておりませんが、それに向けてもボランティアの有効活用について積極的に取り組んでまいります。それで、グローバル人材育成塾でも、カリキュラムの中にそれを取り組んで、自分のまちをＰＲ、品川区のまちをＰＲする授業等に取り組んでおりますし、また中学校の教科書、８年生の教科書でも。","voiceIndex":158,"id":"exchange-074"},{"speaker":"石田（し）委員","kind":"提案","question":"さまざまな提案も含めて質問させていただきました。ぜひ前向きに検討していただいて、その実現に向けてよろしくお願いいたします。以上で、民主・改革ネットを代表しての総括質疑を終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":161,"id":"exchange-075"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは介護保険大改悪による要支援のサービス取り上げはやめ、充実を求めて質問します。そのほか、保険料、そして特別養護老人ホームについても伺います。そこで示された単価は幾らになったのか伺います。新たな総合事業の生活機能向上支援事業、ヘルパーの週１回の基本の月額単価は幾らになったのか。予防通所事業、デイサービスの週１回の基本の単価が幾らになったのか、それぞれ教えてください。","respondent":"榎本健康福祉事業部長","answer":"区だけが独自で下げているというものではございません。そういった中で、今お尋ねの生活機能向上支援の部分につきましては、単位数ではなくて金額ということなので、１万１,４００円という形です。","voiceIndex":163,"id":"exchange-076"},{"speaker":"石田（ち）委員","kind":"質問","question":"これだけ単価が下がるとどうなるのか、現場に行って伺ってきました。国による２.２７％の介護報酬の引き下げ。それによって要支援者を受け入れられない事業所が出れば、受け皿がなくなり、結局、サービス取り上げになるのではないでしょうか、伺います。介護報酬単価の引き下げが、さらに介護職の地位を低迷させ、募集しても集まらないという事態を広げると思うのですが、いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"そこに今、パネルで示されているものは、本当の基本の金額だけです。例えば下の段、デイサービスでいきますと、その枠組みが大きく変わりましたので、標準的な送迎・入浴を加えた場合には１万７,２２２円ということで、金額がそこに示されているものとは違うという形になります。","voiceIndex":165,"id":"exchange-077"},{"speaker":"石田（ち）委員","kind":"質問","question":"結局、加算をしなければ、頑張って加算をつけないと、サービス単価が上げられないということだと思うのです。事業所は要支援のサービスはやっていけないと。ほかの事業を考えなければ経営も危ないと、大変悩んでいます。赤字でも頑張れということなのでしょうか、伺います。","respondent":"榎本健康福祉事業部長","answer":"そうなると、やはり地域によっていろんな工夫ができないということもありますので、そういう工夫を取り入れられるように総合事業という形での組み立てにして、各自治体が創意工夫を図って、その地域に応じたものをできるようにということで、枠組みを切り替えたものです。","voiceIndex":167,"id":"exchange-078"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"事業所がなくなっていくということは、サービス取り上げと一緒ではないかということを伺いました。事業所は何を頑張ればいいのか。そして、職員を削れということなのでしょうか。頑張ってもだめだったら廃業しても仕方がないということなのでしょうか。４月からの要支援者の介護給付費サービスの取り上げは中止し、事業所の単価は今までと同等にすべきと強く求めますが、いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"そういった中で、事業所のほうですけれども、各事業所にも説明をして、この総合事業にできるかどうかというのも十分協議しながら進めているところですので、４月からの実施に何ら問題はございません。","voiceIndex":169,"id":"exchange-079"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"認定については変わらないと言っているのですけれども、この給付費を大きく削っていくのが今回の総合支援法ですので、ではどうやって給付費を削減していくのですか。そして、品川区も給付費削減に伴い、保険料引き下げをするべきと思いますが、いかがでしょうか。低所得者ほど重くのしかかる介護保険料は、値上げではなく、この増収分も使って引き下げこそすべきですが、いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"そういった意味では先行きまで見て、これから後期高齢者が３年後には高齢者の中の半分を超えるという形も想定されていますので、そういった中で介護需要等を見きわめながら、こういう設定をしているという形ですので、この金額、５,３００円を引き下げるつもりはございません。","voiceIndex":171,"id":"exchange-080"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ほかの各保険料や出ていくお金は増え、入ってくるお金は減るという状況ですので、この品川区が進める介護保険料、決められるわけですから、そして準備基金からもどれだけ出すかを区が決定できるわけですから、この引き下げこそしていただきたいと、そして、２５億円の増収分が入るわけです。給付費削減で１億８,０００万円余が平成２７年度給付費を削ることによって削減されます。","respondent":"榎本健康福祉事業部長","answer":"新聞報道によりますと、２１区の平均の保険料は５,６９０円ということですので、品川区の５,３００円というのは、特段の高いほうにはないと認識はしております。","voiceIndex":173,"id":"exchange-081"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これだけサービス料が低いということではないでしょうか。特別養護老人ホームも整備率は２３区で２１位。低所得者ほど重くのしかかる介護保険料は、値上げではなく引き下げを求めて次に移りたいと思います。最後に特別養護老人ホームについて伺います。現在、待機者は６４０人。広町２丁目、劇団四季隣の区有地は、開発ではなく特別養護老人ホーム増設に使うべきと思いますけれどもいかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"それから広町２丁目のところにつきましては、暫定利用ということで、やはり特別養護老人ホーム等の高齢者福祉施設は、ある程度一定の数十年という期間で設置しないと、中に入っている入所の方が不安に思うという形になりますので。","voiceIndex":175,"id":"exchange-082"},{"speaker":"石田（ち）委員","kind":"質問","question":"広町２丁目の劇団四季隣の区有地は、開発の暫定地として２２年間も塩漬け状態になっている土地です。暫定、暫定と言いますけれども、いつまで暫定にしておくのか。今こそ、区民の財産である区有地は、特別養護老人ホームなど区民の切実な願いの実現にこそ使うべきだと思いますけれども、いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"用地というものはそれぞれの目的でもって使うという形で整理しているわけですから、それぞれの目的のところでそういう用地の考え方をとっていかざるを得ないと考えております。","voiceIndex":177,"id":"exchange-083"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"結局、介護でも、２３区中最低です。保険料は上がるのに、サービスは使えない。特別養護老人ホームにも入れない。高齢化のピークに備えるなら、公的保険による介護は抑制ではなく充実こそ必要です。特別養護老人ホームについては、品川区には土地もお金も十分にあります。誰もが入れる特別養護老人ホームのさらなる増設の計画を早急につくっていただきたいと思います。いかがでしょうか。","respondent":"榎本健康福祉事業部長","answer":"それぞれ、さまざまな手法が出てきておりますので、一つだけの施設をとって、それでもっていくという形にはならないので、総合的な判断をしてやっていきたいと考えています。","voiceIndex":179,"id":"exchange-084"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"総合的にということですけれども、どこも利用料が高いわけです。それで、やはり誰でも入れる、低所得でも入れる特別養護老人ホームを、本当に多くの方が切実に求めています。入れずに申し込み続けて亡くなる方もいます。ですので、ぜひとも特別養護老人ホーム増設、そして「公的保険の介護は充実を」を求めて私の質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":181,"id":"exchange-085"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、一人の待機児も出さないための認可保育園大幅増設を求めて質問をいたします。区長がこの思いを受けとめて、自治体としての責任を果たすこと、区長みずからが掲げた待機児ゼロの公約を守ることを求めて質問します。３月１３日に公表された２次募集の選考結果についてお聞きします。そのうち、４月の受け入れ枠拡大は何人分なのか。そして、その中で０から２歳児は何人分なのかについてお答えください。","respondent":"金子子ども未来事業部長","answer":"内訳は０から２歳が１,０２９件、３歳以上が１２５件です。それから平成２７年度のいわゆる受け入れ枠の拡大数ですが、こちらについては７０９人です。そのうち、４月に新たに拡大する数が３７０人、そのうちの０から２歳は１８８人です。","voiceIndex":183,"id":"exchange-086"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１次と２次の申請数は３,０６０人です。入れなかった子どもはそのうち１,１５４人。１,１５４人もの子どもたちが入れないという過去最悪の事態となりました。このことについてどう捉えているのかをまず伺いたいと思います。育児休職明けで４月に復帰。一体、１,１５４人の入れなかった人たちはどうしたらいいと考えているのか。この人たちは一体どうすればいいと考えているのかについてもお答えください。","respondent":"金子子ども未来事業部長","answer":"今年度、７０９人という数を、受け皿の拡大の数をお出ししておりますけれども、これはここ数年来、なかった数でありますので、引き続き、保育園の入園申し込みが増加するような傾向に関しましては、積極的に対応していきたいと考えています。","voiceIndex":185,"id":"exchange-087"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"７０９人と言われますけれども、実際は４月では３７０人です。しかもそのうち０から２歳児までは１８８人しか増えていないのです。１,０２９人しか入れていないのです。産休明けの人が軒並み入れない。内定がやっととれて仕事をしないと生活ができないのに入れない。どこにも入れない人、こういう人はどうしたらいいのかと聞いているのです。どんな選択肢があると考えているのか改めて伺います。","respondent":"金子子ども未来事業部長","answer":"先ほど申し上げましたとおり、認証保育所等々の施設あるいは年度内に今年はさらに３３９人の枠を確保しておるわけですので、こういったところにお申し込みいただいて、あるいは私ども等にご相談いただければ丁寧なご相談に応じたいと考えています。","voiceIndex":187,"id":"exchange-088"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"しかも年度内にできたことで足りるのでしょうか。去年の４月、８７０人が入れませんでした。そして、去年の１０月にはさらにそれを大きく上回ることがわかっていたわけです。だからこそ、私たち共産党区議団は何度も何度も、「４月に一人の子どもも路頭に迷わせないための緊急対策をとりなさい」と求めてきました。こんな状況になっていることに対して区としては反省がないのでしょうか、お聞きします。","respondent":"金子子ども未来事業部長","answer":"しかしながら、今年度、この数字でありますが、来年度に向けても広町２丁目の劇団四季の隣で区として開設しようという考えもありますので、さまざまな手法を検討して、今後とも積極的に取り組んでまいりたいと考えております。","voiceIndex":189,"id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１,１５４人が入れなかったと。私は、１,１５４人も待機児が出たということに対して、この人たちは、では一体どうしたらいいのかということで聞いているのです。ママたちの人生がかかっているわけです。こんなことがあっていいと考えているのか、改めて伺います。区長選挙が去年の１０月にありました。この公約に責任を持とうという思いはないのか、私は区長に伺いたいと思います。区長、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"待機児ゼロということでいろいろおっしゃっておりますけれども、これは区としての政策目標ですので、これに向けて努力していくということですので、そのようにご理解いただければと考えています。","voiceIndex":191,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"その緊急対策をしっかりとってくださいと、私たちは繰り返し求めてきたわけです。区立認可保育園、１００人規模の建設費はわずか２億５,０００万円です。運営費は２億円です。前年度の決算で区の基金は７７７億円ありました。これは福祉に使うべきお金ではないでしょうか。共産党が提案しています２０園増設は十分可能です。なぜ区が待機児ゼロに必要な認可保育園をつくらないのか、改めてお聞きします。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、本年度までこういった状況ではありますけれども、先ほど来申し上げていますとおり、来年度以降も保育の実施の責務というのは区にありますので、これについてはさまざまな手法を駆使して、総合的に対策をとっていき。","voiceIndex":193,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"児童福祉法第２４条で、「区は保育を必要とする子どもを保育所において保育しなければならない」と、区の責務を定めています。この責務を怠っていると私は指摘せざるを得ません。区が責任を持って、緊急対策と抜本対策をとることを強く求めます。もう一つ伺いたいのが待機児童の数え方です。なぜこんなに違うのか、今年の不承諾通知は１,１５４人です。区の待機児童の数え方をお聞きします。","respondent":"金子子ども未来事業部長","answer":"待機児童の数え方というお尋ねですけれども、平成２６年度までは保育所入所待機児童ということで国から調査が参りまして、これについて回答するという形の数字でございました。","voiceIndex":195,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的な中身をお答えいただけなかったのですけれど、品川区の数え方が他区と違うところが、４月入園を申し込んだ人が、さらに５月の入園申し込みをし直さなければ待機児童に数えられないという点なのです。これは近隣区に聞きました。だから、実態と大きく違う待機児童の数になるのではないでしょうか。改めて５月申請者を待機児にするのはやめるべきだと思いますけれども、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":197,"id":"exchange-093"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ほかの区も、１年間有効というとり方なのです。だけど、５月にもう一回申請した人だけを待機児童に数えるというやり方はしていないのです。実態をあらわす待機児の数え方にすべきだということを指摘しておきます。次に保育の格差の問題を伺います。認可外保育園に絞って伺います。認可外保育園の区内の数、１人当たりの平米数と職員体制、補助金、保育料、立ち入り調査がどうなっているのか伺います。","respondent":"金子子ども未来事業部長","answer":"実態把握のための都と区のチェックということですけれども、認可外保育施設につきましては、東京都に指導権限がありますけれども、実際の立ち入り調査の場面では、区の職員も同行するようにしておりますので、区としても現状の把握に努めているところです。","voiceIndex":200,"id":"exchange-094"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"認可外は補助金なしですから、現場は本当に苦労していると思います。それから園に対して、認可保育園や小規模保育事業などに移行への援助をすべきではないかと思うのですが、いかがでしょうかということが２点目です。それから３点目として、やはりどこにも入れず、やむを得ず認可外保育所を利用せざるを得ない保護者に対して、認証保育と同様の保育料助成をすべきではないかと思いますが、いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"それから保護者に対しての助成ということですけれども、先ほども申し上げましたとおり、認可外保育施設、認証保育所を除くとさまざまな実態があります。ですので、これを一律に助成するというのは非常に現状としては難しいものであると考えているところです。","voiceIndex":202,"id":"exchange-095"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、格差のない保育のために、区が責任を持って取り組んでいただきたいと思います。最後に、ママたちが探し回ってもどこにも入れない。本当に、考えると夜も眠れない。こんな声を聞くたびに、本当に胸が痛みます。どの子も豊かにすくすく育つ権利を保障すべきです。区が責任を持って、希望する子どもを安心して預けられるよう、必要な数の認可保育園をつくることを求めて、共産党の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":204,"id":"exchange-096"},{"speaker":"須貝委員","kind":"質問","question":"介護対策についてお聞きします。東京への人口集中が進む中、厚生労働省は、全国で認知症を患う人の数が２０２５年には７００万人を超えると推計値を発表しました。６５歳以上の高齢者のうち５人に１人が認知症であるという計算となりますが、今介護などを支える人材の確保が難しくなっていると聞きますが、現状はどうなのでしょうか、お答えください。その現状についてもお答えください。","respondent":"榎本健康福祉事業部長","answer":"それはもちろん、新規採用のほうの人材もそうですけれども、区の福祉施設に勤めている職員のレベルアップ等の講座等も行いながら、人材のレベルアップに努めているところです。","voiceIndex":206,"id":"exchange-097"},{"speaker":"須貝委員","kind":"質問","question":"今、質問したのですが、まず介護現場の処遇について改善されているのでしょうかという質問をいたしましたので、もう一度お願いいたします。そして、また介護サービスを受ける方はますます増えていますが、その現状。実際、こういうふうに、こういう状態の方が増えているのだというケースがあると思うのですが、その辺について再度質問します。","respondent":"榎本健康福祉事業部長","answer":"要支援の方から要介護５までの方がいらっしゃいまして、なかなか事例というのは難しいのですけれども、最近見たところですと、重度では車椅子の方がかなり多くなってきていまして、車椅子での介護サービスをどういうふうにしていくかとか、そういう形になっていると思います。","voiceIndex":208,"id":"exchange-098"},{"speaker":"須貝委員","kind":"質問","question":"定着率も悪い。そして、現場の状況を見ると、介護を支える若者の介護離れやヘルパー不足が増える一方で、この都市部では高齢化が急速に進み、認知症高齢者がますます増えている現状に対して、区としてどう対処するお考えですか、教えてください。対応できないならば、介護される方がその入口でとめるような仕組みもつくらなければいけないと思うのですが、何か対策があれば教えてください。","respondent":"榎本健康福祉事業部長","answer":"それで、例えば介護学校であれば、２年生が１年生を教えて、きちんと先輩・後輩の中で伝えていくものは伝えていくという形になっておりますので、そのような形で品川区は進めていきたいと考えています。","voiceIndex":210,"id":"exchange-099"},{"speaker":"須貝委員","kind":"意見","question":"本当に増えていて大変だと思うのですが、我々、品川区内を歩いていて、気が付くのは、高齢者クラブ、それからシルバーセンターで活動している人たちは元気にやっております。町会活動にも参加されている方も元気です。もう認知症に入って、さらに要介護１、２になってしまったら、もうとまりません。やはりそういう仕組みというのは大事ではないかと思うのですが、ご見解をお聞かせください。","respondent":"榎本健康福祉事業部長","answer":"ただ、そうは申しましても、先ほどの認知症予防につながる習慣等は、閉じこもる前の方がやっていただければ、そのまま続けられるですので、閉じこもる方をさらに引っ張り出すということもやりますけれども、そこだけに重点を置けば全てがうまくいくというものではありませんので。","voiceIndex":212,"id":"exchange-100"},{"speaker":"須貝委員","kind":"質問・要望","question":"食事会でもいいです。毎日１０分でも２０分でも人と接する。頑張っていただきたいと思います。小中一貫教育制度を始めて１０年経ちましたが、いじめも不登校もなくなっていません。学校の授業だけでは学力が身につかないため、小学生から民間塾に通う子が増える一方、教育制度が変わらず安定している私立中学校に、品川区からも３割の子が進学しています。ここでお聞きします。それについてもお答えください。","respondent":"田村教育次長","answer":"それで、その結果を踏まえて、要するにわからないまま進級するのではなく、それをわかるような形でフォローしてやっているかというお尋ねなので、それは各学校、取組みを実施しております。","voiceIndex":214,"id":"exchange-101"},{"speaker":"須貝委員","kind":"質問","question":"さて、現在、区は小中一貫教育を進めています。子どもたちを９年間にわたって見守っているわけですから、学力定着度調査は小学５年生、６年生、そして中学２年生、３年生も毎年実施するべきではないのかお答えください。中学３年生は１０カ月後に高校受験がありますので、年度初めに本人の実力を計るためにも都立高校入学試験の過去問を実施したらどうか、お答えください。","respondent":"田村教育次長","answer":"過去問は、現実問題とすると、大体、都立高校の過去問は２学期までの間の授業の内容が出るということなので、どうしても、早くて夏休み以降ですか、各学校で都立高校の過去問を実施するということで、一律この時期にやるという考えは現在のところ持っておりません。","voiceIndex":216,"id":"exchange-102"},{"speaker":"須貝委員","kind":"意見","question":"中学生は各学期の中間と期末の計５回ですが、ミニテストは毎月２回あります。要するに、学力到達調査で５教科全てでやり、合格点を決めて合格するまで受け続けています。そして、宿題も出ていますし、３年になりますと、入試対策のプリントも出されています。他県の公立学校でも、このように実施し、成果を上げていますので、品川区でも可能ではないかと思いますが、お答えください。","respondent":"田村教育次長","answer":"それと、それ以外に、今年度もそうですが、勉強合宿ということで、宿泊型４校だとか通所型２校だとか、やはり品川区のやり方で、本当に習熟度別の学習も含めて、少人数学級も含めて、学力の進捗状況に合わせて緻密な取扱いをしているので。","voiceIndex":218,"id":"exchange-103"},{"speaker":"須貝委員","kind":"質問","question":"それで、中学３年生、もう受験間近の秋です。それでも１年生の問題が全然手につきません。そういう子を何人かお見受けいたしました。「どうしたんだ」と言ったら、「わからない」と。１つの教室でそういう現状を見たら、ちょっと、品川区教育委員会がやっていることは違うのではないかと。それが、学校、また教育委員会の仕事ではないのでしょうか。その辺について、もう一度、再度お答えください。","respondent":"田村教育次長","answer":"１万８,４９４人のそれぞれの多様性に合わせて教育を、義務教育ですから実施するというのが大きな使命なのです。","voiceIndex":220,"id":"exchange-104"},{"speaker":"須貝委員","kind":"質問","question":"義務教育の使命で、塾へ行っている子、それぞれ学校に、今、学校が補習をしていると、さらに頑張る子は偏差値の高い学校を目指す。ではどうやって、学校で努力しましたか、今、学校は学力の底上げに対してきちんと取り組んでいるのですかといったときに、では何を見ればいいのでしょうか。例えば僕らがたまたまそこで見た生徒は本当にまれな例なのでしょうか。そうではないと思います。","respondent":"田村教育次長","answer":"それで中学校の保護者は８２.５％が満足しているという、数値的に、別に誘導も何もしていない数字で出ているので、やはり品川区の取組みが、決しておごってはいけないですけれど、一定のご理解を得ているというふうな形で考えております。","voiceIndex":222,"id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"部活で満足。学校というのは勉強をするためにできたわけですから、それは大事にしてほしいと思います。そういうことも考えると、そういうお子さんがいて、学力が上がっている、評価が上がっているということも私はきちんと、塾にどれだけの子が通っているのだということを把握する必要があると思うし、学習指導も、それを見きわめてきちんとする必要があると思いますが、ご見解をお聞かせください。","respondent":"田村教育次長","answer":"それと、塾のお話をしますけれど、毎回これもご答弁していますけれど、各中学校は当然、授業中の様子や小テスト、あるいは定期考査だとか、あるいは高校入試の時点での卒業生の定期考査と高校入試の時点での相関関係を、今までの累積の結果がありますので。","voiceIndex":224,"id":"exchange-106"},{"speaker":"須貝委員","kind":"質問・要望","question":"蓄積とおっしゃいますが、現状、学力もそれぞれ、みんな変わっております。やはりそうではなくて、的確な最新のデータを私は見ていただきたいと思います。子どもたちにはさまざまな夢があります。その夢を実現させるためには、ある程度の学力は必要だと考えます。厳しい実社会で生き抜いていけるように、確かな学力を身につけさせる教育をするべきだと思います。以上で無所属品川の総括質疑を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-107"},{"speaker":"伊藤委員","kind":"提案","question":"本委員会で我が会派委員が指摘・提案・質問した全庁共通プロジェクト、大崎駅周辺地区再開発、地域包括支援センター、ＪＲ広町アパート跡地再開発、マイナンバーカード、品川区としての危機管理、総合教育会議、災害時の障害者支援・自立支援、航空機騒音測定、羽田空港機能強化に対する対応、観光アクションプラン、擁壁調査、品川区研究校、学校選択制等は、今後の品川区政推進の羅針盤となるものであり。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":229,"id":"exchange-108"},{"speaker":"浅野委員","kind":"提案","question":"東日本大震災の発生から４年目を迎え、昨年に引き続き、防災対策の強化、災害に強いまちづくりを重点課題と位置づけ、木密地域不燃化１０年プロジェクト事業の対象地区に新たに３地区を加え、合計９地区を事業対象として木造住宅密集地域の改善を推進、ＪＴアパート跡地をしながわ中央公園として拡張して、ヘリポートや防災備蓄倉庫などの整備の実施、津波や浸水などへの対策として津波避難施設の確保。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":231,"id":"exchange-109"},{"speaker":"いながわ委員","kind":"提案","question":"国の施策である地域住民生活等緊急支援を活用したプレミアム付区内共通商品券の発行では、幅広い区民がより多くの商店で利用できる仕組みを求めます。引き続きの充実を要望いたします。さらに実現に向けて、今回の予算特別委員会において我が会派の所属委員が質問の中で指摘・提案した各項目を真摯に受けとめ、予算執行することを強く要望し、民主・改革ネットの意見表明といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":233,"id":"exchange-110"},{"speaker":"南委員","kind":"質問・要望","question":"消費税の８％増税と、実質賃金の１９カ月連続マイナス、社会保障の解体など、国の悪政から区民の暮らしを守る防波堤として自治体の役割を果たすことが求められます。この方向へ区政を抜本的に転換するよう求めます。上大崎の跡地のさらなる特別養護老人ホーム増設計画の具体化を求めます。第３は教育の問題です。子どもの豊かな学びを保障するために、３０人学級など、教育環境の整備を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":235,"id":"exchange-111"},{"speaker":"須貝委員","kind":"質問・要望","question":"平成２７年度予算に対する無所属品川の意見表明を行います。無所属品川は、平成２７年度の品川区一般会計、国民健康保険事業会計、後期高齢者医療特別会計、介護保険特別会計の各予算に賛成いたします。防災対策や医療・介護・子育ての予算は年々上昇し、財政負担も増え続けていますが、今こそ継続的かつ大規模な緊急経済対策を行うとともに、生活弱者である区民生活の支援を拡充していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":237,"id":"exchange-112"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1032#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":104087,"voices":242}},{"id":"h27-20150318-7","meetingId":"h27-cm03","date":"2015年3月18日","dateIso":"2015-03-18","committee":"厚生委員会","time":"午前１０時００分～午前１０時５６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第４６号議案、品川区国民健康保険条例の一部を改正する条例","agenda":"第４６号議案、品川区国民健康保険条例の一部を改正する条例","exchanges":[{"speaker":"伊藤委員","kind":"確認","question":"おそらくレセプトを１円からとするとか、そういうことになってくると思うのだけれども、決して全体を反対するわけではないのだけれども、これからこの保険を考えていくときに、やっぱり適正な治療が展開されているかということ、鈴木委員がいる前で申し訳ないのだけれども、それをどこかで見ていかないと、ただただ増え続けていくだけであって。","respondent":"高森国保医療年金課長","answer":"委員おっしゃられているように確かに一つの課題としては、今お話しいただいた内容というのはこれからさまざまな形で、都道府県化になったりいろいろな形の流れの中で、もう一度検討課題ということにさせていただきたいと思います。よろしくお願いします。","voiceIndex":5,"id":"exchange-001"},{"speaker":"伊藤委員","kind":"質問・要望","question":"簡単な問題ではないと思いながら質問するのですけれども、どうしても高齢化になることは避けられない事実だから、こういう社会保障制度そのものの根底がどんどん厳しくなっていくことはわかるのですよ。だけれども、出ていくものに対して、ある程度の確認をする仕組みもあったらいいのではないかなという思いがありますので、もう一言お答えいただきたい。","respondent":"高森国保医療年金課長","answer":"そういう方については、品川区のほうから直接被保険者に対して警告を兼ねて文書を発送するなりして、現状ではそういう形で進めさせていただいているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"たけうち委員","kind":"質問","question":"３ページの２．保険財政共同安定化事業の拡大ということで、３０万円超から１円以上、ちょっとここがよくわからないので、もう一回詳しいご説明をいただいていいでしょうか。","respondent":"高森国保医療年金課長","answer":"すみません、ちょっと説明不足で申し訳ございません。６ページをご覧いただきたいと思います。","voiceIndex":10,"id":"exchange-003"},{"speaker":"たけうち委員","kind":"質問","question":"イメージは何となくそうなのだろうなと思ったのですが、そうすると、区市町村としてはプラスの方向というか、安定化の拡大なのだから、財源としては今までよりも多く入ってくるということでよろしいのですか。","respondent":"高森国保医療年金課長","answer":"予算上の話で恐縮ですけれども、平成２６年度まではたしか３２億円ぐらい拠出していまして、見込みでは、同額に２,０００万円ぐらい乗った形で戻ってくるような見込みを立ててあります。","voiceIndex":12,"id":"exchange-004"},{"speaker":"たけうち委員","kind":"質問","question":"一応わかりました。それから、先ほどあった平成３０年度から都道府県化ということなのですけれども、これについては今、都道府県化ということなので東京都、２３区で同じ保険料率でやっているところを、今度はいわゆる市町村というのですか、三多摩というのですかね、そちらのほうとあわせていくということになるわけですよね。そこと保険料を一緒にしていくと、そういう考えになるのでしょうか。","respondent":"高森国保医療年金課長","answer":"もともと東京都は全部統一保険料みたいな、東京都が保険者になるわけですから、そういうふうなイメージを持っていたのですけれども、保険料については分賦金方式ということで、例えば、もっと言ってしまいますと、２３区は今保険料という扱いになっているわけですけれども。","voiceIndex":14,"id":"exchange-005"},{"speaker":"たけうち委員","kind":"質問","question":"まだ決定していないからあれなのでしょうけれども、そうすると、イメージとしては、今２３区は同じ保険料なわけですよね、それは変わらずにいて、なおかつ、わからないですけれども、市町村分のものまで、どちらかというと２３区のほうで少し負担してあげると、そういうイメージなのですか。","respondent":"高森国保医療年金課長","answer":"その負担するというイメージというのは、後期高齢者広域連合の関係はそういう形になっていますけれども、今の段階では負担をしてあげるというよりそこは切り離しているというイメージで、ただこれから東京都と特別区２３区のほうの関係で。","voiceIndex":16,"id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問・要望","question":"最後に要望ですけれども、おそらくまた６月、７月ぐらいになると窓口に大勢の方が、いつも通るといらっしゃって、いろいろやっぱり、これ自体は致し方ないというふうに僕は理解していますけれども、やっぱり上がった方はそれぞれ総論賛成だけど、各論になると、自分に当てはまると保険料がかなり上がるということで、窓口で何でだと、こういうご説明を求める方も当然いらっしゃると思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１１ページのモデルケースのところで、一番下の３人世帯、世帯主だけ収入があるというところで、２００万円のところが２万２,０９１円、平成２６年度の保険料と比較するとこれだけ上がると結構な、大幅な値上げかなと感じるのですけれども、この間、旧ただし書き方式になったことで、軽減措置、多分この２００万円の方は非課税だと思うのですけれども。","respondent":"高森国保医療年金課長","answer":"二つの質問で、一つ目のほうの介護納付金の関係ですけれども、こちらにつきましては、厚生労働省のほうから示されております計算をする諸係数というのがあるのですけれども、それに基づいて私どものほうのここで介護納付金を記載していますのは。","voiceIndex":19,"id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"それで、これから高額療養費のほうも一般財源の投入をやめて、これを保険料に転嫁していくということで、これが今回２年目と、４年間でなくしていくというものの今回２年目で、それを４分の１ずつ保険料に充てていくというところで、先ほど１人平均で９,０００円、これを４分の１にすると２,２００円ということだったのですけれども、その額がそのまま３.３４％。","respondent":"高森国保医療年金課長","answer":"保険料を確かに毎年のように改定をさせていただいている状況ですが、これは医療費総額が本当に伸びておりまして、大体３.９％ぐらい伸びている状況ですので、さまざまな形で国から、都から、区からということで、または支援金等をいただきながら。","voiceIndex":21,"id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"医療費の総額が上がっているということですけれども、やっぱり国保の抱える問題としては、構造的な課題というのがずっと言われていると思うのです。ですので、こういったところをどう考えられているのかなというのをちょっとお聞かせください。","respondent":"高森国保医療年金課長","answer":"平成２９年度からも１,７００億円、合計で３,４００億円を国保の財政基盤の安定化のために入れてくるというふうな状況で、この間新聞報道で出ておりましたけれども、そういう形で国は国なりにいろいろな形で安定、いわゆる安定というのは行政側から見た安定だけではなく。","voiceIndex":23,"id":"exchange-010"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"国保加入者が、全国で見ると平均所得がどんどん減ってきている状況ですよね。２０１２年で言うと、国保加入者の平均所得が１４１万円です、区内で言うとどうかはちょっとわからないですけれども。ですので、払える保険料にしていかないことには、持続可能性もなくなっていくのではないかと思うのですけれども、そこはいかがでしょうか。","respondent":"高森国保医療年金課長","answer":"委員おっしゃるように、ただ、平成２７年度からまた７割、５割、２割ということで、これは見直しということで軽減税率、いわゆる控除額を引き上げることによりまして、収入が少し多くなった方でも取り込める形で。","voiceIndex":25,"id":"exchange-011"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"一般財源の投入を高額療養費でやめていくというのも本当に大変なことだなと思うのですけれども、大もとはやっぱり国庫負担が減らされたというのが、これだけ国保料がどーんと跳ね上がっていく大もとの原因だと思うのですけれども、やはり、そこからさらに一般財源までも引き払ってしまうというところでは、負担増を本当に強いているなというふうに思うのですけれども。","respondent":"高森国保医療年金課長","answer":"ただ、そのほかのところを見ますと、１.０１だとか、また１.００だとか、いろいろな形でなるべく負担がかからないようにというふうな形で線引きをさせていただきながら今回提案させていただいている状況でございまして。","voiceIndex":27,"id":"exchange-012"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"あくまでもこれはモデルケースですので、本当に各世帯に当てていくと、どれだけの世帯が値上がっていくかというのがわかると思うのですね。ですので、本当に引き下げこそしてほしいと私は思うのです。それで最後に、国保の短期証とかの件数をちょっと教えていただきたいと思います。平成２６年度で短期証と資格証の発行件数、あと差し押さえ件数を教えてください。","respondent":"高森国保医療年金課長","answer":"平成２６年の１０月現在の資料がありますので、それで報告しますが、短期証の対象世帯数は３,７１５世帯でございまして、資格証の世帯は１３１世帯です。平成２５年度の差し押さえ件数は３９４件で、平成２６年度は１月末現在で４８５件です。","voiceIndex":29,"id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"短期証と差し押さえのところで増えている状況ですよね。この間話を聞かせてもらっているところでは、なかなか連絡がとれず何回とってもとれないというお宅には差し押さえをしているという状況だと思うのですけれども、この差し押さえで収納率が上がっているという状況、そういう関係なのでしょうか。","respondent":"高森国保医療年金課長","answer":"ただ、実際に連絡がとれない方も多々いらっしゃいますけれども、原則は大変申し訳ない言い方になるかもしれませんが、私どものほうは、６月に保険料を賦課させていただきまして、収入が著しく困窮されている方であればご相談をいただいて。","voiceIndex":31,"id":"exchange-014"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"以前、前の課長にお聞きしたときには、差し押さえすることでびっくりして連絡をしてくるのだというようなことも言われたことがあったのです。ですので、そういった部分をしっかり見ていただきたいと思うのです。そこを見つけ出すというのがなかなか難しいと思うのですけれども、そこは本当に粘り強くやっていただきたいと思います。差し押さえを突然するということはしないでいただきたいなと思います。","respondent":"榎本健康福祉事業部長","answer":"基本的にはかなり長い期間、半年以上は滞納している、もしくは経過をして、分納約束をしたのにそれができていないとか、そういう特殊事情があるときに最終的に差し押さえをするという形ですので、ご相談いただければ。","voiceIndex":33,"id":"exchange-015"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"特殊事例だけで、この４８５件ということなのですか。やはり、そうではないところでも、差し押さえがされているという状況をちょっと耳にするので、そういった乱暴な差し押さえはすべきでないというふうに申し上げたのですけれども、これは全て特殊事例ということでしょうか。","respondent":"高森国保医療年金課長","answer":"今部長から話がありましたように、滞納して３ヶ月ぐらいで差し押さえ、実は法令上は、督促期限を過ぎた後納付がない場合は滞納処分しなければならないという国税徴収法の規定がございまして、私どものほうも地方税法を介して。","voiceIndex":35,"id":"exchange-016"},{"speaker":"伊藤委員","kind":"意見","question":"本議案に賛成いたします。ただ、品川区にお願いしたいのは、ぜひ懇切丁寧な説明を、特に大きく変更する場合があるわけでありますから、そういう個々の方々に対しては十分な説明とご理解していただくことをお願いしておきまして、賛成いたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"やはり、国保加入者の現状が大変厳しくなっている中で、高齢化も進んで、そして収入減も進んでいるというもとでは、払える国保料にしていくべきだと思いますので、さらなる値上げというのは私は反対です。年金も下げられて、介護保険料も値上がって、さらに国保まで値上がる、本当に払い切れないと思います。そういった思いに応えて、一般財源の投入をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3412#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2015-01-01&TermEnd=2015-12-31"}],"sourceMeta":{"pages":0,"characters":18958,"voices":49}}]);
